INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('752f84a6-887d-46e2-b8cf-b18645289e89', '過宋員外之問舊莊', '過宋員外之问旧莊', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["宋公舊池館，零落守陽阿。","枉道祗從入，吟詩許更過。","淹留問耆老，寂莫向山河。","更識將軍樹，悲風日暮多。"]', '["宋公旧池館，零落守陽阿。","枉道祗從入，吟诗許更過。","淹留问耆老，寂莫向山河。","更識將軍樹，悲风日暮多。"]', '诗', 'shi', '', NULL, '過宋員外之問舊莊 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43ca0051-95f4-4bbb-8171-09b420f4b3e3', '夜宴左氏莊', '夜宴左氏莊', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["風林纖月落，衣露淨琴張。","暗水流花徑，春星帶草堂。","檢書燒燭短，看劒引杯長。","詩罷聞吳詠，扁舟意不忘。"]', '["风林纖月落，衣露淨琴張。","暗水流花徑，春星带草堂。","檢书燒燭短，看劒引杯长。","诗罷闻吳詠，扁舟意不忘。"]', '诗', 'shi', '', NULL, '夜宴左氏莊 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d89d155-45a6-432d-a873-d00d2917c366', '送蔡希曾都尉還隴右因寄高三十五書記', '送蔡希曾都尉還隴右因寄高三十五书記', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["蔡子勇成癖，彎弓西射胡。","健兒寧鬬死，壯士恥爲儒。","官是先鋒得，材緣挑戰須。","身輕一鳥過，槍急萬人呼。","雲幕隨開府，春城赴上都。","馬頭金狎帢，駝背錦糢糊。","咫尺雲山路，歸飛青海隅。","上公猶寵錫，突將且前驅。","漢使黃河遠，涼州白麥枯。","因君問消息，好在阮元瑜。"]', '["蔡子勇成癖，彎弓西射胡。","健兒寧鬬死，壯士恥爲儒。","官是先鋒得，材緣挑戰須。","身轻一鸟過，槍急万人呼。","云幕隨开府，春城赴上都。","马头金狎帢，駝背錦糢糊。","咫尺云山路，归飞青海隅。","上公猶寵錫，突將且前驱。","漢使黄河远，涼州白麦枯。","因君问消息，好在阮元瑜。"]', '诗', 'shi', '', NULL, '送蔡希曾都尉還隴右因寄高三十五書記 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('571a9d34-1572-42f4-bb50-96c4d88974b4', '春日憶李白', '春日憶李白', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["白也詩無敵，飄然思不羣。","清新庾開府，俊逸鮑參軍。","渭北春天樹，江東日暮雲。","何時一尊酒，重與細論文。"]', '["白也诗無敵，飄然思不羣。","清新庾开府，俊逸鲍參軍。","渭北春天樹，江东日暮云。","何时一尊酒，重與細論文。"]', '诗', 'shi', '', NULL, '春日憶李白 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e07d2690-df2b-40db-a730-409d0ccf2263', '贈陳二補闕', '贈陳二補闕', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["世儒多汩沒，夫子獨聲名。","獻納開東觀，君王問長卿。","皁雕寒始急，天馬老能行。","自到青冥裏，休看白髮生。"]', '["世儒多汩沒，夫子独声名。","獻納开东观，君王问长卿。","皁雕寒始急，天马老能行。","自到青冥裏，休看白髮生。"]', '诗', 'shi', '', NULL, '贈陳二補闕 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a04ffb1-5b06-412e-8cbb-d021aaff929c', '寄高三十五書記', '寄高三十五书記', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["歎惜高生老，新詩日又多。","美名人不及，佳句法如何。","主將收才子，崆峒足凱歌。","聞君已朱紱，且得慰蹉跎。"]', '["歎惜高生老，新诗日又多。","美名人不及，佳句法如何。","主將收才子，崆峒足凱歌。","闻君已朱紱，且得慰蹉跎。"]', '诗', 'shi', '', NULL, '寄高三十五書記 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('707956ea-1893-4d4b-81f0-2d0786647e46', '送裴二虯作尉永嘉', '送裴二虯作尉永嘉', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["孤嶼亭何處，天涯水氣中。","故人官就此，絕境興誰同。","隱吏逢梅福，遊山憶謝公。","扁舟吾已就，把釣待秋風。"]', '["孤嶼亭何处，天涯水氣中。","故人官就此，絕境兴誰同。","隐吏逢梅福，游山憶謝公。","扁舟吾已就，把釣待秋风。"]', '诗', 'shi', '', NULL, '送裴二虯作尉永嘉 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2646aa96-72fd-42bf-9671-83924dbb4236', '城西陂泛舟', '城西陂泛舟', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["青蛾皓齒在樓船，橫笛短簫悲遠天。","春風自信牙檣動，遲日徐看錦纜牽。","魚吹細浪搖歌扇，燕蹴飛花落舞筵。","不有小舟能蘯槳，百壺那送酒如泉。"]', '["青蛾皓齒在楼船，橫笛短簫悲远天。","春风自信牙檣动，遲日徐看錦纜牽。","鱼吹細浪搖歌扇，燕蹴飞花落舞筵。","不有小舟能蘯槳，百壺那送酒如泉。"]', '诗', 'shi', '', NULL, '城西陂泛舟 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e8e3a49-7135-4e53-94a1-524f3801d40e', '贈田九判官', '贈田九判官', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["崆峒使節上青霄，河隴降王款聖朝。","宛馬總肥春苜蓿，將軍只數漢嫖姚。","陳留阮瑀誰爭長，京兆田郎早見招。","麾下賴君才竝入，獨能無意向漁樵。"]', '["崆峒使節上青霄，河隴降王款聖朝。","宛马總肥春苜蓿，將軍只數漢嫖姚。","陳留阮瑀誰爭长，京兆田郎早见招。","麾下賴君才竝入，独能無意向漁樵。"]', '诗', 'shi', '', NULL, '贈田九判官 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03b5716c-b741-411d-a388-b2f3fab090e1', '贈獻納使起居田舍人', '贈獻納使起居田舍人', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["獻納司存雨露邊，地分清切任才賢。","舍人退食收封事，宮女開函近御筵。","曉漏追飛青瑣闥，晴窗點檢白雲篇。","揚雄更有河東賦，唯待吹噓送上天。"]', '["獻納司存雨露邊，地分清切任才賢。","舍人退食收封事，宮女开函近御筵。","晓漏追飞青瑣闥，晴窗点檢白云篇。","揚雄更有河东賦，唯待吹噓送上天。"]', '诗', 'shi', '', NULL, '贈獻納使起居田舍人 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3a5cf75-a207-4e84-8579-c48c16317966', '送韋書記赴安西', '送韋书記赴安西', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["夫子歘通貴，雲泥相望懸。","白頭無藉在，朱紱有哀憐。","書記赴三捷，公車留二年。","欲浮江海去，此別意蒼然。"]', '["夫子歘通貴，云泥相望懸。","白头無藉在，朱紱有哀怜。","书記赴三捷，公车留二年。","欲浮江海去，此別意蒼然。"]', '诗', 'shi', '', NULL, '送韋書記赴安西 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e325ad6-d00a-4ed2-8d87-849bb63a2efa', '陪鄭廣文遊何將軍山林十首 一', '陪鄭廣文游何將軍山林十首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["不識南塘路，今知第五橋。","名園依綠水，野竹上青霄。","谷口舊相得，濠梁同見招。","平生爲幽興，未惜馬蹄遙。"]', '["不識南塘路，今知第五橋。","名园依綠水，野竹上青霄。","谷口旧相得，濠梁同见招。","平生爲幽兴，未惜马蹄遙。"]', '诗', 'shi', '', NULL, '陪鄭廣文遊何將軍山林十首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7881ef4b-b7ae-4a62-9681-2ff7050dfb20', '陪鄭廣文遊何將軍山林十首 二', '陪鄭廣文游何將軍山林十首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["百頃風潭上，千重夏木清。","卑枝低結子，接葉暗巢鶯。","鮮鯽銀絲膾，香芹碧澗羹。","飜疑柁樓底，晚飯越中行。"]', '["百頃风潭上，千重夏木清。","卑枝低結子，接葉暗巢鶯。","鲜鯽銀絲膾，香芹碧澗羹。","飜疑柁楼底，晚飯越中行。"]', '诗', 'shi', '', NULL, '陪鄭廣文遊何將軍山林十首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51ac3a6e-d8ae-4286-b3f0-9b6448e1b138', '陪鄭廣文遊何將軍山林十首 三', '陪鄭廣文游何將軍山林十首 三', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["萬里戎王子，何年別月支。","異花開絕域，滋蔓匝清池。","漢使徒空到，神農竟不知。","露飜兼雨打，開坼日離披。"]', '["万里戎王子，何年別月支。","異花开絕域，滋蔓匝清池。","漢使徒空到，神農竟不知。","露飜兼雨打，开坼日離披。"]', '诗', 'shi', '', NULL, '陪鄭廣文遊何將軍山林十首 三 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d34ad9f8-018c-4f05-b19a-8fd388b39165', '陪鄭廣文遊何將軍山林十首 四', '陪鄭廣文游何將軍山林十首 四', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["旁舍連高竹，疎籬帶晚花。","碾渦深沒馬，藤蔓曲藏蛇。","詞賦工無益，山林跡未賒。","盡捻書籍賣，來問爾東家。"]', '["旁舍連高竹，疎籬带晚花。","碾渦深沒马，藤蔓曲藏蛇。","词賦工無益，山林跡未賒。","尽捻书籍賣，来问爾东家。"]', '诗', 'shi', '', NULL, '陪鄭廣文遊何將軍山林十首 四 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('acddc789-88a1-42a4-a12a-f5a6830c7432', '陪鄭廣文遊何將軍山林十首 五', '陪鄭廣文游何將軍山林十首 五', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["賸水滄江破，殘山碣石開。","綠垂風折筍，紅綻雨肥梅。","銀甲彈箏用，金魚換酒來。","興移無灑埽，隨意坐莓苔。"]', '["賸水滄江破，殘山碣石开。","綠垂风折筍，紅綻雨肥梅。","銀甲彈箏用，金鱼換酒来。","兴移無灑埽，隨意坐莓苔。"]', '诗', 'shi', '', NULL, '陪鄭廣文遊何將軍山林十首 五 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f6db6d9-e276-4da3-9e9e-06d1d3f75bd2', '陪鄭廣文遊何將軍山林十首 六', '陪鄭廣文游何將軍山林十首 六', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["風磴吹陰雪，雲門吼瀑泉。","酒醒思臥簟，衣冷欲裝綿。","野老來看客，河魚不取錢。","只疑淳樸處，自有一山川。"]', '["风磴吹陰雪，云门吼瀑泉。","酒醒思臥簟，衣冷欲裝綿。","野老来看客，河鱼不取錢。","只疑淳樸处，自有一山川。"]', '诗', 'shi', '', NULL, '陪鄭廣文遊何將軍山林十首 六 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5226fbe5-7035-4c09-9baa-ce4fc9009bfa', '陪鄭廣文遊何將軍山林十首 七', '陪鄭廣文游何將軍山林十首 七', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["棘樹寒雲色，茵蔯春藕香。","脆添生菜美，陰益食單涼。","野鶴清晨出，山精白日藏。","石林蟠水府，百里獨蒼蒼。"]', '["棘樹寒云色，茵蔯春藕香。","脆添生菜美，陰益食單涼。","野鹤清晨出，山精白日藏。","石林蟠水府，百里独蒼蒼。"]', '诗', 'shi', '', NULL, '陪鄭廣文遊何將軍山林十首 七 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29be806c-b27a-4050-a2a6-8c69a1eebf5f', '陪鄭廣文遊何將軍山林十首 八', '陪鄭廣文游何將軍山林十首 八', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["憶過楊柳渚，走馬定昆池。","醉把青荷葉，狂遺白接䍦。","刺船思郢客，解水乞吳兒。","坐對秦山晚，江湖興頗隨。"]', '["憶過楊柳渚，走马定昆池。","醉把青荷葉，狂遺白接䍦。","刺船思郢客，解水乞吳兒。","坐对秦山晚，江湖兴頗隨。"]', '诗', 'shi', '', NULL, '陪鄭廣文遊何將軍山林十首 八 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14b59e7e-8085-40bd-89eb-9c83003ce625', '陪鄭廣文遊何將軍山林十首 九', '陪鄭廣文游何將軍山林十首 九', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["牀上書連屋，階前樹拂雲。","將軍不好武，稚子總能文。","醒酒微風入，聽詩靜夜分。","絺衣挂蘿薜，涼月白紛紛。"]', '["牀上书連屋，階前樹拂云。","將軍不好武，稚子總能文。","醒酒微风入，听诗静夜分。","絺衣挂蘿薜，涼月白紛紛。"]', '诗', 'shi', '', NULL, '陪鄭廣文遊何將軍山林十首 九 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ef037cc-4fa7-4feb-955a-a454ca3713a2', '陪鄭廣文遊何將軍山林十首 十', '陪鄭廣文游何將軍山林十首 十', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["幽意忽不愜，歸期無奈何。","出門流水注，回首白雲多。","自笑燈前舞，誰憐醉後歌。","祗應與朋好，風雨亦來過。"]', '["幽意忽不愜，归期無奈何。","出门流水注，回首白云多。","自笑灯前舞，誰怜醉後歌。","祗應與朋好，风雨亦来過。"]', '诗', 'shi', '', NULL, '陪鄭廣文遊何將軍山林十首 十 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46381f44-e44c-44e1-8d3d-fa0313757063', '重過何氏五首 一', '重過何氏五首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["問訊東橋竹，將軍有報書。","倒衣還命駕，高枕乃吾廬。","花妥鶯捎蝶，溪喧獺趁魚。","重來休沐地，真作野人居。"]', '["问訊东橋竹，將軍有報书。","倒衣還命駕，高枕乃吾廬。","花妥鶯捎蝶，溪喧獺趁鱼。","重来休沐地，真作野人居。"]', '诗', 'shi', '', NULL, '重過何氏五首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dcac42cf-0623-45f1-98d7-9f710dec8863', '重過何氏五首 二', '重過何氏五首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["山雨尊仍在，沙沈榻未移。","犬迎曾宿客，鴉護落巢兒。","雲薄翠微寺，天清黃子陂。","向來幽興極，步屣過東籬。"]', '["山雨尊仍在，沙沈榻未移。","犬迎曾宿客，鴉護落巢兒。","云薄翠微寺，天清黄子陂。","向来幽兴極，步屣過东籬。"]', '诗', 'shi', '', NULL, '重過何氏五首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66369c6e-ff5b-49e3-b2c9-4ec90030ee6f', '重過何氏五首 三', '重過何氏五首 三', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["落日平臺上，春風啜茗時。","石闌斜點筆，桐葉坐題詩。","翡翠鳴衣桁，蜻蜓立釣絲。","自今幽興熟，來往亦無期。"]', '["落日平台上，春风啜茗时。","石闌斜点笔，桐葉坐題诗。","翡翠鳴衣桁，蜻蜓立釣絲。","自今幽兴熟，来往亦無期。"]', '诗', 'shi', '', NULL, '重過何氏五首 三 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5730ab68-4012-414b-916a-748fc81583e3', '重過何氏五首 四', '重過何氏五首 四', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["頗怪朝參嬾，應耽野趣長。","雨拋金鎖甲，苔臥綠沈槍。","手自移蒲柳，家纔足稻粱。","看君用幽意，白日到羲皇。"]', '["頗怪朝參嬾，應耽野趣长。","雨拋金鎖甲，苔臥綠沈槍。","手自移蒲柳，家纔足稻粱。","看君用幽意，白日到羲皇。"]', '诗', 'shi', '', NULL, '重過何氏五首 四 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b147516-e870-4934-96da-02ee91b0046b', '重過何氏五首 五', '重過何氏五首 五', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["到此應常宿，相留可判年。","蹉跎暮容色，悵望好林泉。","何路霑微祿，歸山買薄田。","斯遊恐不遂，把酒意茫然。"]', '["到此應常宿，相留可判年。","蹉跎暮容色，悵望好林泉。","何路霑微祿，归山買薄田。","斯游恐不遂，把酒意茫然。"]', '诗', 'shi', '', NULL, '重過何氏五首 五 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2e105eb-bf47-46ea-b2d3-fc6e0613e869', '冬日有懷李白', '冬日有懷李白', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["寂寞書齋裏，終朝獨爾思。","更尋嘉樹傳，不忘角弓詩。","短褐風霜入，還丹日月遲。","未因乘興去，空有鹿門期。"]', '["寂寞书斋裏，終朝独爾思。","更尋嘉樹傳，不忘角弓诗。","短褐风霜入，還丹日月遲。","未因乘兴去，空有鹿门期。"]', '诗', 'shi', '', NULL, '冬日有懷李白 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75f08978-8abb-4b09-82b7-30f90ce56d68', '杜位宅守歲', '杜位宅守歲', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["守歲阿戎家，椒盤已頌花。","盍簪喧櫪馬，列炬散林鴉。","四十明朝過，飛騰暮景斜。","誰能更拘束，爛醉是生涯。"]', '["守歲阿戎家，椒盤已頌花。","盍簪喧櫪马，列炬散林鴉。","四十明朝過，飞腾暮景斜。","誰能更拘束，爛醉是生涯。"]', '诗', 'shi', '', NULL, '杜位宅守歲 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2e67053-fb77-4b11-8dde-9c726aaa7ec0', '與鄠縣源大少府宴渼陂', '與鄠縣源大少府宴渼陂', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["應爲四陂好，金錢罄一餐。","飯抄雲子白，瓜嚼水精寒。","無計迴船下，空愁避酒難。","主人情爛熳，持荅翠琅玕。"]', '["應爲四陂好，金錢罄一餐。","飯抄云子白，瓜嚼水精寒。","無計迴船下，空愁避酒难。","主人情爛熳，持荅翠琅玕。"]', '诗', 'shi', '', NULL, '與鄠縣源大少府宴渼陂 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c811630-909b-4aa3-ac92-db90021e132d', '崔駙馬山亭宴集', '崔駙马山亭宴集', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["蕭史幽棲地，林間蹋鳳毛。","洑流何處入，亂石閉門高。","客醉揮金椀，詩成得繡袍。","清秋多宴會，終日困香醪。"]', '["蕭史幽棲地，林间蹋鳳毛。","洑流何处入，亂石閉门高。","客醉揮金椀，诗成得繡袍。","清秋多宴會，終日困香醪。"]', '诗', 'shi', '', NULL, '崔駙馬山亭宴集 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81c3df1e-6db1-43ab-8b2e-1fa9490f6531', '九日楊奉化會白水崔明府', '九日楊奉化會白水崔明府', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["今日潘懷縣，同時陸浚儀。","坐開桑落酒，來把菊花枝。","天宇清霜淨，公堂宿霧披。","晚酣留客舞，鳧舄共差池。"]', '["今日潘懷縣，同时陸浚儀。","坐开桑落酒，来把菊花枝。","天宇清霜淨，公堂宿霧披。","晚酣留客舞，鳧舄共差池。"]', '诗', 'shi', '', NULL, '九日楊奉化會白水崔明府 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e49af687-a500-425c-a9cb-0e7816bbb04e', '贈翰林張四學士', '贈翰林張四学士', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["翰林逼華蓋，鯨力破滄溟。","天上張公子，宮中漢客星賦詩拾翠殿，佐酒望雲亭。","紫誥仍兼綰，黃麻似六經。","內分金帶赤，恩與荔枝青。","無復隨高鳳，空餘泣聚螢。","此生任春草，垂老獨漂萍。","儻憶山陽會，悲歌在一聽。"]', '["翰林逼华蓋，鯨力破滄溟。","天上張公子，宮中漢客星賦诗拾翠殿，佐酒望云亭。","紫誥仍兼綰，黄麻似六經。","內分金带赤，恩與荔枝青。","無复隨高鳳，空餘泣聚螢。","此生任春草，垂老独漂萍。","儻憶山陽會，悲歌在一听。"]', '诗', 'shi', '', NULL, '贈翰林張四學士 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f847798-230a-4e1b-946f-5ae62cfad00b', '送張二十參軍赴蜀州因呈楊五侍御', '送張二十參軍赴蜀州因呈楊五侍御', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["好去張公子，通家別恨添。","兩行秦樹直，萬點蜀山尖。","御史新驄馬，參軍舊紫髯。","皇華吾善處，於汝定無嫌。"]', '["好去張公子，通家別恨添。","兩行秦樹直，万点蜀山尖。","御史新驄马，參軍旧紫髯。","皇华吾善处，於汝定無嫌。"]', '诗', 'shi', '', NULL, '送張二十參軍赴蜀州因呈楊五侍御 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86d084a1-6ccd-49a1-8757-cebc29ef13e8', '陪諸貴公子丈八溝攜妓納涼晚際遇雨二首 一', '陪諸貴公子丈八溝携妓納涼晚際遇雨二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["落日放船好，輕風生浪遲。","竹深留客處，荷淨納涼時。","公子調冰水，佳人雪藕絲。","片雲頭上黑，應是雨催詩。"]', '["落日放船好，轻风生浪遲。","竹深留客处，荷淨納涼时。","公子調冰水，佳人雪藕絲。","片云头上黑，應是雨催诗。"]', '诗', 'shi', '', NULL, '陪諸貴公子丈八溝攜妓納涼晚際遇雨二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('faada38b-ba84-4066-b426-10159e66011b', '陪諸貴公子丈八溝攜妓納涼晚際遇雨二首 二', '陪諸貴公子丈八溝携妓納涼晚際遇雨二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["雨來霑席上，風急打船頭。","越女紅帬濕，燕姬翠黛愁。","纜侵隄柳繫，幔宛浪花浮。","歸路飜蕭颯，陂塘五月秋。"]', '["雨来霑席上，风急打船头。","越女紅帬濕，燕姬翠黛愁。","纜侵隄柳繫，幔宛浪花浮。","归路飜蕭颯，陂塘五月秋。"]', '诗', 'shi', '', NULL, '陪諸貴公子丈八溝攜妓納涼晚際遇雨二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b188d669-90b1-4227-8fed-d725bde3105d', '白水明府舅宅喜雨', '白水明府舅宅喜雨', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["吾舅政如此，古人誰復過。","碧山晴又濕，白水雨偏多。","精禱既不昧，歡娛將謂何。","湯年旱頗甚，今日醉弦歌。"]', '["吾舅政如此，古人誰复過。","碧山晴又濕，白水雨偏多。","精禱既不昧，歡娛將謂何。","湯年旱頗甚，今日醉弦歌。"]', '诗', 'shi', '', NULL, '白水明府舅宅喜雨 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab5ba449-0413-41db-ae33-c2354bc02526', '陪李金吾花下飲', '陪李金吾花下饮', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["勝地初相引，余行得自娛。","見輕吹鳥毳，隨意數花鬚。","細草稱偏坐，香醪嬾再酤。","醉歸應犯夜，可怕李金吾。"]', '["勝地初相引，余行得自娛。","见轻吹鸟毳，隨意數花鬚。","細草稱偏坐，香醪嬾再酤。","醉归應犯夜，可怕李金吾。"]', '诗', 'shi', '', NULL, '陪李金吾花下飲 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ff8d911-4b5b-4128-b35d-7714115f6db0', '贈高式顏', '贈高式顏', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["昔別是何處，相逢皆老夫。","故人還寂寞，削跡共艱虞。","自失論文友，空知賣酒壚。","平生飛動意，見爾不能無。"]', '["昔別是何处，相逢皆老夫。","故人還寂寞，削跡共艱虞。","自失論文友，空知賣酒壚。","平生飞动意，见爾不能無。"]', '诗', 'shi', '', NULL, '贈高式顏 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d40a3095-f2e8-4ee3-9f18-b8dba56e4131', '贈比部蕭郎中十兄', '贈比部蕭郎中十兄', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["有美生人傑，由來積德門。","漢朝丞相系，梁日帝王孫。","蘊藉爲郎久，魁梧秉哲尊。","詞華傾後輩，風雅藹孤騫。","宅相榮姻戚，兒童惠討論。","見知真自幼，謀拙醜諸昆。","漂蕩雲天闊，沈埋日月奔。","致君時已晚，懷古意空存。","中散山陽鍛，愚公野谷村。","寧紆長者轍，歸老任乾坤。"]', '["有美生人傑，由来積德门。","漢朝丞相系，梁日帝王孫。","蘊藉爲郎久，魁梧秉哲尊。","词华傾後輩，风雅藹孤騫。","宅相榮姻戚，兒童惠討論。","见知真自幼，謀拙醜諸昆。","漂蕩云天闊，沈埋日月奔。","致君时已晚，懷古意空存。","中散山陽鍛，愚公野谷村。","寧紆长者轍，归老任乾坤。"]', '诗', 'shi', '', NULL, '贈比部蕭郎中十兄 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5afe65e-41f6-4c7a-8bc7-ff3f024937cb', '九日曲江', '九日曲江', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["綴席茱萸好，浮舟菡萏衰。","季秋時欲半，九日意兼悲。","江水清源曲，荆門此路疑。","晚來高興盡，搖蕩菊花期。"]', '["綴席茱萸好，浮舟菡萏衰。","季秋时欲半，九日意兼悲。","江水清源曲，荆门此路疑。","晚来高兴尽，搖蕩菊花期。"]', '诗', 'shi', '', NULL, '九日曲江 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aac265f0-080e-4861-8308-80d102a6c63d', '承沈八丈東美除膳部員外阻雨未遂馳賀奉寄此詩', '承沈八丈东美除膳部員外阻雨未遂驰賀奉寄此诗', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["今日西京掾，多除內省郎。","通家惟沈氏，謁帝似馮唐。","詩律羣公問，儒門舊史長。","清秋便寓直，列宿頓輝光。","未暇申宴慰，含情空激揚。","司存何所比，膳部默悽傷。","貧賤人事略，經過霖潦妨。","禮同諸父長，恩豈布衣忘。","天路牽騏驥，雲臺引棟梁。","徒懷貢公喜，颯颯鬢毛蒼。"]', '["今日西京掾，多除內省郎。","通家惟沈氏，謁帝似馮唐。","诗律羣公问，儒门旧史长。","清秋便寓直，列宿頓輝光。","未暇申宴慰，含情空激揚。","司存何所比，膳部默悽傷。","貧賤人事略，經過霖潦妨。","禮同諸父长，恩豈布衣忘。","天路牽騏驥，云台引棟梁。","徒懷貢公喜，颯颯鬢毛蒼。"]', '诗', 'shi', '', NULL, '承沈八丈東美除膳部員外阻雨未遂馳賀奉寄此詩 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8bbcdf98-b24e-4e1f-8b61-54fe765ce200', '奉留贈集賢院崔于二學士', '奉留贈集賢院崔于二学士', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["昭代將垂白，途窮乃叫閽。","氣衝星象表，詞感帝王尊。","天老書題目，春宮驗討論。","倚風遺鶂路，隨水到龍門。","竟與蛟螭雜，空聞燕雀喧。","青冥猶契闊，陵厲不飛飜。","儒術誠難起，家聲庶已存。","故山多藥物，勝概憶桃源。","欲整還鄉斾，長懷禁掖垣。","謬稱三賦在，難述二公恩。"]', '["昭代將垂白，途窮乃叫閽。","氣衝星象表，词感帝王尊。","天老书題目，春宮驗討論。","倚风遺鶂路，隨水到龙门。","竟與蛟螭杂，空闻燕雀喧。","青冥猶契闊，陵厲不飞飜。","儒術誠难起，家声庶已存。","故山多藥物，勝概憶桃源。","欲整還乡斾，长懷禁掖垣。","謬稱三賦在，难述二公恩。"]', '诗', 'shi', '', NULL, '奉留贈集賢院崔于二學士 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('501c3090-1ab5-4532-bbe4-533572f8ed66', '故武衛將軍輓歌三首 一', '故武衛將軍輓歌三首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["嚴警當寒夜，前軍落大星。","壯夫思感決，哀詔惜精靈。","王者今無戰，書生已勒銘。","封侯意疎闊，編簡爲誰青。"]', '["嚴警當寒夜，前軍落大星。","壯夫思感決，哀詔惜精靈。","王者今無戰，书生已勒銘。","封侯意疎闊，編簡爲誰青。"]', '诗', 'shi', '', NULL, '故武衛將軍輓歌三首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf8aa5b6-2baa-45ef-af3c-7a1f04138f8a', '故武衛將軍輓歌三首 二', '故武衛將軍輓歌三首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["舞劒過人絕，鳴弓射獸能。","銛鋒行愜順，猛噬失蹻騰。","赤羽千夫膳，黃河十月冰。","橫行沙漠外，神速至今稱。"]', '["舞劒過人絕，鳴弓射獸能。","銛鋒行愜順，猛噬失蹻腾。","赤羽千夫膳，黄河十月冰。","橫行沙漠外，神速至今稱。"]', '诗', 'shi', '', NULL, '故武衛將軍輓歌三首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7d5c37f-03d1-4795-a503-3461c7c43c7b', '故武衛將軍輓歌三首 三', '故武衛將軍輓歌三首 三', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["哀輓青門去，新阡絳水遙。","路人紛雨泣，天意颯風飄。","部曲精仍銳，匈奴氣不驕。","無由覩雄略，大樹日蕭蕭。"]', '["哀輓青门去，新阡絳水遙。","路人紛雨泣，天意颯风飄。","部曲精仍銳，匈奴氣不驕。","無由覩雄略，大樹日蕭蕭。"]', '诗', 'shi', '', NULL, '故武衛將軍輓歌三首 三 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93422ee0-895d-4778-a7f1-269cedb9bb6b', '官定後戲贈', '官定後戲贈', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["不作河西尉，淒涼爲折腰。","老夫怕趨走，率府且逍遙。","耽酒須微祿，狂歌託聖朝。","故山歸興盡，回首向風飆。"]', '["不作河西尉，淒涼爲折腰。","老夫怕趨走，率府且逍遙。","耽酒須微祿，狂歌託聖朝。","故山归兴尽，回首向风飆。"]', '诗', 'shi', '', NULL, '官定後戲贈 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a06af16-eafc-421a-b261-97245ef0dbf5', '九日藍田崔氏莊', '九日藍田崔氏莊', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["老去悲秋強自寬，興來今日盡君歡。","羞將短髮還吹帽，笑倩旁人爲正冠。","藍水遠從千澗落，玉山高並兩峰寒。","明年此會知誰健，醉把茱萸子細看。"]', '["老去悲秋強自寬，兴来今日尽君歡。","羞將短髮還吹帽，笑倩旁人爲正冠。","藍水远從千澗落，玉山高並兩峰寒。","明年此會知誰健，醉把茱萸子細看。"]', '诗', 'shi', '', NULL, '九日藍田崔氏莊 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c4c451c-c3be-4ded-8d6d-83ae2210a157', '崔氏東山草堂', '崔氏东山草堂', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["愛汝玉山草堂靜，高秋爽氣相鮮新。","有時自發鐘磬響，落日更見漁樵人。","盤剝白鴉谷口栗，飯煮青泥坊底芹。","何爲西莊王給事，柴門空閉鏁松筠。"]', '["愛汝玉山草堂静，高秋爽氣相鲜新。","有时自發鐘磬响，落日更见漁樵人。","盤剝白鴉谷口栗，飯煮青泥坊底芹。","何爲西莊王給事，柴门空閉鏁松筠。"]', '诗', 'shi', '', NULL, '崔氏東山草堂 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5246cf9-130a-4cd8-afc5-ca0f33a16b32', '對雪', '对雪', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["戰哭多新鬼，愁吟獨老翁。","亂雲低薄暮，急雪舞迴風。","瓢棄尊無綠，爐存火似紅。","數州消息斷，愁坐正書空。"]', '["戰哭多新鬼，愁吟独老翁。","亂云低薄暮，急雪舞迴风。","瓢棄尊無綠，爐存火似紅。","數州消息斷，愁坐正书空。"]', '诗', 'shi', '', NULL, '對雪 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59c7eaa9-3c05-4857-8cff-10376706ccb9', '月夜', '月夜', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["今夜鄜州月，閨中只獨看。","遙憐小兒女，未解憶長安。","香霧雲鬟濕，清輝玉臂寒。","何時倚虛幌，雙照淚痕乾。"]', '["今夜鄜州月，閨中只独看。","遙怜小兒女，未解憶长安。","香霧云鬟濕，清輝玉臂寒。","何时倚虛幌，雙照泪痕乾。"]', '诗', 'shi', '', NULL, '月夜 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f265b866-4ac3-4deb-aea5-c07157043755', '遣興', '遣兴', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["驥子好男兒，前年學語時。","問知人客姓，誦得老夫詩。","世亂憐渠小，家貧仰母慈。","鹿門攜不遂，雁足繫難期。","天地軍麾滿，山河戰角悲。","儻歸免相失，見日敢辭遲。"]', '["驥子好男兒，前年学語时。","问知人客姓，誦得老夫诗。","世亂怜渠小，家貧仰母慈。","鹿门携不遂，雁足繫难期。","天地軍麾满，山河戰角悲。","儻归免相失，见日敢辞遲。"]', '诗', 'shi', '', NULL, '遣興 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5846db55-7817-45af-bdf7-f4bd4eea5386', '元日寄韋氏妹', '元日寄韋氏妹', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["近聞韋氏妹，迎在漢鍾離。","郎伯殊方鎮，京華舊國移。","春城回北斗，郢樹發南枝。","不見朝正使，啼痕滿面垂。"]', '["近闻韋氏妹，迎在漢鍾離。","郎伯殊方鎮，京华旧国移。","春城回北斗，郢樹發南枝。","不见朝正使，啼痕满面垂。"]', '诗', 'shi', '', NULL, '元日寄韋氏妹 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9e6425c-6c14-4f69-8694-87a8b96a43de', '春望', '春望', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["國破山河在，城春草木深。","感時花濺淚，恨別鳥驚心。","烽火連三月，家書抵萬金。","白頭搔更短，渾欲不勝簪。"]', '["国破山河在，城春草木深。","感时花濺泪，恨別鸟驚心。","烽火連三月，家书抵万金。","白头搔更短，渾欲不勝簪。"]', '诗', 'shi', '', NULL, '春望 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08dc6c3a-07bc-479a-9bbe-4225ff0352e6', '憶幼子', '憶幼子', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["驥子春猶隔，鶯歌暖正繁。","別離驚節換，聰慧與誰論。","澗水空山道，柴門老樹村。","憶渠愁只睡，炙背俯晴軒。"]', '["驥子春猶隔，鶯歌暖正繁。","別離驚節換，聰慧與誰論。","澗水空山道，柴门老樹村。","憶渠愁只睡，炙背俯晴軒。"]', '诗', 'shi', '', NULL, '憶幼子 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9482c243-95f3-4929-a211-9081efcc386d', '一百五日夜對月', '一百五日夜对月', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["無家對寒食，有淚如金波。","斫却月中桂，清光應更多。","仳離放紅蘂，想像嚬青蛾。","牛女漫愁思，秋期猶渡河。"]', '["無家对寒食，有泪如金波。","斫却月中桂，清光應更多。","仳離放紅蘂，想像嚬青蛾。","牛女漫愁思，秋期猶渡河。"]', '诗', 'shi', '', NULL, '一百五日夜對月 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcb3ac74-1891-4dc4-b4cf-902bfb557786', '喜達行在所三首 一', '喜達行在所三首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["西憶岐陽信，無人遂却回。","眼穿當落日，心死著寒灰。","霧樹行相引，蓮峰望忽開。","所親驚老瘦，辛苦賊中來。"]', '["西憶岐陽信，無人遂却回。","眼穿當落日，心死著寒灰。","霧樹行相引，蓮峰望忽开。","所親驚老瘦，辛苦賊中来。"]', '诗', 'shi', '', NULL, '喜達行在所三首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42a236eb-db9d-42f2-a3ae-e415a4e48ebe', '喜達行在所三首 二', '喜達行在所三首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["愁思胡笳夕，淒涼漢苑春。","生還今日事，間道暫時人。","司隸章初覩，南陽氣已新。","喜心飜倒極，嗚咽淚霑巾。"]', '["愁思胡笳夕，淒涼漢苑春。","生還今日事，间道暫时人。","司隸章初覩，南陽氣已新。","喜心飜倒極，嗚咽泪霑巾。"]', '诗', 'shi', '', NULL, '喜達行在所三首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8aa47a3d-a824-4c5d-866d-337bbf9d386b', '喜達行在所三首 三', '喜達行在所三首 三', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["死去憑誰報，歸來始自憐。","猶瞻太白雪，喜遇武功天。","影靜千官裏，心蘇七校前。","今朝漢社稷，新數中興年。"]', '["死去憑誰報，归来始自怜。","猶瞻太白雪，喜遇武功天。","影静千官裏，心蘇七校前。","今朝漢社稷，新數中兴年。"]', '诗', 'shi', '', NULL, '喜達行在所三首 三 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f23b1cc-5071-4fb2-95c2-a2e94c7016e9', '得家書', '得家书', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["去憑遊客寄，來爲附家書。","今日知消息，他鄉且舊居。","熊兒幸無恙，驥子最憐渠。","臨老羈孤極，傷時會合疎。","二毛趨帳殿，一命侍鸞輿。","北闕妖氛滿，西郊白露初。","涼風新過雁，秋雨欲生魚。","農事空山裏，眷言終荷鋤。"]', '["去憑游客寄，来爲附家书。","今日知消息，他乡且旧居。","熊兒幸無恙，驥子最怜渠。","臨老羈孤極，傷时會合疎。","二毛趨帳殿，一命侍鸾輿。","北闕妖氛满，西郊白露初。","涼风新過雁，秋雨欲生鱼。","農事空山裏，眷言終荷鋤。"]', '诗', 'shi', '', NULL, '得家書 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4836a0b-ba8d-4561-adfe-a7b862c42f5f', '奉贈嚴八閣老', '奉贈嚴八閣老', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["扈聖登黃閣，明公獨妙年。","蛟龍得雲雨，鵰鶚在秋天。","客禮容疎放，官曹可接聯。","新詩句句好，應任老夫傳。"]', '["扈聖登黄閣，明公独妙年。","蛟龙得云雨，鵰鶚在秋天。","客禮容疎放，官曹可接聯。","新诗句句好，應任老夫傳。"]', '诗', 'shi', '', NULL, '奉贈嚴八閣老 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3c12144-2047-423c-82ab-59ac817de071', '奉送郭中丞兼太僕卿充隴右節度使三十韻', '奉送郭中丞兼太僕卿充隴右節度使三十韻', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["詔發西山將，秋屯隴右兵。","淒涼餘部曲，燀赫舊家聲。","鵰鶚乘時去，驊騮顧主鳴。","艱難須上策，容易即前程。","斜日當軒蓋，高風卷斾旌。","松悲天水冷，沙亂雪山清。","和虜猶懷惠，防邊不敢驚。","古來於異域，鎮靜示專征。","燕薊奔封豕，周秦觸駭鯨。","中原何慘黷，餘孽尚縱橫。","箭入昭陽殿，笳吟細柳營。","內人紅袖泣，王子白衣行。","宸極祅星動，園陵殺氣平。","空餘金椀出，無復繐帷輕。","毀廟天飛雨，焚宮火徹明。","罘罳朝共落，棆桷夜同傾。","三月師逾整，羣胡勢就烹。","瘡痍親接戰，勇決冠垂成。","妙譽期元宰，殊恩且列卿。","幾時迴節鉞，戮力埽欃槍。","圭竇三千士，雲梯七十城。","恥非齊說客，祗似魯諸生。","通籍微班忝，周行獨坐榮。","隨肩趨漏刻，短髮寄簪纓。","徑欲依劉表，還疑厭禰衡。","漸衰那此別，忍淚獨含情。","廢邑狐貍語，空邨虎豹爭。","人頻墜塗炭，公豈忘精誠。","元帥調新律，前軍壓舊京。","安邊仍扈從，莫作後功名。"]', '["詔發西山將，秋屯隴右兵。","淒涼餘部曲，燀赫旧家声。","鵰鶚乘时去，驊騮顧主鳴。","艱难須上策，容易即前程。","斜日當軒蓋，高风卷斾旌。","松悲天水冷，沙亂雪山清。","和虜猶懷惠，防邊不敢驚。","古来於異域，鎮静示專征。","燕薊奔封豕，周秦觸駭鯨。","中原何慘黷，餘孽尚縱橫。","箭入昭陽殿，笳吟細柳營。","內人紅袖泣，王子白衣行。","宸極祅星动，园陵殺氣平。","空餘金椀出，無复繐帷轻。","毀廟天飞雨，焚宮火徹明。","罘罳朝共落，棆桷夜同傾。","三月師逾整，羣胡勢就烹。","瘡痍親接戰，勇決冠垂成。","妙譽期元宰，殊恩且列卿。","幾时迴節鉞，戮力埽欃槍。","圭竇三千士，云梯七十城。","恥非齊说客，祗似魯諸生。","通籍微班忝，周行独坐榮。","隨肩趨漏刻，短髮寄簪纓。","徑欲依劉表，還疑厭禰衡。","漸衰那此別，忍泪独含情。","廢邑狐貍語，空邨虎豹爭。","人頻墜塗炭，公豈忘精誠。","元帥調新律，前軍壓旧京。","安邊仍扈從，莫作後功名。"]', '诗', 'shi', '', NULL, '奉送郭中丞兼太僕卿充隴右節度使三十韻 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79409b2e-e571-44e6-a49d-46f40cbbbc2f', '送楊六判官使西蕃', '送楊六判官使西蕃', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["送遠秋風落，西征海氣寒。","帝京氛祲滿，人世別離難。","絕域遙懷怒，和親願結歡。","敕書憐贊普，兵甲望長安。","宣命前程急，惟良待士寬。","子雲清自守，今日起爲官。","垂淚方投筆，傷時即據鞍。","儒衣山鳥怪，漢節野童看。","邊酒排金醆，夷歌捧玉盤。","草輕蕃馬健，雪重拂廬乾。","慎爾參籌畫，從茲正羽翰。","歸來權可取，九萬一朝摶。"]', '["送远秋风落，西征海氣寒。","帝京氛祲满，人世別離难。","絕域遙懷怒，和親願結歡。","敕书怜贊普，兵甲望长安。","宣命前程急，惟良待士寬。","子云清自守，今日起爲官。","垂泪方投笔，傷时即據鞍。","儒衣山鸟怪，漢節野童看。","邊酒排金醆，夷歌捧玉盤。","草轻蕃马健，雪重拂廬乾。","慎爾參籌畫，從茲正羽翰。","归来權可取，九万一朝摶。"]', '诗', 'shi', '', NULL, '送楊六判官使西蕃 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a35f4223-3156-4912-a5f5-037679ced8a3', '月', '月', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["天上秋期近，人間月影清。","入河蟾不沒，擣藥兔長生。","只益丹心苦，能添白髮明。","干戈知滿地，休照國西營。"]', '["天上秋期近，人间月影清。","入河蟾不沒，擣藥兔长生。","只益丹心苦，能添白髮明。","干戈知满地，休照国西營。"]', '诗', 'shi', '', NULL, '月 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f35c4d3c-1141-4821-9c39-99a480960d98', '留別賈嚴二閣老兩院補闕', '留別賈嚴二閣老兩院補闕', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["田園須蹔往，戎馬惜離羣。","去遠留詩別，愁多任酒醺。","一秋常苦雨，今日始無雲。","山路時吹角，那堪處處聞。"]', '["田园須蹔往，戎马惜離羣。","去远留诗別，愁多任酒醺。","一秋常苦雨，今日始無云。","山路时吹角，那堪处处闻。"]', '诗', 'shi', '', NULL, '留別賈嚴二閣老兩院補闕 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fc53dc2-02b8-4730-9591-f38761ec08c4', '晚行口號', '晚行口號', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["三川不可到，歸路晚山稠。","落雁浮寒水，飢烏集戍樓。","市朝今日異，喪亂幾時休。","遠媿梁江總，還家尚黑頭。"]', '["三川不可到，归路晚山稠。","落雁浮寒水，飢烏集戍楼。","市朝今日異，喪亂幾时休。","远媿梁江總，還家尚黑头。"]', '诗', 'shi', '', NULL, '晚行口號 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bae42ddc-7641-43fc-8edc-882c1f6f53d0', '獨酌成詩', '独酌成诗', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["燈花何太喜，酒綠正相親。","醉裏從爲客，詩成覺有神。","兵戈猶在眼，儒術豈謀身。","共被微官縛，低頭媿野人。"]', '["灯花何太喜，酒綠正相親。","醉裏從爲客，诗成覺有神。","兵戈猶在眼，儒術豈謀身。","共被微官縛，低头媿野人。"]', '诗', 'shi', '', NULL, '獨酌成詩 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e11ed7c1-450d-4504-8a6b-a040475e92d9', '行次昭陵', '行次昭陵', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["舊俗疲庸主，羣雄問獨夫。","讖歸龍鳳質，威定虎狼都。","天屬尊堯典，神功協禹謨。","風雲隨絕足，日月繼高衢。","文物多師古，朝廷半老儒。","直詞寧戮辱，賢路不崎嶇。","往者災猶降，蒼生喘未蘇。","指麾安率土，盪滌撫洪爐。","壯士悲陵邑，幽人拜鼎湖。","玉衣晨自舉，鐵馬汗常趨。","松柏瞻虛殿，塵沙立暝途。","寂寥開國日，流恨滿山隅。"]', '["旧俗疲庸主，羣雄问独夫。","讖归龙鳳質，威定虎狼都。","天屬尊堯典，神功協禹謨。","风云隨絕足，日月繼高衢。","文物多師古，朝廷半老儒。","直词寧戮辱，賢路不崎嶇。","往者災猶降，蒼生喘未蘇。","指麾安率土，盪滌撫洪爐。","壯士悲陵邑，幽人拜鼎湖。","玉衣晨自舉，鐵马汗常趨。","松柏瞻虛殿，塵沙立暝途。","寂寥开国日，流恨满山隅。"]', '诗', 'shi', '', NULL, '行次昭陵 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a68b8610-8269-46fa-b015-d367d71e04eb', '重經昭陵', '重經昭陵', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["草昧英雄起，謳歌曆數歸。","風塵三尺劒，社稷一戎衣。","翼亮貞文德，丕承戢武威。","聖圖天廣大，宗祀日光輝。","陵寢盤空曲，熊羆守翠微。","再窺松柏路，還見五雲飛。"]', '["草昧英雄起，謳歌曆數归。","风塵三尺劒，社稷一戎衣。","翼亮貞文德，丕承戢武威。","聖圖天廣大，宗祀日光輝。","陵寢盤空曲，熊羆守翠微。","再窺松柏路，還见五云飞。"]', '诗', 'shi', '', NULL, '重經昭陵 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbb109b7-3b66-4f82-a111-97892b26fa7a', '喜聞官軍已臨賊境二十韻', '喜闻官軍已臨賊境二十韻', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["胡虜潛京縣，官軍擁賊壕。","鼎魚猶假息，穴蟻欲何逃。","帳殿羅玄冕，轅門照白袍。","秦山當警蹕，漢苑入旌旄。","路失羊腸險，雲橫雉尾高。","五原空壁壘，八水散風濤。","今日看天意，遊魂貸爾曹。","乞降那更得，尚詐莫徒勞。","元帥歸龍種，司空握豹韜。","前軍蘇武節，左將呂虔刀。","兵氣回飛鳥，威聲沒巨鼇。","戈鋋開雪色，弓矢尚秋毫。","天步艱方盡，時和運更遭。","誰云遺毒螫，已是沃腥臊。","睿想丹墀近，神行羽衛牢。","花門騰絕漠，拓羯渡臨洮。","此輩感恩至，羸俘何足操。","鋒先衣染血，騎突劒吹毛。","喜覺都城動，悲憐子女號。","家家賣釵釧，只待獻春醪。"]', '["胡虜潛京縣，官軍擁賊壕。","鼎鱼猶假息，穴蟻欲何逃。","帳殿羅玄冕，轅门照白袍。","秦山當警蹕，漢苑入旌旄。","路失羊腸險，云橫雉尾高。","五原空壁壘，八水散风濤。","今日看天意，游魂貸爾曹。","乞降那更得，尚詐莫徒勞。","元帥归龙種，司空握豹韜。","前軍蘇武節，左將呂虔刀。","兵氣回飞鸟，威声沒巨鼇。","戈鋋开雪色，弓矢尚秋毫。","天步艱方尽，时和運更遭。","誰云遺毒螫，已是沃腥臊。","睿想丹墀近，神行羽衛牢。","花门腾絕漠，拓羯渡臨洮。","此輩感恩至，羸俘何足操。","鋒先衣染血，騎突劒吹毛。","喜覺都城动，悲怜子女號。","家家賣釵釧，只待獻春醪。"]', '诗', 'shi', '', NULL, '喜聞官軍已臨賊境二十韻 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b755f069-b0a4-48e4-9a32-ccd5760c8145', '收京三首 一', '收京三首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["仙仗離丹極，妖星照玉除。","須爲下殿走，不可好樓居。","暫屈汾陽駕，聊飛燕將書。","依然七廟略，更與萬方初。"]', '["仙仗離丹極，妖星照玉除。","須爲下殿走，不可好楼居。","暫屈汾陽駕，聊飞燕將书。","依然七廟略，更與万方初。"]', '诗', 'shi', '', NULL, '收京三首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba89d909-9652-4b7d-92d0-322cf35d5884', '收京三首 二', '收京三首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["生意甘衰白，天涯正寂寥。","忽聞哀痛詔，又下聖明朝。","羽翼懷商老，文思憶帝堯。","叨逢罪己日，霑灑望青霄。"]', '["生意甘衰白，天涯正寂寥。","忽闻哀痛詔，又下聖明朝。","羽翼懷商老，文思憶帝堯。","叨逢罪己日，霑灑望青霄。"]', '诗', 'shi', '', NULL, '收京三首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('330d805a-4167-40f4-9541-bfedc51bf4ae', '收京三首 三', '收京三首 三', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["汗馬收宮闕，春城剷賊壕。","賞應歌杕杜，歸及薦櫻桃。","雜虜橫戈數，功臣甲第高。","萬方頻送喜，無乃聖躬勞。"]', '["汗马收宮闕，春城剷賊壕。","賞應歌杕杜，归及薦櫻桃。","杂虜橫戈數，功臣甲第高。","万方頻送喜，無乃聖躬勞。"]', '诗', 'shi', '', NULL, '收京三首 三 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93c07519-1b9a-4ec0-b8e8-841cd597e49c', '臘日', '臘日', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["臘日常年暖尚遙，今年臘日凍全消。","侵陵雪色還萱草，漏洩春光有柳條。","縱酒欲謀良夜醉，還家初散紫宸朝。","口脂面藥隨恩澤，翠管銀罌下九霄。"]', '["臘日常年暖尚遙，今年臘日凍全消。","侵陵雪色還萱草，漏洩春光有柳條。","縱酒欲謀良夜醉，還家初散紫宸朝。","口脂面藥隨恩澤，翠管銀罌下九霄。"]', '诗', 'shi', '', NULL, '臘日 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1452d4a0-8b49-4c25-918f-9fb14f35a2bc', '紫宸殿退朝口號', '紫宸殿退朝口號', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["戶外昭容紫袖垂，雙瞻御座引朝儀。","香飄合殿春風轉，花覆千官淑景移。","晝漏希聞高閣報，天顏有喜近臣知。","宮中每出歸東省，會送夔龍集鳳池。"]', '["戶外昭容紫袖垂，雙瞻御座引朝儀。","香飄合殿春风轉，花覆千官淑景移。","晝漏希闻高閣報，天顏有喜近臣知。","宮中每出归东省，會送夔龙集鳳池。"]', '诗', 'shi', '', NULL, '紫宸殿退朝口號 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d954e300-4edc-4819-8b39-8da5d11b7592', '曲江二首 一', '曲江二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["一片花飛減却春，風飄萬點正愁人。","且看欲盡花經眼，莫厭傷多酒入脣。","江上小堂巢翡翠，花邊高冢臥麒麟。","細推物理須行樂，何用浮名絆此身。"]', '["一片花飞減却春，风飄万点正愁人。","且看欲尽花經眼，莫厭傷多酒入脣。","江上小堂巢翡翠，花邊高冢臥麒麟。","細推物理須行乐，何用浮名絆此身。"]', '诗', 'shi', '', NULL, '曲江二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23834447-1596-4ba9-ab2b-3db0d39108bb', '曲江二首 二', '曲江二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["朝回日日典春衣，每日江頭盡醉歸。","酒債尋常行處有，人生七十古來稀。","穿花蛺蝶深深見，點水蜻蜓款款飛。","傳語風光共流轉，暫時相賞莫相違。"]', '["朝回日日典春衣，每日江头尽醉归。","酒債尋常行处有，人生七十古来稀。","穿花蛺蝶深深见，点水蜻蜓款款飞。","傳語风光共流轉，暫时相賞莫相違。"]', '诗', 'shi', '', NULL, '曲江二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('acc3a0aa-9e2e-4d09-a9e7-afc040bcdd31', '曲江對酒', '曲江对酒', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["苑外江頭坐不歸，水精春殿轉霏微。","桃花細逐楊花落，黃鳥時兼白鳥飛。","縱飲久判人共棄，嬾朝真與世相違。","吏情更覺滄洲遠，老大悲傷未拂衣。"]', '["苑外江头坐不归，水精春殿轉霏微。","桃花細逐楊花落，黄鸟时兼白鸟飞。","縱饮久判人共棄，嬾朝真與世相違。","吏情更覺滄洲远，老大悲傷未拂衣。"]', '诗', 'shi', '', NULL, '曲江對酒 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb4e050e-22ed-4f7e-8b41-078534a7e01b', '曲江對雨', '曲江对雨', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["城上春雲覆苑牆，江亭晚色靜年芳。","林花著雨燕脂落，水荇牽風翠帶長。","龍武新軍深駐輦，芙蓉別殿謾焚香。","何時詔此金錢會，暫醉佳人錦瑟旁。"]', '["城上春云覆苑牆，江亭晚色静年芳。","林花著雨燕脂落，水荇牽风翠带长。","龙武新軍深駐輦，芙蓉別殿謾焚香。","何时詔此金錢會，暫醉佳人錦瑟旁。"]', '诗', 'shi', '', NULL, '曲江對雨 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56df51aa-0b14-4261-aaca-6866007287b1', '奉和賈至舍人早朝大明宮', '奉和賈至舍人早朝大明宮', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["五夜漏聲催曉箭，九重春色醉仙桃。","旌旗日暖龍蛇動，宮殿風微燕雀高。","朝罷香煙攜滿袖，詩成珠玉在揮毫。","欲知世掌絲綸美，池上於今有鳳毛。"]', '["五夜漏声催晓箭，九重春色醉仙桃。","旌旗日暖龙蛇动，宮殿风微燕雀高。","朝罷香煙携满袖，诗成珠玉在揮毫。","欲知世掌絲綸美，池上於今有鳳毛。"]', '诗', 'shi', '', NULL, '奉和賈至舍人早朝大明宮 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e6abc60-ab63-4865-a822-638f63805fe1', '宣政殿退朝晚出左掖', '宣政殿退朝晚出左掖', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["天門日射黃金牓，春殿晴曛赤羽旗。","宮草微微承委佩，鑪煙細細駐遊絲。","雲近蓬萊常好色，雪殘鳷鵲亦多時。","侍臣緩步歸青瑣，退食從容出每遲。"]', '["天门日射黄金牓，春殿晴曛赤羽旗。","宮草微微承委佩，鑪煙細細駐游絲。","云近蓬萊常好色，雪殘鳷鵲亦多时。","侍臣緩步归青瑣，退食從容出每遲。"]', '诗', 'shi', '', NULL, '宣政殿退朝晚出左掖 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe54c75c-9e9a-4c5c-91df-47c14716818e', '題省中院壁', '題省中院壁', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["掖垣竹埤梧十尋，洞門對霤常陰陰。","落花遊絲白日靜，鳴鳩乳燕青春深。","腐儒衰晚謬通籍，退食遲迴違寸心。","衮職曾無一字補，許身媿比雙南金。"]', '["掖垣竹埤梧十尋，洞门对霤常陰陰。","落花游絲白日静，鳴鳩乳燕青春深。","腐儒衰晚謬通籍，退食遲迴違寸心。","衮職曾無一字補，許身媿比雙南金。"]', '诗', 'shi', '', NULL, '題省中院壁 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2769113d-0cac-4e67-83cb-0c10685f8381', '春宿左省', '春宿左省', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["花隱掖垣暮，啾啾棲鳥過。","星臨萬戶動，月傍九霄多。","不寢聽金鑰，因風想玉珂。","明朝有封事，數問夜如何。"]', '["花隐掖垣暮，啾啾棲鸟過。","星臨万戶动，月傍九霄多。","不寢听金鑰，因风想玉珂。","明朝有封事，數问夜如何。"]', '诗', 'shi', '', NULL, '春宿左省 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5c7c474-4fff-4fec-9f4a-d8e2d1447a77', '送翰林張司馬南海勒碑', '送翰林張司马南海勒碑', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["冠冕通南極，文章落上台。","詔從三殿去，碑到百蠻開。","野館濃花發，春帆細雨來。","不知滄海上，天遣幾時回。"]', '["冠冕通南極，文章落上台。","詔從三殿去，碑到百蠻开。","野館濃花發，春帆細雨来。","不知滄海上，天遣幾时回。"]', '诗', 'shi', '', NULL, '送翰林張司馬南海勒碑 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3d9772e-9eec-4dd0-9ac1-fe1f94646c61', '晚出左掖', '晚出左掖', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["晝刻傳呼淺，春旗簇仗齊。","退朝花底散，歸院柳邊迷。","樓雪融城濕，宮雲去殿低。","避人焚諫草，騎馬欲雞棲。"]', '["晝刻傳呼淺，春旗簇仗齊。","退朝花底散，归院柳邊迷。","楼雪融城濕，宮云去殿低。","避人焚諫草，騎马欲雞棲。"]', '诗', 'shi', '', NULL, '晚出左掖 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5f78fdb-2066-4ff7-8b29-8a1ce54c0c28', '曲江陪鄭八丈南史飲', '曲江陪鄭八丈南史饮', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["雀啄江頭黃柳花，鵁鶄鸂鶒滿晴沙。","自知白髮非春事，且盡芳尊戀物華。","近侍即今難浪迹，此身那得更無家。","丈人文力猶強健，豈傍青門學種瓜。"]', '["雀啄江头黄柳花，鵁鶄鸂鶒满晴沙。","自知白髮非春事，且尽芳尊戀物华。","近侍即今难浪迹，此身那得更無家。","丈人文力猶強健，豈傍青门学種瓜。"]', '诗', 'shi', '', NULL, '曲江陪鄭八丈南史飲 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88a4cb52-fee3-461b-b681-32275a0edd24', '送賈閣老出汝州', '送賈閣老出汝州', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["西掖梧桐樹，空留一院陰。","艱難歸故里，去住損春心。","宮殿青門隔，雲山紫邏深。","人生五馬貴，莫受二毛侵。"]', '["西掖梧桐樹，空留一院陰。","艱难归故里，去住損春心。","宮殿青门隔，云山紫邏深。","人生五马貴，莫受二毛侵。"]', '诗', 'shi', '', NULL, '送賈閣老出汝州 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19b577a6-dca0-4c95-9365-7e4a8356e71d', '鄭駙馬池臺喜遇鄭廣文同飲', '鄭駙马池台喜遇鄭廣文同饮', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["不謂生戎馬，何知共酒杯。","然臍郿塢敗，握節漢臣回。","白髮千莖雪，丹心一寸灰。","別離經死地，披寫忽登臺。","重對秦簫發，俱過阮宅來。","留連春夜舞，淚落強裴回。"]', '["不謂生戎马，何知共酒杯。","然臍郿塢敗，握節漢臣回。","白髮千莖雪，丹心一寸灰。","別離經死地，披寫忽登台。","重对秦簫發，俱過阮宅来。","留連春夜舞，泪落強裴回。"]', '诗', 'shi', '', NULL, '鄭駙馬池臺喜遇鄭廣文同飲 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9bfc8f27-b527-4cce-9c7b-000d7285c0ea', '送鄭十八虔貶台州司戶傷其臨老陷賊之故闕爲面別情見於詩', '送鄭十八虔貶台州司戶傷其臨老陷賊之故闕爲面別情见於诗', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["鄭公樗散鬢成絲，酒後常稱老畫師。","萬里傷心嚴譴日，百年垂死中興時。","蒼惶已就長途往，邂逅無端出餞遲。","便與先生應永訣，九重泉路盡交期。"]', '["鄭公樗散鬢成絲，酒後常稱老畫師。","万里傷心嚴譴日，百年垂死中兴时。","蒼惶已就长途往，邂逅無端出餞遲。","便與先生應永訣，九重泉路尽交期。"]', '诗', 'shi', '', NULL, '送鄭十八虔貶台州司戶傷其臨老陷賊之故闕爲面別情見於詩 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf854c36-62d7-4c54-ad3f-258cfedbb14a', '題鄭十八著作虔', '題鄭十八著作虔', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["台州地闊海冥冥，雲水長和島嶼青。","亂後故人雙別淚，春深逐客一浮萍。","酒酣嬾舞誰相拽，詩罷能吟不復聽。","第五橋東流恨水，皇陂岸北結愁亭。","賈生對鵩傷王傅，蘇武看羊陷賊庭。","可念此翁懷直道，也霑新國用輕刑。","禰衡實恐遭江夏，方朔虛傳是歲星。","窮巷悄然車馬絕，案頭乾死讀書螢。"]', '["台州地闊海冥冥，云水长和島嶼青。","亂後故人雙別泪，春深逐客一浮萍。","酒酣嬾舞誰相拽，诗罷能吟不复听。","第五橋东流恨水，皇陂岸北結愁亭。","賈生对鵩傷王傅，蘇武看羊陷賊庭。","可念此翁懷直道，也霑新国用轻刑。","禰衡實恐遭江夏，方朔虛傳是歲星。","窮巷悄然车马絕，案头乾死读书螢。"]', '诗', 'shi', '', NULL, '題鄭十八著作虔 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54954a45-c90c-4fa5-858e-90a189f637b4', '端午日賜衣', '端午日賜衣', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["宮衣亦有名，端午被恩榮。","細葛含風輭，香羅疊雪輕。","自天題處濕，當暑著來清。","意內稱長短，終身荷聖情。"]', '["宮衣亦有名，端午被恩榮。","細葛含风輭，香羅叠雪轻。","自天題处濕，當暑著来清。","意內稱长短，終身荷聖情。"]', '诗', 'shi', '', NULL, '端午日賜衣 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c79ae130-83bb-423d-b3d3-0ce169c5af49', '贈畢四', '贈畢四', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["才大今詩伯，家貧苦宦卑。","飢寒奴僕賤，顏狀老翁爲。","同調嗟誰惜，論文笑自知。","流傳江鮑體，相顧免無兒。"]', '["才大今诗伯，家貧苦宦卑。","飢寒奴僕賤，顏狀老翁爲。","同調嗟誰惜，論文笑自知。","流傳江鲍體，相顧免無兒。"]', '诗', 'shi', '', NULL, '贈畢四 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab870495-7671-41b5-922d-c9c5e7bb3726', '酬孟雲卿', '酬孟云卿', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["樂極傷頭白，更長愛燭紅。","相逢難衮衮，告別莫怱怱。","但恐天河落，寧辭酒醆空。","明朝牽世務，揮淚各西東。"]', '["乐極傷头白，更长愛燭紅。","相逢难衮衮，告別莫怱怱。","但恐天河落，寧辞酒醆空。","明朝牽世務，揮泪各西东。"]', '诗', 'shi', '', NULL, '酬孟雲卿 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63aa0a1e-4b50-42f0-adbf-15fea1394963', '奉贈王中允', '奉贈王中允', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["中允聲名久，如今契闊深。","共傳收庾信，不比得陳琳一病緣明主，三年獨此心。","窮愁應有作，試誦白頭吟。"]', '["中允声名久，如今契闊深。","共傳收庾信，不比得陳琳一病緣明主，三年独此心。","窮愁應有作，試誦白头吟。"]', '诗', 'shi', '', NULL, '奉贈王中允 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea9ee6ef-9a41-42c5-8676-e47b412f0db9', '奉陪鄭駙馬韋曲二首 一', '奉陪鄭駙马韋曲二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["韋曲花無賴，家家惱殺人。","綠尊雖盡日，白髮好禁春。","石角鉤衣破，藤枝刺眼新。","何時占業竹，頭戴小烏巾。"]', '["韋曲花無賴，家家惱殺人。","綠尊雖尽日，白髮好禁春。","石角鉤衣破，藤枝刺眼新。","何时占業竹，头戴小烏巾。"]', '诗', 'shi', '', NULL, '奉陪鄭駙馬韋曲二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c50ef689-8ad8-43b3-8504-54a2a5a54171', '奉陪鄭駙馬韋曲二首 二', '奉陪鄭駙马韋曲二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["野寺垂楊裏，春畦亂水間。","美花多映竹，好鳥不歸山。","城郭終何事，風塵豈駐顏。","誰能共公子，薄暮欲俱還。"]', '["野寺垂楊裏，春畦亂水间。","美花多映竹，好鸟不归山。","城郭終何事，风塵豈駐顏。","誰能共公子，薄暮欲俱還。"]', '诗', 'shi', '', NULL, '奉陪鄭駙馬韋曲二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2503d099-6e39-4c1e-bf86-cd84c0e61d85', '奉荅岑參補闕見贈', '奉荅岑參補闕见贈', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["窈窕清禁闥，罷朝歸不同。","君隨丞相後，我往日華東。","冉冉柳枝碧，娟娟花蘂紅。","故人得佳句，獨贈白頭翁。"]', '["窈窕清禁闥，罷朝归不同。","君隨丞相後，我往日华东。","冉冉柳枝碧，娟娟花蘂紅。","故人得佳句，独贈白头翁。"]', '诗', 'shi', '', NULL, '奉荅岑參補闕見贈 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b14af996-a066-4cff-8903-35e2d658155a', '送許八拾遺歸江寧覲省甫昔時嘗客遊此縣於許生處乞瓦棺寺維摩圖樣志諸篇末', '送許八拾遺归江寧覲省甫昔时嘗客游此縣於許生处乞瓦棺寺維摩圖樣志諸篇末', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["詔許辭中禁，慈顏赴北堂。","聖朝新孝理，祖席倍輝光。","內帛擎偏重，宮衣著更香。","淮陰清夜驛，京口渡江航。","春隔雞人晝，秋期燕子涼。","賜書誇父老，壽酒樂城隍。","看畫曾飢渴，追蹤恨淼茫。","虎頭金粟影，神妙獨難忘。"]', '["詔許辞中禁，慈顏赴北堂。","聖朝新孝理，祖席倍輝光。","內帛擎偏重，宮衣著更香。","淮陰清夜驛，京口渡江航。","春隔雞人晝，秋期燕子涼。","賜书誇父老，壽酒乐城隍。","看畫曾飢渴，追蹤恨淼茫。","虎头金粟影，神妙独难忘。"]', '诗', 'shi', '', NULL, '送許八拾遺歸江寧覲省甫昔時嘗客遊此縣於許生處乞瓦棺寺維摩圖樣志諸篇末 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8330e313-8085-4cb6-aff2-ae060be0427f', '因許八奉寄江寧旻上人', '因許八奉寄江寧旻上人', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["不見旻公三十年，對書寄與淚潺湲。","舊來好事今能否，老去新詩誰與傳。","棊局動隨尋澗竹，袈裟憶上泛湖船。","聞君話我爲官在，頭白昏昏只醉眠。"]', '["不见旻公三十年，对书寄與泪潺湲。","旧来好事今能否，老去新诗誰與傳。","棊局动隨尋澗竹，袈裟憶上泛湖船。","闻君話我爲官在，头白昏昏只醉眠。"]', '诗', 'shi', '', NULL, '因許八奉寄江寧旻上人 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f88a6dbd-bf83-458c-b5e2-85fdd1ed98b2', '至德二載甫自京金光門出問道歸鳳翔乾元初從左拾遺移華州掾與親故別因出此門有悲往事', '至德二載甫自京金光门出问道归鳳翔乾元初從左拾遺移华州掾與親故別因出此门有悲往事', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["此道昔歸順，西郊胡正繁。","至今殘破膽，應有未招魂。","近得歸京邑，移官豈至尊。","無才日衰老，駐馬望千門。"]', '["此道昔归順，西郊胡正繁。","至今殘破膽，應有未招魂。","近得归京邑，移官豈至尊。","無才日衰老，駐马望千门。"]', '诗', 'shi', '', NULL, '至德二載甫自京金光門出問道歸鳳翔乾元初從左拾遺移華州掾與親故別因出此門有悲往事 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('450412bc-cbe8-4ed5-9f44-80257de60195', '寄高三十五詹事', '寄高三十五詹事', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["安穩高詹事，兵戈久索居。","時來如宦達，歲晚莫情疎。","天上多鴻雁，池中足鯉魚。","相看過半百，不寄一行書。"]', '["安穩高詹事，兵戈久索居。","时来如宦達，歲晚莫情疎。","天上多鴻雁，池中足鯉鱼。","相看過半百，不寄一行书。"]', '诗', 'shi', '', NULL, '寄高三十五詹事 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3de2b064-649b-4161-8ca5-6eef38ed7a13', '路逢襄陽楊少府入城戲呈楊員外綰', '路逢襄陽楊少府入城戲呈楊員外綰', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["寄語楊員外，山寒少茯苓。","歸來稍喧暖，當爲斸青冥。","飜動神仙窟，封題鳥獸形。","兼將老藤杖，扶汝醉初醒。"]', '["寄語楊員外，山寒少茯苓。","归来稍喧暖，當爲斸青冥。","飜动神仙窟，封題鸟獸形。","兼將老藤杖，扶汝醉初醒。"]', '诗', 'shi', '', NULL, '路逢襄陽楊少府入城戲呈楊員外綰 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d1d49b5-035f-4a94-a44f-62a626cfef42', '題鄭縣亭子', '題鄭縣亭子', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["鄭縣亭子澗之濱，戶牖憑高發興新。","雲斷岳蓮臨大路，天晴宮柳暗長春。","巢邊野雀羣欺燕，花底山蜂遠趁人。","更欲題詩滿青竹，晚來幽獨恐傷神。"]', '["鄭縣亭子澗之濱，戶牖憑高發兴新。","云斷岳蓮臨大路，天晴宮柳暗长春。","巢邊野雀羣欺燕，花底山蜂远趁人。","更欲題诗满青竹，晚来幽独恐傷神。"]', '诗', 'shi', '', NULL, '題鄭縣亭子 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('708eb748-5e4c-45b8-9d44-221f9099b801', '早秋苦熱堆案相仍', '早秋苦熱堆案相仍', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["七月六日苦炎熱，對食暫餐還不能。","每愁夜中自足蝎，況乃秋後轉多蠅。","束帶發狂欲大叫，簿書何急來相仍。","南望青松架短壑，安得赤脚蹋層冰。"]', '["七月六日苦炎熱，对食暫餐還不能。","每愁夜中自足蝎，況乃秋後轉多蠅。","束带發狂欲大叫，簿书何急来相仍。","南望青松架短壑，安得赤脚蹋層冰。"]', '诗', 'shi', '', NULL, '早秋苦熱堆案相仍 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08952280-f6c8-4e0d-a585-363c240a5e16', '望岳', '望岳', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["西岳崚嶒竦處尊，諸峰羅立如兒孫。","安得仙人九節杖，拄到玉女洗頭盆。","車箱入谷無歸路，箭栝通天有一門。","稍待西風涼冷後，高尋白帝問真源。"]', '["西岳崚嶒竦处尊，諸峰羅立如兒孫。","安得仙人九節杖，拄到玉女洗头盆。","车箱入谷無归路，箭栝通天有一门。","稍待西风涼冷後，高尋白帝问真源。"]', '诗', 'shi', '', NULL, '望岳 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6cf4f8dd-9d3b-4ba0-84e6-109d36a9863e', '至日遣興奉寄北省舊閣老兩院故人二首 一', '至日遣兴奉寄北省旧閣老兩院故人二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["去歲茲辰捧御牀，五更三點入鵷行。","欲知趨走傷心地，正想氛氳滿眼香。","無路從容陪語笑，有時顛倒著衣裳。","何人錯憶窮愁日，愁日愁隨一線長。"]', '["去歲茲辰捧御牀，五更三点入鵷行。","欲知趨走傷心地，正想氛氳满眼香。","無路從容陪語笑，有时顛倒著衣裳。","何人錯憶窮愁日，愁日愁隨一線长。"]', '诗', 'shi', '', NULL, '至日遣興奉寄北省舊閣老兩院故人二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80b59d90-c62e-4269-8883-3b625cd91ba7', '至日遣興奉寄北省舊閣老兩院故人二首 二', '至日遣兴奉寄北省旧閣老兩院故人二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["憶昨逍遙供奉班，去年今日侍龍顏。","麒麟不動爐煙上，孔雀徐開扇影還。","玉几由來天北極，朱衣只在殿中間。","孤城此日堪腸斷，愁對寒雲雪滿山。"]', '["憶昨逍遙供奉班，去年今日侍龙顏。","麒麟不动爐煙上，孔雀徐开扇影還。","玉几由来天北極，朱衣只在殿中间。","孤城此日堪腸斷，愁对寒云雪满山。"]', '诗', 'shi', '', NULL, '至日遣興奉寄北省舊閣老兩院故人二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('194fa0f1-ddae-472b-9605-5cd82616abb3', '得弟消息二首 一', '得弟消息二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["近有平陰信，遙憐舍弟存。","側身千里道，寄食一家村。","烽舉新酣戰，啼垂舊血痕。","不知臨老日，招得幾人魂。"]', '["近有平陰信，遙怜舍弟存。","側身千里道，寄食一家村。","烽舉新酣戰，啼垂旧血痕。","不知臨老日，招得幾人魂。"]', '诗', 'shi', '', NULL, '得弟消息二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('102793c0-2d3d-458f-a7e6-dfc302477324', '得弟消息二首 二', '得弟消息二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["汝懦歸無計，吾衰往未期。","浪傳烏鵲喜，深負鶺鴿詩。","生理何顏面，憂端且歲時。","兩京三十口，雖在命如絲。"]', '["汝懦归無計，吾衰往未期。","浪傳烏鵲喜，深負鶺鴿诗。","生理何顏面，憂端且歲时。","兩京三十口，雖在命如絲。"]', '诗', 'shi', '', NULL, '得弟消息二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb0d6385-8dff-4da5-b2c2-6e1a9b5cf48d', '憶弟二首 一', '憶弟二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["喪亂聞吾弟，飢寒傍濟州。","人稀吾不到，兵在見何由。","憶昨狂催走，無時病去憂。","即今千種恨，惟共水東流。"]', '["喪亂闻吾弟，飢寒傍濟州。","人稀吾不到，兵在见何由。","憶昨狂催走，無时病去憂。","即今千種恨，惟共水东流。"]', '诗', 'shi', '', NULL, '憶弟二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('964923ad-cd19-4377-9743-2b29b7b6e644', '憶弟二首 二', '憶弟二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["且喜河南定，不問鄴城圍。","百戰今誰在，三年望汝歸。","故園花自發，春日鳥還飛。","斷絕人煙久，東西消息稀。"]', '["且喜河南定，不问鄴城圍。","百戰今誰在，三年望汝归。","故园花自發，春日鸟還飞。","斷絕人煙久，东西消息稀。"]', '诗', 'shi', '', NULL, '憶弟二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2cf3e2d-249b-41bc-ba86-cd4f899dc840', '得舍弟消息', '得舍弟消息', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["亂後誰歸得，他鄉勝故鄉。","直爲心厄苦，久念與存亡。","汝書猶在壁，汝妾已辭房。","舊犬知愁恨，垂頭傍我牀。"]', '["亂後誰归得，他乡勝故乡。","直爲心厄苦，久念與存亡。","汝书猶在壁，汝妾已辞房。","旧犬知愁恨，垂头傍我牀。"]', '诗', 'shi', '', NULL, '得舍弟消息 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9a5c088-8d7d-44cf-9554-4b1bd43e9d6b', '秦州雜詩二十首 一', '秦州杂诗二十首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["滿目悲生事，因人作遠遊。","遲迴度隴怯，浩蕩及關愁。","水落魚龍夜，山空鳥鼠秋。","西征問烽火，心折此淹留。"]', '["满目悲生事，因人作远游。","遲迴度隴怯，浩蕩及关愁。","水落鱼龙夜，山空鸟鼠秋。","西征问烽火，心折此淹留。"]', '诗', 'shi', '', NULL, '秦州雜詩二十首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a725c40-d060-4cfb-a800-df3c309f66aa', '秦州雜詩二十首 二', '秦州杂诗二十首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["秦州山北寺，勝跡隗囂宮。","苔蘚山門古，丹青野殿空。","月明垂葉露，雲逐渡溪風。","清渭無情極，愁時獨向東。"]', '["秦州山北寺，勝跡隗囂宮。","苔蘚山门古，丹青野殿空。","月明垂葉露，云逐渡溪风。","清渭無情極，愁时独向东。"]', '诗', 'shi', '', NULL, '秦州雜詩二十首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5845a436-04f1-4954-a6e7-3ea1c4ac752a', '秦州雜詩二十首 三', '秦州杂诗二十首 三', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["州圖領同谷，驛道出流沙。","降虜兼千帳，居人有萬家。","馬驕珠汗落，胡舞白蹄斜。","年少臨洮子，西來亦自誇。"]', '["州圖領同谷，驛道出流沙。","降虜兼千帳，居人有万家。","马驕珠汗落，胡舞白蹄斜。","年少臨洮子，西来亦自誇。"]', '诗', 'shi', '', NULL, '秦州雜詩二十首 三 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cac3df5d-c0a0-4208-8fd5-794975b165b0', '秦州雜詩二十首 四', '秦州杂诗二十首 四', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["鼓角緣邊郡，川原欲夜時。","秋聽殷地發，風散入雲悲。","抱葉寒蟬靜，歸來獨鳥遲。","萬方聲一概，吾道竟何之。"]', '["鼓角緣邊郡，川原欲夜时。","秋听殷地發，风散入云悲。","抱葉寒蟬静，归来独鸟遲。","万方声一概，吾道竟何之。"]', '诗', 'shi', '', NULL, '秦州雜詩二十首 四 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90667fd7-b11e-44db-9dec-68cdba9e2fc5', '秦州雜詩二十首 五', '秦州杂诗二十首 五', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["南使宜天馬，由來萬匹強。","浮雲連陣沒，秋草徧山長。","聞說真龍種，仍殘老驌驦。","哀鳴思戰鬬，逈立向蒼蒼。"]', '["南使宜天马，由来万匹強。","浮云連陣沒，秋草徧山长。","闻说真龙種，仍殘老驌驦。","哀鳴思戰鬬，逈立向蒼蒼。"]', '诗', 'shi', '', NULL, '秦州雜詩二十首 五 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a5b7e29-19a8-4ca5-9911-b1e4803f5cd9', '秦州雜詩二十首 六', '秦州杂诗二十首 六', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["城上胡笳奏，山邊漢節歸。","防河赴滄海，奉詔發金微。","士苦形骸黑，旌疎鳥獸稀。","那聞往來戍，恨解鄴城圍。"]', '["城上胡笳奏，山邊漢節归。","防河赴滄海，奉詔發金微。","士苦形骸黑，旌疎鸟獸稀。","那闻往来戍，恨解鄴城圍。"]', '诗', 'shi', '', NULL, '秦州雜詩二十首 六 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee3631a2-3091-4beb-8356-a16d004ca08f', '秦州雜詩二十首 七', '秦州杂诗二十首 七', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["莽莽萬重山，孤城山谷間。","無風雲出塞，不夜月臨關。","屬國歸何晚，樓蘭斬未還。","煙塵獨長望，衰颯正摧顏。"]', '["莽莽万重山，孤城山谷间。","無风云出塞，不夜月臨关。","屬国归何晚，楼蘭斬未還。","煙塵独长望，衰颯正摧顏。"]', '诗', 'shi', '', NULL, '秦州雜詩二十首 七 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c716f7b3-931d-4deb-97dc-0e83232e0372', '秦州雜詩二十首 八', '秦州杂诗二十首 八', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["聞道尋源使，從天此路迴。","牽牛去幾許，宛馬至今來。","一望幽燕隔，何時郡國開。","東征健兒盡，羌笛暮吹哀。"]', '["闻道尋源使，從天此路迴。","牽牛去幾許，宛马至今来。","一望幽燕隔，何时郡国开。","东征健兒尽，羌笛暮吹哀。"]', '诗', 'shi', '', NULL, '秦州雜詩二十首 八 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c716801-1e00-42bc-8f99-473b707c6e3f', '秦州雜詩二十首 九', '秦州杂诗二十首 九', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["今日明人眼，臨池好驛亭。","叢篁低地碧，高柳半天青。","稠疊多幽事，喧呼閱使星。","老夫如有此，不異在郊坰。"]', '["今日明人眼，臨池好驛亭。","叢篁低地碧，高柳半天青。","稠叠多幽事，喧呼閱使星。","老夫如有此，不異在郊坰。"]', '诗', 'shi', '', NULL, '秦州雜詩二十首 九 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da88e355-99df-4d78-9680-2f61b0bf8336', '秦州雜詩二十首 十', '秦州杂诗二十首 十', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["雲氣接崑崙，涔涔塞雨繁。","羌童看渭水，使客向河源。","煙火軍中幕，牛羊嶺上村。","所居秋草淨，正閉小蓬門。"]', '["云氣接崑崙，涔涔塞雨繁。","羌童看渭水，使客向河源。","煙火軍中幕，牛羊嶺上村。","所居秋草淨，正閉小蓬门。"]', '诗', 'shi', '', NULL, '秦州雜詩二十首 十 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd56f333-f562-4b79-a24f-dda16cbf66d4', '秦州雜詩二十首 十一', '秦州杂诗二十首 十一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["蕭蕭古塞冷，漠漠秋雲低。","黃鵠翅垂雨，蒼鷹飢啄泥。","薊門誰自北，漢將獨征西。","不意書生耳，臨衰厭鼓鞞。"]', '["蕭蕭古塞冷，漠漠秋云低。","黄鵠翅垂雨，蒼鷹飢啄泥。","薊门誰自北，漢將独征西。","不意书生耳，臨衰厭鼓鞞。"]', '诗', 'shi', '', NULL, '秦州雜詩二十首 十一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0956099-4071-47fe-af2d-5c5826a58d19', '秦州雜詩二十首 十二', '秦州杂诗二十首 十二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["山頭南郭寺，水號北流泉。","老樹空庭得，清渠一邑傳。","秋花危石底，晚景臥鐘邊。","俯仰悲身世，溪風爲颯然。"]', '["山头南郭寺，水號北流泉。","老樹空庭得，清渠一邑傳。","秋花危石底，晚景臥鐘邊。","俯仰悲身世，溪风爲颯然。"]', '诗', 'shi', '', NULL, '秦州雜詩二十首 十二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c03d6d7-bcd3-42d0-9f9e-2b6ff6ec58ce', '秦州雜詩二十首 十三', '秦州杂诗二十首 十三', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["傳道東柯谷，深藏數十家。","對門藤蓋瓦，映竹水穿沙。","瘦地飜宜粟，陽坡可種瓜。","船人近相報，但恐失桃花。"]', '["傳道东柯谷，深藏數十家。","对门藤蓋瓦，映竹水穿沙。","瘦地飜宜粟，陽坡可種瓜。","船人近相報，但恐失桃花。"]', '诗', 'shi', '', NULL, '秦州雜詩二十首 十三 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4617163-8647-4cc2-bdcf-a3d6aeb2ee74', '秦州雜詩二十首 十四', '秦州杂诗二十首 十四', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["萬古仇池穴，潛通小有天。","神魚人不見，福地語真傳。","近接西南境，長懷十九泉。","何時一茅屋，送老白雲邊。"]', '["万古仇池穴，潛通小有天。","神鱼人不见，福地語真傳。","近接西南境，长懷十九泉。","何时一茅屋，送老白云邊。"]', '诗', 'shi', '', NULL, '秦州雜詩二十首 十四 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ccea1bac-1e88-45d6-859a-91e8cf29e811', '秦州雜詩二十首 十五', '秦州杂诗二十首 十五', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["未暇泛蒼海，悠悠兵馬間。","塞門風落木，客舍雨連山。","阮籍行多興，龐公隱不還。","東柯遂疎嬾，休鑷鬢毛斑。"]', '["未暇泛蒼海，悠悠兵马间。","塞门风落木，客舍雨連山。","阮籍行多兴，龐公隐不還。","东柯遂疎嬾，休鑷鬢毛斑。"]', '诗', 'shi', '', NULL, '秦州雜詩二十首 十五 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da625d4b-a775-4c5e-9860-4bfe89e481ce', '秦州雜詩二十首 十六', '秦州杂诗二十首 十六', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["東柯好崖谷，不與衆峰羣。","落日邀雙鳥，晴天養片雲。","野人矜險絕，水竹會平分。","采藥吾將老，兒童未遣聞。"]', '["东柯好崖谷，不與衆峰羣。","落日邀雙鸟，晴天養片云。","野人矜險絕，水竹會平分。","采藥吾將老，兒童未遣闻。"]', '诗', 'shi', '', NULL, '秦州雜詩二十首 十六 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5d1ccf8-66f3-4c96-aa51-a935cd0b71d4', '秦州雜詩二十首 十七', '秦州杂诗二十首 十七', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["邊秋陰易久，不復辨晨光。","檐雨亂淋幔，山雲低度牆。","鸕鶿窺淺井，蚯蚓上深堂。","車馬何蕭索，門前百草長。"]', '["邊秋陰易久，不复辨晨光。","檐雨亂淋幔，山云低度牆。","鸕鶿窺淺井，蚯蚓上深堂。","车马何蕭索，门前百草长。"]', '诗', 'shi', '', NULL, '秦州雜詩二十首 十七 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('060f8950-7f13-4184-8a7d-d5eb30c3bf01', '秦州雜詩二十首 十八', '秦州杂诗二十首 十八', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["地僻秋將盡，山高客未歸。","塞雲多斷績，邊日少光輝。","警急烽常報，傳聞檄屢飛。","西戎外甥國，何得迕天威。"]', '["地僻秋將尽，山高客未归。","塞云多斷績，邊日少光輝。","警急烽常報，傳闻檄屢飞。","西戎外甥国，何得迕天威。"]', '诗', 'shi', '', NULL, '秦州雜詩二十首 十八 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca525a27-f594-438d-99ba-e7de2ec3ac0a', '秦州雜詩二十首 十九', '秦州杂诗二十首 十九', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["鳳林戈未息，魚海路常難。","候火雲烽峻，懸軍幕井乾。","風連西極動，月過北庭寒。","故老思飛將，何時議築壇。"]', '["鳳林戈未息，鱼海路常难。","候火云烽峻，懸軍幕井乾。","风連西極动，月過北庭寒。","故老思飞將，何时議築壇。"]', '诗', 'shi', '', NULL, '秦州雜詩二十首 十九 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98910f3c-cec8-4530-9c3a-c0e34c39b3b6', '秦州雜詩二十首 二十', '秦州杂诗二十首 二十', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["唐堯真自聖，野老復何知。","曬藥能無婦，應門幸有兒。","藏書聞禹穴，讀記憶仇池。","爲報鴛行舊，鷦鷯在一枝。"]', '["唐堯真自聖，野老复何知。","曬藥能無婦，應门幸有兒。","藏书闻禹穴，读記憶仇池。","爲報鴛行旧，鷦鷯在一枝。"]', '诗', 'shi', '', NULL, '秦州雜詩二十首 二十 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1280e87-ac81-4f9b-9de5-377d6af38ae8', '月夜憶舍弟', '月夜憶舍弟', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["戍鼓斷人行，秋邊一雁聲。","露從今夜白，月是故鄉明。","有弟皆分散，無家問死生。","寄書長不避，況乃未休兵。"]', '["戍鼓斷人行，秋邊一雁声。","露從今夜白，月是故乡明。","有弟皆分散，無家问死生。","寄书长不避，況乃未休兵。"]', '诗', 'shi', '', NULL, '月夜憶舍弟 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c492d0a-ef0a-4938-8c65-fa50a5de7d5e', '宿贊公房', '宿贊公房', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["杖錫何來此，秋風已颯然。","雨荒深院菊，霜倒半池蓮。","放逐寧違性，虛空不離禪。","相逢成夜宿，隴月向人圓。"]', '["杖錫何来此，秋风已颯然。","雨荒深院菊，霜倒半池蓮。","放逐寧違性，虛空不離禪。","相逢成夜宿，隴月向人圓。"]', '诗', 'shi', '', NULL, '宿贊公房 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d449437-09a5-462b-86e5-e1ff2fdfc832', '東樓', '东楼', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["萬里流沙道，西征過北門。","但添新戰骨，不返舊征魂。","樓角臨風迥，城陰帶水昏。","傳聲看驛使，送節向河源。"]', '["万里流沙道，西征過北门。","但添新戰骨，不返旧征魂。","楼角臨风迥，城陰带水昏。","傳声看驛使，送節向河源。"]', '诗', 'shi', '', NULL, '東樓 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be9d4d46-2848-4724-aae8-dab695b16714', '雨晴', '雨晴', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["天水秋雲薄，從西萬里風。","今朝好晴景，久雨不妨農。","塞柳行疎翠，山棃結小紅。","胡笳樓上發，一雁入高空。"]', '["天水秋云薄，從西万里风。","今朝好晴景，久雨不妨農。","塞柳行疎翠，山棃結小紅。","胡笳楼上發，一雁入高空。"]', '诗', 'shi', '', NULL, '雨晴 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87fc6086-4359-4046-bde9-4d724d1f2d6d', '寓目', '寓目', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["一縣蒲萄熟，秋山苜蓿多。","關雲常帶雨，塞水不成河。","羌女輕烽燧，胡兒制駱駝。","自傷遲暮眼，喪亂飽經過。"]', '["一縣蒲萄熟，秋山苜蓿多。","关云常带雨，塞水不成河。","羌女轻烽燧，胡兒制駱駝。","自傷遲暮眼，喪亂飽經過。"]', '诗', 'shi', '', NULL, '寓目 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b73a514-a34d-4229-8583-cdbd778403d4', '山寺', '山寺', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["野寺殘僧少，山園細路高。","麝香眠石竹，鸚鵡啄金桃。","亂石通人過，懸崖置屋牢。","上方重閣晚，百里見秋毫。"]', '["野寺殘僧少，山园細路高。","麝香眠石竹，鸚鵡啄金桃。","亂石通人過，懸崖置屋牢。","上方重閣晚，百里见秋毫。"]', '诗', 'shi', '', NULL, '山寺 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5018a28-92f8-458f-92e2-cc62ce096164', '即事', '即事', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["聞道花門破，和親事却非。","人憐漢公主，生得渡河歸。","秋思拋雲髻，腰支勝寶衣。","羣兇猶索戰，回首意多違。"]', '["闻道花门破，和親事却非。","人怜漢公主，生得渡河归。","秋思拋云髻，腰支勝寶衣。","羣兇猶索戰，回首意多違。"]', '诗', 'shi', '', NULL, '即事 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1b76a70-be94-4373-b9d6-e52dc893e6b2', '遣懷', '遣懷', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["愁眼看霜露，寒城菊自花。","天風隨斷柳，客淚墮清笳。","水淨樓陰直，山昏塞日斜。","夜來歸鳥盡，啼殺後棲鴉。"]', '["愁眼看霜露，寒城菊自花。","天风隨斷柳，客泪墮清笳。","水淨楼陰直，山昏塞日斜。","夜来归鸟尽，啼殺後棲鴉。"]', '诗', 'shi', '', NULL, '遣懷 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54313608-eb28-4f12-9583-7a821d285ec4', '天河', '天河', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["常時任顯晦，秋至輒分明。","縱被微雲掩，終能永夜清。","含星動雙闕，伴月照邊城。","牛女年年渡，何曾風浪生。"]', '["常时任显晦，秋至輒分明。","縱被微云掩，終能永夜清。","含星动雙闕，伴月照邊城。","牛女年年渡，何曾风浪生。"]', '诗', 'shi', '', NULL, '天河 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4176367c-f23b-4d58-a008-22c48b9e5979', '初月', '初月', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["光細弦豈上，影斜輪未安。","微升古塞外，已隱暮雲端。","河漢不改色，關山空自寒。","庭前有白露，暗滿菊花團。"]', '["光細弦豈上，影斜輪未安。","微升古塞外，已隐暮云端。","河漢不改色，关山空自寒。","庭前有白露，暗满菊花團。"]', '诗', 'shi', '', NULL, '初月 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8e07cab-06f6-4ea0-a6b6-815bd8c22506', '歸燕', '归燕', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["不獨避霜雪，其如儔侶稀。","四時無失序，八月自知歸。","春色豈相訪，衆雛還識機。","故巢儻未毀，會傍主人飛。"]', '["不独避霜雪，其如儔侶稀。","四时無失序，八月自知归。","春色豈相訪，衆雛還識機。","故巢儻未毀，會傍主人飞。"]', '诗', 'shi', '', NULL, '歸燕 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d4a0228-d51b-462c-ae8b-4a811e5509a1', '擣衣', '擣衣', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["亦知戍不返，秋至拭清砧。","已近苦寒月，況經長別心。","寧辭擣熨倦，一寄塞垣深。","用盡閨中力，君聽空外音。"]', '["亦知戍不返，秋至拭清砧。","已近苦寒月，況經长別心。","寧辞擣熨倦，一寄塞垣深。","用尽閨中力，君听空外音。"]', '诗', 'shi', '', NULL, '擣衣 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef44ed15-6181-4597-93e9-94431ee9df4b', '促織', '促织', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["促織甚微細，哀音何動人。","草根吟不穩，牀下夜相親。","久客得無淚，放妻難及晨。","悲絲與急管，感激異天真。"]', '["促织甚微細，哀音何动人。","草根吟不穩，牀下夜相親。","久客得無泪，放妻难及晨。","悲絲與急管，感激異天真。"]', '诗', 'shi', '', NULL, '促織 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('337b1cbf-675e-490f-a23d-48bee622b21f', '螢火', '螢火', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["幸因腐草出，敢近太陽飛。","未足臨書卷，時能點客衣。","隨風隔幔小，帶雨傍林微。","十月清霜重，飄零何處歸。"]', '["幸因腐草出，敢近太陽飞。","未足臨书卷，时能点客衣。","隨风隔幔小，带雨傍林微。","十月清霜重，飄零何处归。"]', '诗', 'shi', '', NULL, '螢火 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5584095-bed0-43b3-a45b-a437877d266c', '蒹葭', '蒹葭', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["摧折不自守，秋風吹若何。","暫時花戴雪，幾處葉沈波。","體弱春風早，叢長夜露多。","江湖後搖落，亦恐歲蹉跎。"]', '["摧折不自守，秋风吹若何。","暫时花戴雪，幾处葉沈波。","體弱春风早，叢长夜露多。","江湖後搖落，亦恐歲蹉跎。"]', '诗', 'shi', '', NULL, '蒹葭 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ecf783d-8e3f-4d06-8560-11ba520f5e37', '苦竹', '苦竹', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["青冥亦自守，輭弱強扶持。","味苦夏蟲避，叢卑春鳥疑。","軒墀曾不重，剪伐欲無辭。","幸近幽人屋，霜根結在茲。"]', '["青冥亦自守，輭弱強扶持。","味苦夏蟲避，叢卑春鸟疑。","軒墀曾不重，剪伐欲無辞。","幸近幽人屋，霜根結在茲。"]', '诗', 'shi', '', NULL, '苦竹 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eacfad64-4b0a-461d-9f76-5ae2a1558ab7', '除架', '除架', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["束薪已零落，瓠葉轉蕭疎。","幸結白花了，寧辭青蔓除。","秋蟲聲不去，暮雀意何如。","寒事今牢落，人生亦有初。"]', '["束薪已零落，瓠葉轉蕭疎。","幸結白花了，寧辞青蔓除。","秋蟲声不去，暮雀意何如。","寒事今牢落，人生亦有初。"]', '诗', 'shi', '', NULL, '除架 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c72700e-23a9-4717-b52c-843621c092f1', '廢畦', '廢畦', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["秋蔬擁霜露，豈敢惜凋殘。","暮景數枝葉，天風吹汝寒。","綠霑泥滓盡，香與歲時闌。","生意春如昨，悲君白玉盤。"]', '["秋蔬擁霜露，豈敢惜凋殘。","暮景數枝葉，天风吹汝寒。","綠霑泥滓尽，香與歲时闌。","生意春如昨，悲君白玉盤。"]', '诗', 'shi', '', NULL, '廢畦 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71db67d2-6d13-444d-9ef4-0f7e1ef35d97', '夕烽', '夕烽', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["夕峰來不近，每日報平安。","塞上傳光小，雲邊落點殘。","照秦通警急，過隴自艱難。","聞道蓬萊殿，千門立馬看。"]', '["夕峰来不近，每日報平安。","塞上傳光小，云邊落点殘。","照秦通警急，過隴自艱难。","闻道蓬萊殿，千门立马看。"]', '诗', 'shi', '', NULL, '夕烽 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('964cf095-7893-4844-941b-9549a49cd3b1', '秋笛', '秋笛', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["清商欲盡奏，奏苦血霑衣。","他日傷心極，征人白骨歸。","相逢恐恨過，故作發聲微。","不見秋雲動，悲風稍稍飛。"]', '["清商欲尽奏，奏苦血霑衣。","他日傷心極，征人白骨归。","相逢恐恨過，故作發声微。","不见秋云动，悲风稍稍飞。"]', '诗', 'shi', '', NULL, '秋笛 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65526803-d701-435f-8d19-9fd9c960080c', '送遠', '送远', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["帶甲滿天地，胡爲君遠行。","親朋盡一哭，鞍馬去孤城。","草木歲月晚，關河霜雪清。","別離已昨日，因見古人情。"]', '["带甲满天地，胡爲君远行。","親朋尽一哭，鞍马去孤城。","草木歲月晚，关河霜雪清。","別離已昨日，因见古人情。"]', '诗', 'shi', '', NULL, '送遠 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7540b747-b085-435f-b814-8218b9a6313b', '觀兵', '观兵', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["北庭送壯士，貔虎數尤多。","精銳舊無敵，邊隅今若何。","妖氛擁白馬，元帥待彫戈。","莫守鄴城下，斬鯨遼海波。"]', '["北庭送壯士，貔虎數尤多。","精銳旧無敵，邊隅今若何。","妖氛擁白马，元帥待彫戈。","莫守鄴城下，斬鯨遼海波。"]', '诗', 'shi', '', NULL, '觀兵 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('916d6382-2751-4d92-8faf-9799436f778f', '不歸', '不归', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["河間尚征伐，汝骨在空城。","從弟人皆有，終身恨不平。","數金憐俊邁，總角愛聰明。","而上三年土，春風草又生。"]', '["河间尚征伐，汝骨在空城。","從弟人皆有，終身恨不平。","數金怜俊邁，總角愛聰明。","而上三年土，春风草又生。"]', '诗', 'shi', '', NULL, '不歸 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c036362-9f1d-434c-854f-b97a2a4bb19b', '天末憶李白', '天末憶李白', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["涼風起天末，君子意如何。","鴻雁幾時到，江湖秋水多。","文章憎命達，魑魅喜人過。","應共冤魂語，投詩贈汩羅。"]', '["涼风起天末，君子意如何。","鴻雁幾时到，江湖秋水多。","文章憎命達，魑魅喜人過。","應共冤魂語，投诗贈汩羅。"]', '诗', 'shi', '', NULL, '天末憶李白 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77190d46-4155-4a30-99e3-0534b8e9481b', '獨立', '独立', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["空外一鷙鳥，河間雙白鷗。","飄颻搏擊便，容易往來遊。","草露亦多濕，蛛絲仍未收。","天機近人事，獨立萬端憂。"]', '["空外一鷙鸟，河间雙白鷗。","飄颻搏擊便，容易往来游。","草露亦多濕，蛛絲仍未收。","天機近人事，独立万端憂。"]', '诗', 'shi', '', NULL, '獨立 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e2f3d54-351b-455a-8dbb-c4aada51996b', '日暮', '日暮', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["日落風亦起，城頭鳥尾訛。","黃雲高未動，白水已揚波。","羌婦語還哭，胡兒行且歌。","將軍別換馬，夜出擁彫戈。"]', '["日落风亦起，城头鸟尾訛。","黄云高未动，白水已揚波。","羌婦語還哭，胡兒行且歌。","將軍別換马，夜出擁彫戈。"]', '诗', 'shi', '', NULL, '日暮 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b34b8fd-9e51-4e5a-96fe-a168a11fe696', '空囊', '空囊', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["翠柏苦猶食，晨霞高可餐。","世人共鹵莽，吾道屬艱難。","不爨井晨凍，無衣牀夜寒。","囊空恐羞澀，留得一錢看。"]', '["翠柏苦猶食，晨霞高可餐。","世人共鹵莽，吾道屬艱难。","不爨井晨凍，無衣牀夜寒。","囊空恐羞澀，留得一錢看。"]', '诗', 'shi', '', NULL, '空囊 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('057c887c-9525-4a2e-b553-23d5afab9275', '病馬', '病马', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["乘爾亦已久，天寒關塞深。","塵中老盡力，歲晚病傷心。","毛骨豈殊衆，馴良猶至今。","物微意不淺，感動一沈吟。"]', '["乘爾亦已久，天寒关塞深。","塵中老尽力，歲晚病傷心。","毛骨豈殊衆，馴良猶至今。","物微意不淺，感动一沈吟。"]', '诗', 'shi', '', NULL, '病馬 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e4f767b-c903-4dcc-8e08-33ef70e81445', '蕃劒', '蕃劒', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["致此自僻遠，又非珠玉裝。","如何有奇怪，每夜吐光芒。","虎氣必騰趠，龍身寧久藏。","風塵苦未息，持汝奉明王。"]', '["致此自僻远，又非珠玉裝。","如何有奇怪，每夜吐光芒。","虎氣必腾趠，龙身寧久藏。","风塵苦未息，持汝奉明王。"]', '诗', 'shi', '', NULL, '蕃劒 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea9aa292-1c78-4494-b621-c8edd9329b96', '銅缾', '銅缾', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["Ｂ亂後碧井廢，時清瑤殿深。","銅缾未失水，百丈有哀音。","側想美人意，應非寒甃沈。","蛟龍半缺落，猶得折黃金。"]', '["Ｂ亂後碧井廢，时清瑤殿深。","銅缾未失水，百丈有哀音。","側想美人意，應非寒甃沈。","蛟龙半缺落，猶得折黄金。"]', '诗', 'shi', '', NULL, '銅缾 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57d11f12-bb85-47ff-9b97-0676acc9d4bc', '觀安西兵過赴關中待命二首 一', '观安西兵過赴关中待命二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["四鎮富精銳，摧鋒皆絕倫。","還聞獻士卒，足以靜風塵。","老馬夜知道，蒼鷹飢著人。","臨危經久戰，用急始如神。"]', '["四鎮富精銳，摧鋒皆絕倫。","還闻獻士卒，足以静风塵。","老马夜知道，蒼鷹飢著人。","臨危經久戰，用急始如神。"]', '诗', 'shi', '', NULL, '觀安西兵過赴關中待命二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('111f8ccd-6456-408c-86d6-0bbdbdf1a41e', '觀安西兵過赴關中待命二首 二', '观安西兵過赴关中待命二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["奇兵不在衆，萬馬救中原。","談笑無河北，心肝奉至尊。","孤雲隨殺氣，飛鳥避轅門。","竟日留歡樂，城池未覺喧。"]', '["奇兵不在衆，万马救中原。","談笑無河北，心肝奉至尊。","孤云隨殺氣，飞鸟避轅门。","竟日留歡乐，城池未覺喧。"]', '诗', 'shi', '', NULL, '觀安西兵過赴關中待命二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('530eb94b-97b1-4630-8005-556cfd4a53d3', '送人從軍', '送人從軍', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["弱水應無地，陽關已近天。","今君渡沙磧，累月斷人煙。","好武寧論命，封侯不計年。","馬寒防失道，雪沒錦鞍韉。"]', '["弱水應無地，陽关已近天。","今君渡沙磧，累月斷人煙。","好武寧論命，封侯不計年。","马寒防失道，雪沒錦鞍韉。"]', '诗', 'shi', '', NULL, '送人從軍 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('342116e5-c4b1-48a4-968c-68e9e7a4057d', '野望', '野望', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["清秋望不極，迢遰起曾陰。","遠水兼天淨，孤城隱霧深。","葉稀風更落，山迥日初沈。","獨鶴歸何晚，昏鴉已滿林。"]', '["清秋望不極，迢遰起曾陰。","远水兼天淨，孤城隐霧深。","葉稀风更落，山迥日初沈。","独鹤归何晚，昏鴉已满林。"]', '诗', 'shi', '', NULL, '野望 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d305b310-788d-4242-a9df-be50bdb884a0', '示姪佐', '示姪佐', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["多病秋風落，君來慰眼前。","自聞茅屋趣，只想竹林眠。","滿谷山雲起，侵籬澗水懸。","嗣宗諸子姪，早覺仲容賢。"]', '["多病秋风落，君来慰眼前。","自闻茅屋趣，只想竹林眠。","满谷山云起，侵籬澗水懸。","嗣宗諸子姪，早覺仲容賢。"]', '诗', 'shi', '', NULL, '示姪佐 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4ebe616-20f4-4b12-964a-8b1f41f7dbab', '佐還山後寄三首 一', '佐還山後寄三首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["山晚浮雲合，歸時恐路迷。","澗寒人欲到，村黑鳥應棲。","野客茅茨小，田家樹木低。","舊諳疎嬾叔，須汝故相攜。"]', '["山晚浮云合，归时恐路迷。","澗寒人欲到，村黑鸟應棲。","野客茅茨小，田家樹木低。","旧諳疎嬾叔，須汝故相携。"]', '诗', 'shi', '', NULL, '佐還山後寄三首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24ca9d45-cb54-4cfe-bd3c-00c7ff303385', '佐還山後寄三首 二', '佐還山後寄三首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["白露黃粱熟，分張素有期。","已應舂得細，頗覺寄來遲。","味豈同金菊，香宜配綠葵。","老人佗日愛，正想滑流匙。"]', '["白露黄粱熟，分張素有期。","已應舂得細，頗覺寄来遲。","味豈同金菊，香宜配綠葵。","老人佗日愛，正想滑流匙。"]', '诗', 'shi', '', NULL, '佐還山後寄三首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba4d7faa-1894-49de-9902-b426b4bc250b', '佐還山後寄三首 三', '佐還山後寄三首 三', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["幾道泉澆圃，交橫落慢坡。","葳蕤秋葉少，隱映野雲多。","隔沼連香芰，通林帶女蘿。","甚聞霜薤白，重惠意如何。"]', '["幾道泉澆圃，交橫落慢坡。","葳蕤秋葉少，隐映野云多。","隔沼連香芰，通林带女蘿。","甚闻霜薤白，重惠意如何。"]', '诗', 'shi', '', NULL, '佐還山後寄三首 三 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('257315b5-3e86-4d9e-96ea-0855de476059', '從人覓小胡孫許寄', '從人覓小胡孫許寄', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["人說南州路，山猨樹樹懸。","舉家聞若駭，爲寄小如拳。","預哂愁胡面，初調見馬鞭。","許求聰慧者，童稚捧應癲。"]', '["人说南州路，山猨樹樹懸。","舉家闻若駭，爲寄小如拳。","預哂愁胡面，初調见马鞭。","許求聰慧者，童稚捧應癲。"]', '诗', 'shi', '', NULL, '從人覓小胡孫許寄 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7499d3c4-f9ec-44f6-ab1f-ac3c83471ee8', '秋日阮隱居致薤三十束', '秋日阮隐居致薤三十束', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["隱者柴門內，畦蔬繞舍秋。","盈筐承露薤，不待致書求。","束比青芻色，圓齊玉箸頭。","衰年關鬲冷，味煖幷無憂。"]', '["隐者柴门內，畦蔬繞舍秋。","盈筐承露薤，不待致书求。","束比青芻色，圓齊玉箸头。","衰年关鬲冷，味煖幷無憂。"]', '诗', 'shi', '', NULL, '秋日阮隱居致薤三十束 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf724cea-153c-470e-ae32-aba401213d55', '秦州見敕目薛三璩授司議郎畢四曜除監察與二子有故遠喜遷官兼述索居凡三十韻', '秦州见敕目薛三璩授司議郎畢四曜除監察與二子有故远喜遷官兼述索居凡三十韻', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["大雅何寥闊，斯人尚典刑。","交期余潦倒，材力爾精靈。","二子聲同日，諸生困一經。","文章開穾奧，遷擢潤朝廷。","舊好何由展，新詩更憶聽。","別來頭幷白，相見眼終青。","伊昔貧皆甚，同憂心不寧。","栖遑分半菽，浩蕩逐流萍。","俗態猶猜忌，妖氛忽杳冥。","獨慙投漢閣，俱議哭秦庭。","遠蜀祗無補，囚梁亦固扃。","華夷相混合，宇宙一羶腥。","帝力收三統，天威總四溟。","舊都俄望幸，清廟肅惟馨。","雜種雖高壘，長驅甚建瓴。","焚香淑景殿，漲水望雲亭。","法駕初還日，羣公若會星。","宮臣仍點染，柱史正零丁。","官忝趨棲鳳，朝回歎聚螢。","喚人看腰褭，不嫁惜娉婷。","掘劒知埋獄，提刀見發硎。","侏儒應共飽，漁父忌偏醒。","旅泊窮清渭，長吟望濁涇。","羽書還似急，烽火未全停。","師老資殘寇，戎生及近坰。","忠臣辭憤激，烈士涕飄零。","上將盈邊鄙，元勳溢鼎銘。","仰思調玉燭，誰定握青萍。","隴俗輕鸚鵡，原情類鶺鴒。","秋風動關塞，高臥想儀行。"]', '["大雅何寥闊，斯人尚典刑。","交期余潦倒，材力爾精靈。","二子声同日，諸生困一經。","文章开穾奧，遷擢潤朝廷。","旧好何由展，新诗更憶听。","別来头幷白，相见眼終青。","伊昔貧皆甚，同憂心不寧。","栖遑分半菽，浩蕩逐流萍。","俗態猶猜忌，妖氛忽杳冥。","独慙投漢閣，俱議哭秦庭。","远蜀祗無補，囚梁亦固扃。","华夷相混合，宇宙一羶腥。","帝力收三統，天威總四溟。","旧都俄望幸，清廟肅惟馨。","杂種雖高壘，长驱甚建瓴。","焚香淑景殿，漲水望云亭。","法駕初還日，羣公若會星。","宮臣仍点染，柱史正零丁。","官忝趨棲鳳，朝回歎聚螢。","喚人看腰褭，不嫁惜娉婷。","掘劒知埋獄，提刀见發硎。","侏儒應共飽，漁父忌偏醒。","旅泊窮清渭，长吟望濁涇。","羽书還似急，烽火未全停。","師老資殘寇，戎生及近坰。","忠臣辞憤激，烈士涕飄零。","上將盈邊鄙，元勳溢鼎銘。","仰思調玉燭，誰定握青萍。","隴俗轻鸚鵡，原情類鶺鴒。","秋风动关塞，高臥想儀行。"]', '诗', 'shi', '', NULL, '秦州見敕目薛三璩授司議郎畢四曜除監察與二子有故遠喜遷官兼述索居凡三十韻 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad25550b-b0b6-49cd-981a-88d90471b624', '寄彭州高三十五使君適虢州岑二十七長史參三十韻', '寄彭州高三十五使君適虢州岑二十七长史參三十韻', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["故人何寂寞，今我獨淒涼。","老去才難盡，秋來興甚長。","物情尤可見，辭客未能忘。","海內知名士，雲端各異方。","高岑殊緩步，沈鮑得同行。","意愜關飛動，篇終接混茫。","舉天悲富駱，近代惜盧王。","似爾官仍貴，前賢命可傷。","諸侯非棄擲，半刺已翱翔。","詩好幾時見，書成無信將。","男兒行處是，客子鬬身強。","羈旅推賢聖，沈綿抵咎殃。","三年猶瘧疾，一鬼不銷亡。","隔日搜脂髓，增寒抱雪霜。","徒然潛隙地，有靦屢鮮妝。","何太龍鍾極，於今出處妨。","無錢居帝里，盡室在邊疆。","劉表雖遺恨，龐公至死藏。","心微傍魚鳥，肉瘦怯豺狼。","隴草蕭蕭白，洮雲片片黃。","彭門劒閣外，虢略鼎湖旁。","荆玉簪頭冷，巴箋染翰光。","烏麻蒸續曬，丹橘露應嘗。","豈異神仙宅，俱兼山水鄉。","竹齋燒藥竈，花嶼讀書牀。","更得清新否，遙知對屬忙。","舊宮寧改漢，淳俗本歸唐。","濟世宜公等，安貧亦士常。","蚩尤終戮辱，胡羯漫猖狂。","會待祅氛靜，論文暫裹糧。"]', '["故人何寂寞，今我独淒涼。","老去才难尽，秋来兴甚长。","物情尤可见，辞客未能忘。","海內知名士，云端各異方。","高岑殊緩步，沈鲍得同行。","意愜关飞动，篇終接混茫。","舉天悲富駱，近代惜盧王。","似爾官仍貴，前賢命可傷。","諸侯非棄擲，半刺已翱翔。","诗好幾时见，书成無信將。","男兒行处是，客子鬬身強。","羈旅推賢聖，沈綿抵咎殃。","三年猶瘧疾，一鬼不銷亡。","隔日搜脂髓，增寒抱雪霜。","徒然潛隙地，有靦屢鲜妝。","何太龙鍾極，於今出处妨。","無錢居帝里，尽室在邊疆。","劉表雖遺恨，龐公至死藏。","心微傍鱼鸟，肉瘦怯豺狼。","隴草蕭蕭白，洮云片片黄。","彭门劒閣外，虢略鼎湖旁。","荆玉簪头冷，巴箋染翰光。","烏麻蒸續曬，丹橘露應嘗。","豈異神仙宅，俱兼山水乡。","竹斋燒藥竈，花嶼读书牀。","更得清新否，遙知对屬忙。","旧宮寧改漢，淳俗本归唐。","濟世宜公等，安貧亦士常。","蚩尤終戮辱，胡羯漫猖狂。","會待祅氛静，論文暫裹糧。"]', '诗', 'shi', '', NULL, '寄彭州高三十五使君適虢州岑二十七長史參三十韻 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33123302-8a66-424b-afcd-44ef1d671410', '寄岳州賈司馬六丈巴州嚴八使君兩閣老五十韻', '寄岳州賈司马六丈巴州嚴八使君兩閣老五十韻', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["衡岳啼猨裏，巴州鳥道邊。","故人俱不利，謫宦兩悠然。","開闢乾坤正，榮枯雨露偏。","長沙才子遠，釣瀨客星懸。","憶昨趨行殿，殷憂捧御筵。","討胡愁李廣，奉使待張騫。","無復雲臺仗，虛修水戰船。","蒼茫城七十，流落劒三千。","畫角吹秦晉，旄頭俯澗瀍。","小儒輕董卓，有識笑苻堅。","浪作禽填海，那將血射天。","萬方思助順，一鼓氣無前。","陰散陳倉北，晴熏太白巔。","亂麻屍積衛，破竹勢臨燕。","法駕還雙闕，王師下八川。","此時霑奉引，佳氣拂周旋。","貔虎開金甲，麒麟受玉鞭。","侍臣諳入仗，廄馬解登仙。","花動朱樓雪，城凝碧樹煙。","衣冠心慘愴，故老淚潺湲。","哭廟悲風急，朝正霽景鮮。","月分梁漢米，春得水衡錢。","內蘂繁於纈，宮莎輭勝緜。","恩榮同拜手，出入最隨肩。","晚著華堂醉，寒重繡被眠。","轡齊兼秉燭，書枉滿懷牋。","每覺升元輔，深期列大賢。","秉鈞方咫尺，鎩翮再聊翩。","禁掖朋從改，微班性命全。","青蒲甘受戮，白髮竟誰憐。","弟子貧原憲，諸生老伏虔。","師資謙未達，鄉黨敬何先。","舊好腸堪斷，新愁眼欲穿。","翠乾危棧竹，紅膩小湖蓮。","賈筆論孤憤，嚴詩賦幾篇。","定知深意苦，莫使衆人傳。","貝錦無停織，朱絲有斷弦。","浦鷗防碎首，霜鶻不空拳。","地僻昏炎瘴，山稠隘石泉。","且將棊度日，應用酒爲年。","典郡終微眇，治中實棄捐。","安排求傲吏，比興展歸田。","去去才難得，蒼蒼理又玄。","古人稱逝矣，吾道卜終焉。","隴外飜投迹，漁陽復控弦。","笑爲妻子累，甘與歲時遷。","親故行稀少，兵戈動接聯。","他鄉饒夢寐，失侶自屯邅。","多病加淹泊，長吟阻靜便。","如公盡雄俊，志在必騰騫。"]', '["衡岳啼猨裏，巴州鸟道邊。","故人俱不利，謫宦兩悠然。","开闢乾坤正，榮枯雨露偏。","长沙才子远，釣瀨客星懸。","憶昨趨行殿，殷憂捧御筵。","討胡愁李廣，奉使待張騫。","無复云台仗，虛修水戰船。","蒼茫城七十，流落劒三千。","畫角吹秦晉，旄头俯澗瀍。","小儒轻董卓，有識笑苻堅。","浪作禽填海，那將血射天。","万方思助順，一鼓氣無前。","陰散陳倉北，晴熏太白巔。","亂麻屍積衛，破竹勢臨燕。","法駕還雙闕，王師下八川。","此时霑奉引，佳氣拂周旋。","貔虎开金甲，麒麟受玉鞭。","侍臣諳入仗，廄马解登仙。","花动朱楼雪，城凝碧樹煙。","衣冠心慘愴，故老泪潺湲。","哭廟悲风急，朝正霽景鲜。","月分梁漢米，春得水衡錢。","內蘂繁於纈，宮莎輭勝緜。","恩榮同拜手，出入最隨肩。","晚著华堂醉，寒重繡被眠。","轡齊兼秉燭，书枉满懷牋。","每覺升元輔，深期列大賢。","秉鈞方咫尺，鎩翮再聊翩。","禁掖朋從改，微班性命全。","青蒲甘受戮，白髮竟誰怜。","弟子貧原憲，諸生老伏虔。","師資謙未達，乡黨敬何先。","旧好腸堪斷，新愁眼欲穿。","翠乾危棧竹，紅膩小湖蓮。","賈笔論孤憤，嚴诗賦幾篇。","定知深意苦，莫使衆人傳。","貝錦無停织，朱絲有斷弦。","浦鷗防碎首，霜鶻不空拳。","地僻昏炎瘴，山稠隘石泉。","且將棊度日，應用酒爲年。","典郡終微眇，治中實棄捐。","安排求傲吏，比兴展归田。","去去才难得，蒼蒼理又玄。","古人稱逝矣，吾道卜終焉。","隴外飜投迹，漁陽复控弦。","笑爲妻子累，甘與歲时遷。","親故行稀少，兵戈动接聯。","他乡饒梦寐，失侶自屯邅。","多病加淹泊，长吟阻静便。","如公尽雄俊，志在必腾騫。"]', '诗', 'shi', '', NULL, '寄岳州賈司馬六丈巴州嚴八使君兩閣老五十韻 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('186aab50-4ead-4c61-9764-1867aec86f52', '寄張十二山人彪三十韻', '寄張十二山人彪三十韻', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["獨臥蒿陽客，三違潁水春。","艱難隨老母，慘澹向時人。","謝氏尋山屐，陶公漉酒巾。","羣兇彌宇宙，此物在風塵。","歷下辭姜被，關西得孟鄰。","早通交契密，晚接道流新。","靜者心多妙，先生藝絕倫。","草書何太苦，詩興不無神。","曹植休前輩，張芝更後身。","數篇吟可老，一字買堪貧。","將恐曾防寇，深潛託所親。","寧聞倚門夕，盡力潔飧晨。","疎嬾爲名誤，驅馳喪我真。","索居猶寂寞，相遇益悲辛。","流轉依邊徼，逢迎念席珍。","時來故舊少，亂後別離頻。","世祖修高廟，文公賞從臣。","商山猶入楚，源水不離秦。","存想青龍祕，騎行白鹿馴。","耕巖非谷口，結草即河濱。","肘後符應驗，囊中藥未陳。","旅懷殊不愜，良覿渺無因。","自古皆悲恨，浮生有屈伸。","此邦今尚武，何處且依仁。","鼓角凌天籟，關山信月輪。","官場羅鎮磧，賊火近洮岷。","蕭索論兵地，蒼茫鬬將辰。","大軍多處所，餘孽尚紛綸。","高興知籠鳥，斯文起獲麟。","窮秋正搖落，回首望松筠。"]', '["独臥蒿陽客，三違潁水春。","艱难隨老母，慘澹向时人。","謝氏尋山屐，陶公漉酒巾。","羣兇彌宇宙，此物在风塵。","歷下辞姜被，关西得孟鄰。","早通交契密，晚接道流新。","静者心多妙，先生藝絕倫。","草书何太苦，诗兴不無神。","曹植休前輩，張芝更後身。","數篇吟可老，一字買堪貧。","將恐曾防寇，深潛託所親。","寧闻倚门夕，尽力潔飧晨。","疎嬾爲名誤，驱驰喪我真。","索居猶寂寞，相遇益悲辛。","流轉依邊徼，逢迎念席珍。","时来故旧少，亂後別離頻。","世祖修高廟，文公賞從臣。","商山猶入楚，源水不離秦。","存想青龙祕，騎行白鹿馴。","耕巖非谷口，結草即河濱。","肘後符應驗，囊中藥未陳。","旅懷殊不愜，良覿渺無因。","自古皆悲恨，浮生有屈伸。","此邦今尚武，何处且依仁。","鼓角凌天籟，关山信月輪。","官場羅鎮磧，賊火近洮岷。","蕭索論兵地，蒼茫鬬將辰。","大軍多处所，餘孽尚紛綸。","高兴知籠鸟，斯文起獲麟。","窮秋正搖落，回首望松筠。"]', '诗', 'shi', '', NULL, '寄張十二山人彪三十韻 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e80bca1f-12ef-4187-b623-b614aa6bee78', '寄李十二白二十韻', '寄李十二白二十韻', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["昔年有狂客，號爾謫仙人。","筆落驚風雨，詩成泣鬼神。","聲名從此大，汩沒一朝伸。","文彩承殊渥，流傳必絕倫。","龍舟移櫂晚，獸錦奪袍新。","白日來深殿，青雲滿後塵。","乞歸優詔許，遇我宿心親。","未負幽棲志，兼全寵辱身。","劇談憐野逸，嗜酒見天真。","醉舞梁園夜，行歌泗水春。","才高心不展，道屈善無鄰。","處士禰衡俊，諸生原憲貧。","稻粱求未足，薏苡謗何頻。","五嶺炎蒸地，三危放逐臣。","幾年遭鵩鳥，獨泣向麒麟。","蘇武先還漢，黃公豈事秦。","楚筵辭醴日，梁獄上書辰。","已用當時法，誰將此義陳。","老吟秋月下，病起暮江濱。","莫怪恩波隔，乘槎與問津。"]', '["昔年有狂客，號爾謫仙人。","笔落驚风雨，诗成泣鬼神。","声名從此大，汩沒一朝伸。","文彩承殊渥，流傳必絕倫。","龙舟移櫂晚，獸錦奪袍新。","白日来深殿，青云满後塵。","乞归優詔許，遇我宿心親。","未負幽棲志，兼全寵辱身。","劇談怜野逸，嗜酒见天真。","醉舞梁园夜，行歌泗水春。","才高心不展，道屈善無鄰。","处士禰衡俊，諸生原憲貧。","稻粱求未足，薏苡謗何頻。","五嶺炎蒸地，三危放逐臣。","幾年遭鵩鸟，独泣向麒麟。","蘇武先還漢，黄公豈事秦。","楚筵辞醴日，梁獄上书辰。","已用當时法，誰將此義陳。","老吟秋月下，病起暮江濱。","莫怪恩波隔，乘槎與问津。"]', '诗', 'shi', '', NULL, '寄李十二白二十韻 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a353dcb1-12cc-4ca8-af1e-55d1d62445f8', '蜀相', '蜀相', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["丞相祠堂何處尋，錦官城外柏森森。","映堦碧草自春色，隔葉黃鸝空好音。","三顧頻煩天下計，兩朝開濟老臣心。","出師未捷身先死，長使英雄淚滿襟。"]', '["丞相祠堂何处尋，錦官城外柏森森。","映堦碧草自春色，隔葉黄鸝空好音。","三顧頻煩天下計，兩朝开濟老臣心。","出師未捷身先死，长使英雄泪满襟。"]', '诗', 'shi', '', NULL, '蜀相 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ffa6c105-9135-4b40-91e9-760296dc673b', '卜居', '卜居', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["浣花流水水西頭，主人爲卜林塘幽。","已知出郭少塵事，更有澄江銷客愁。","無數蜻蜓齊上下，一雙鸂鶒對沈浮。","東行萬里堪乘興，須向山陰上小舟。"]', '["浣花流水水西头，主人爲卜林塘幽。","已知出郭少塵事，更有澄江銷客愁。","無數蜻蜓齊上下，一雙鸂鶒对沈浮。","东行万里堪乘兴，須向山陰上小舟。"]', '诗', 'shi', '', NULL, '卜居 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('653beb5d-33b0-40bf-8877-3fe058dd473c', '一室', '一室', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["一室他鄉遠，空林暮景懸。","正愁聞塞笛，獨立見江船。","巴蜀來多病，荆蠻去幾年。","應同王粲宅，留井峴山前。"]', '["一室他乡远，空林暮景懸。","正愁闻塞笛，独立见江船。","巴蜀来多病，荆蠻去幾年。","應同王粲宅，留井峴山前。"]', '诗', 'shi', '', NULL, '一室 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d30b4748-72eb-4f1d-b8de-99126216c38c', '梅雨', '梅雨', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["南京西浦道，四月熟黃梅。","湛湛長江去，冥冥細雨來。","茅茨疎易濕，雲霧密難開。","竟日蛟龍喜，盤渦與岸迴。"]', '["南京西浦道，四月熟黄梅。","湛湛长江去，冥冥細雨来。","茅茨疎易濕，云霧密难开。","竟日蛟龙喜，盤渦與岸迴。"]', '诗', 'shi', '', NULL, '梅雨 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70d380f8-bc23-408b-8b97-d17b81beb068', '爲農', '爲農', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["錦里煙塵外，江村八九家。","圓荷浮小葉，細麥落輕花。","卜宅從茲老，爲農去國賒。","遠慚句漏令，不得問丹砂。"]', '["錦里煙塵外，江村八九家。","圓荷浮小葉，細麦落轻花。","卜宅從茲老，爲農去国賒。","远慚句漏令，不得问丹砂。"]', '诗', 'shi', '', NULL, '爲農 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9eb7ec2-9795-4b96-bf52-2b23cf2ca4f1', '有客', '有客', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["幽棲地僻經過少，老病人扶再拜難。","豈有文章驚海內，漫勞車馬駐江干。","竟日淹留佳客坐，百年麤糲腐儒餐。","不嫌野外無供給，乘興還來看藥欄。"]', '["幽棲地僻經過少，老病人扶再拜难。","豈有文章驚海內，漫勞车马駐江干。","竟日淹留佳客坐，百年麤糲腐儒餐。","不嫌野外無供給，乘兴還来看藥欄。"]', '诗', 'shi', '', NULL, '有客 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81c77b01-47cd-4aba-a980-5bc74b5b9711', '狂夫', '狂夫', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["萬里橋西一，草堂，百花潭水即滄浪。","風含翠篠娟娟靜，雨裛紅蕖冉冉香。","厚祿故人書斷絕，恒飢稚子色淒涼。","欲填溝壑唯疎放，自笑狂夫老更狂。"]', '["万里橋西一，草堂，百花潭水即滄浪。","风含翠篠娟娟静，雨裛紅蕖冉冉香。","厚祿故人书斷絕，恒飢稚子色淒涼。","欲填溝壑唯疎放，自笑狂夫老更狂。"]', '诗', 'shi', '', NULL, '狂夫 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16efc3a7-3ee7-473f-96ec-e25516cfe2cb', '賓至', '賓至', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["患氣經時久，臨江卜宅新。","喧卑方避俗，疎快頗宜人。","有客過茅宇，呼兒正葛巾。","自鋤稀菜甲，小摘爲情親。"]', '["患氣經时久，臨江卜宅新。","喧卑方避俗，疎快頗宜人。","有客過茅宇，呼兒正葛巾。","自鋤稀菜甲，小摘爲情親。"]', '诗', 'shi', '', NULL, '賓至 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7666f1f3-5124-440d-af0b-735914481fc1', '王十五司馬弟出郭相訪兼遺營茅屋貲', '王十五司马弟出郭相訪兼遺營茅屋貲', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["客裏何遷次，江邊正寂寥。","肯來尋一老，愁破是今朝。","憂我營茅棟，攜錢過野橋。","他鄉唯表弟，還往莫辭遙。"]', '["客裏何遷次，江邊正寂寥。","肯来尋一老，愁破是今朝。","憂我營茅棟，携錢過野橋。","他乡唯表弟，還往莫辞遙。"]', '诗', 'shi', '', NULL, '王十五司馬弟出郭相訪兼遺營茅屋貲 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9775db8-a4b0-4a95-a6e5-3424d5159c97', '堂成', '堂成', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["背郭堂成蔭白茅，緣江路熟俯青郊。","榿林礙日吟風葉，籠竹和煙滴露梢。","暫止飛烏將數子，頻來語燕定新巢。","旁人錯比揚雄宅，嬾惰無心作解嘲。"]', '["背郭堂成蔭白茅，緣江路熟俯青郊。","榿林礙日吟风葉，籠竹和煙滴露梢。","暫止飞烏將數子，頻来語燕定新巢。","旁人錯比揚雄宅，嬾惰無心作解嘲。"]', '诗', 'shi', '', NULL, '堂成 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f54c52d8-8544-482e-9b63-34f6f3b1bdd6', '田舍', '田舍', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["田舍清江曲，柴門古道旁。","草深迷市井，地僻嬾衣裳。","櫸柳枝枝弱，枇杷樹樹香。","鸕鶿西日照，曬翅滿魚梁。"]', '["田舍清江曲，柴门古道旁。","草深迷市井，地僻嬾衣裳。","櫸柳枝枝弱，枇杷樹樹香。","鸕鶿西日照，曬翅满鱼梁。"]', '诗', 'shi', '', NULL, '田舍 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d453f469-2a2c-48a1-8581-0193560729f3', '進艇', '進艇', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["南京久客耕南畝，北望傷神坐北窗。","晝引老妻乘小艇，晴看稚子浴清江。","俱飛蛺蝶元相逐，并蔕芙蓉本自雙。","茗飲蔗漿攜所有，瓷甖無謝玉爲缸。"]', '["南京久客耕南畝，北望傷神坐北窗。","晝引老妻乘小艇，晴看稚子浴清江。","俱飞蛺蝶元相逐，并蔕芙蓉本自雙。","茗饮蔗漿携所有，瓷甖無謝玉爲缸。"]', '诗', 'shi', '', NULL, '進艇 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7147a2b9-5940-46c4-b48b-9316c8112ba1', '西郊', '西郊', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["時出碧雞坊，西郊向草堂。","市橋官柳細，江路野梅香。","傍架齊書帙，看題減藥囊。","無人覺來往，疎嬾意何長。"]', '["时出碧雞坊，西郊向草堂。","市橋官柳細，江路野梅香。","傍架齊书帙，看題減藥囊。","無人覺来往，疎嬾意何长。"]', '诗', 'shi', '', NULL, '西郊 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bad1eb23-f31e-4099-bc52-9a9c7e10bb06', '所思', '所思', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["苦憶荆州醉司馬，謫官樽俎定常開。","九江日落醒何處，一柱觀頭眠幾回。","可憐懷抱向人盡，欲問平安無使來。","故憑錦水將雙淚，好過瞿塘灧澦堆。"]', '["苦憶荆州醉司马，謫官樽俎定常开。","九江日落醒何处，一柱观头眠幾回。","可怜懷抱向人尽，欲问平安無使来。","故憑錦水將雙泪，好過瞿塘灧澦堆。"]', '诗', 'shi', '', NULL, '所思 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5546090-d778-47ce-abde-d3184e225f64', '江村', '江村', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["清江一曲抱村流，長夏江村事事幽。","自去自來堂上燕，相親相近水中鷗。","老妻畫紙爲碁局，稚子敲鍼作釣鉤。","多病所須唯藥物，微軀此外更何求。"]', '["清江一曲抱村流，长夏江村事事幽。","自去自来堂上燕，相親相近水中鷗。","老妻畫紙爲碁局，稚子敲鍼作釣鉤。","多病所須唯藥物，微軀此外更何求。"]', '诗', 'shi', '', NULL, '江村 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a6e1b7d-494b-4ffe-94ac-2b69f9784f35', '江漲', '江漲', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["江漲柴門外，兒童報急流。","下牀高數尺，倚杖沒中洲。","細動迎風燕，輕搖逐浪鷗。","漁人縈小楫，容易拔船頭。"]', '["江漲柴门外，兒童報急流。","下牀高數尺，倚杖沒中洲。","細动迎风燕，轻搖逐浪鷗。","漁人縈小楫，容易拔船头。"]', '诗', 'shi', '', NULL, '江漲 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d3b137e-8d62-4d8d-be0f-88c9589f8ae6', '野老', '野老', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["野老籬前江岸迴，柴門不正逐江開。","漁人網集澄潭下，賈客船隨返照來。","長路關心悲劒閣，片雲何意傍琴臺。","王師未報收東郡，城闕秋生畫角哀。"]', '["野老籬前江岸迴，柴门不正逐江开。","漁人網集澄潭下，賈客船隨返照来。","长路关心悲劒閣，片云何意傍琴台。","王師未報收东郡，城闕秋生畫角哀。"]', '诗', 'shi', '', NULL, '野老 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39f705dc-3756-4ec4-bbc3-ea2e48e3e010', '雲山', '云山', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["京洛雲山外，音書靜不來。","神交作賦客，力盡望鄉臺。","衰疾江邊臥，親朋日暮迴。","白鷗元水宿，何事有餘哀。"]', '["京洛云山外，音书静不来。","神交作賦客，力尽望乡台。","衰疾江邊臥，親朋日暮迴。","白鷗元水宿，何事有餘哀。"]', '诗', 'shi', '', NULL, '雲山 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a9e1040-2e92-4788-ab85-789b57551c08', '遣興', '遣兴', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["干戈猶未定，弟妹各何之。","拭淚霑襟血，梳頭滿面絲。","地卑荒野大，天遠暮江遲。","衰疾那能久，應無見汝時。"]', '["干戈猶未定，弟妹各何之。","拭泪霑襟血，梳头满面絲。","地卑荒野大，天远暮江遲。","衰疾那能久，應無见汝时。"]', '诗', 'shi', '', NULL, '遣興 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8822810-0ad6-4eb1-8351-688d5cf81991', '北鄰', '北鄰', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["明府豈辭滿，藏身方告勞。","青錢買野竹，白幘岸江臯。","愛酒晉山簡，能詩何水曹。","時來訪老疾，步屧到蓬蒿。"]', '["明府豈辞满，藏身方告勞。","青錢買野竹，白幘岸江臯。","愛酒晉山簡，能诗何水曹。","时来訪老疾，步屧到蓬蒿。"]', '诗', 'shi', '', NULL, '北鄰 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8bae0f0-12c6-4d6c-a35d-7077217cfdea', '南鄰', '南鄰', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["錦里先生烏角巾，園收芋粟不全貧。","慣看賓客兒童喜，得食階除鳥雀馴。","秋水纔深四五尺，野航恰受兩三人。","白沙翠竹江村暮，相對柴門月色新。"]', '["錦里先生烏角巾，园收芋粟不全貧。","慣看賓客兒童喜，得食階除鸟雀馴。","秋水纔深四五尺，野航恰受兩三人。","白沙翠竹江村暮，相对柴门月色新。"]', '诗', 'shi', '', NULL, '南鄰 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0084305-f95a-4366-b276-ee70d0feb826', '出郭', '出郭', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["霜露晚淒淒，高天逐望低。","遠煙鹽井上，斜景雪峰西。","故國猶兵馬，他鄉亦鼓鼙。","江城今夜客，還與舊烏啼。"]', '["霜露晚淒淒，高天逐望低。","远煙鹽井上，斜景雪峰西。","故国猶兵马，他乡亦鼓鼙。","江城今夜客，還與旧烏啼。"]', '诗', 'shi', '', NULL, '出郭 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6299dbfa-43e4-4d45-bb02-83f765e3ea33', '過南鄰朱山人水亭', '過南鄰朱山人水亭', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["相近竹參差，相過人不知。","幽花欹滿樹，小水細通池。","歸客村非遠，殘樽席更移。","看君多道氣，從此數追隨。"]', '["相近竹參差，相過人不知。","幽花欹满樹，小水細通池。","归客村非远，殘樽席更移。","看君多道氣，從此數追隨。"]', '诗', 'shi', '', NULL, '過南鄰朱山人水亭 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c24608f-08a4-440f-8401-1c253732f4fc', '恨別', '恨別', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["洛城一別四千里，胡騎長驅五六年。","草木變衰行劒外，兵戈阻絕老江邊。","思家步月清宵立，憶弟看雲白日眠。","聞道河陽近乘勝，司徒急爲破幽燕。"]', '["洛城一別四千里，胡騎长驱五六年。","草木变衰行劒外，兵戈阻絕老江邊。","思家步月清宵立，憶弟看云白日眠。","闻道河陽近乘勝，司徒急爲破幽燕。"]', '诗', 'shi', '', NULL, '恨別 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08787c29-8c27-4e9a-b66a-b499586d2b82', '寄賀蘭銛', '寄賀蘭銛', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["朝野歡娛後，乾坤震蕩中。","相隨萬里日，總作白頭翁。","歲晚仍分袂，江邊更轉蓬。","勿云俱異域，飲啄幾回同。"]', '["朝野歡娛後，乾坤震蕩中。","相隨万里日，總作白头翁。","歲晚仍分袂，江邊更轉蓬。","勿云俱異域，饮啄幾回同。"]', '诗', 'shi', '', NULL, '寄賀蘭銛 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19e1ce0c-fd4d-47e7-83e2-07c1891d5ee4', '寄楊五桂州譚', '寄楊五桂州譚', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["五嶺皆炎熱，宜人獨桂林。","梅花萬里外，雪片一冬深。","聞此寬相憶，爲邦復好音。","江邊送孫楚，遠附白頭吟。"]', '["五嶺皆炎熱，宜人独桂林。","梅花万里外，雪片一冬深。","闻此寬相憶，爲邦复好音。","江邊送孫楚，远附白头吟。"]', '诗', 'shi', '', NULL, '寄楊五桂州譚 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ddd6af5c-372e-4a0e-98bd-4a2c51c42b00', '逢唐興劉主簿弟', '逢唐兴劉主簿弟', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["分手開元末，連年絕尺書。","江山且相見，戎馬未安居。","劒外官人冷，關中驛騎疎。","輕舟下吳會，主簿意何如。"]', '["分手开元末，連年絕尺书。","江山且相见，戎马未安居。","劒外官人冷，关中驛騎疎。","轻舟下吳會，主簿意何如。"]', '诗', 'shi', '', NULL, '逢唐興劉主簿弟 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e17bc310-4fcc-4a80-a860-5f112a907f54', '和裴迪登新津寺寄王侍郎', '和裴迪登新津寺寄王侍郎', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["何限倚山木，吟詩秋葉黃。","蟬聲集古寺，鳥影度寒塘。","風物悲遊子，登臨憶侍郎。","老夫貪佛日，隨意宿僧房。"]', '["何限倚山木，吟诗秋葉黄。","蟬声集古寺，鸟影度寒塘。","风物悲游子，登臨憶侍郎。","老夫貪佛日，隨意宿僧房。"]', '诗', 'shi', '', NULL, '和裴迪登新津寺寄王侍郎 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a32f032-6f9a-4095-bfcc-67d095ce90c7', '敬簡王明府', '敬簡王明府', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["葉縣郎官宰，周南太史公。","神仙才有數，流落意無窮。","驥病思偏秣，鷹愁怕苦籠。","看君用高義，恥與萬人同。"]', '["葉縣郎官宰，周南太史公。","神仙才有數，流落意無窮。","驥病思偏秣，鷹愁怕苦籠。","看君用高義，恥與万人同。"]', '诗', 'shi', '', NULL, '敬簡王明府 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7679ec5f-893f-4d30-8acd-b45c908e49d1', '重簡王明府', '重簡王明府', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["甲子西南異，冬來只薄寒。","江雲何夜盡，蜀雨幾時乾。","行李須相問，窮愁豈有寬。","君聽鴻鴈響，恐致稻粱難。"]', '["甲子西南異，冬来只薄寒。","江云何夜尽，蜀雨幾时乾。","行李須相问，窮愁豈有寬。","君听鴻鴈响，恐致稻粱难。"]', '诗', 'shi', '', NULL, '重簡王明府 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba10246a-c026-41e7-87a9-2e6ce2a27559', '建都十二韻', '建都十二韻', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["蒼生未蘇息，胡馬半乾坤。","議在雲臺上，誰扶黃屋尊。","建都分魏闕，下韶闢荆門。","恐失東人望，其如西極存。","時危當雪恥，計大豈輕論。","雖倚三階正，終愁萬國飜。","牽裾恨不死，漏網荷殊恩。","永負漢庭哭，遙憐湘水魂。","窮冬客江劒，隨事有田園。","風斷青蒲節，霜埋翠竹根。","衣冠空穰穰，關輔久昏昏。","願枉長安日，光輝照北原。"]', '["蒼生未蘇息，胡马半乾坤。","議在云台上，誰扶黄屋尊。","建都分魏闕，下韶闢荆门。","恐失东人望，其如西極存。","时危當雪恥，計大豈轻論。","雖倚三階正，終愁万国飜。","牽裾恨不死，漏網荷殊恩。","永負漢庭哭，遙怜湘水魂。","窮冬客江劒，隨事有田园。","风斷青蒲節，霜埋翠竹根。","衣冠空穰穰，关輔久昏昏。","願枉长安日，光輝照北原。"]', '诗', 'shi', '', NULL, '建都十二韻 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('130ff9df-d0d9-4812-8ae2-cba09ed87050', '歲暮', '歲暮', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["歲暮遠爲客，邊隅還用兵。","煙塵犯雪嶺，鼓角動江城。","天地日流血，朝廷誰請纓。","濟時敢愛死，寂寞壯心驚。"]', '["歲暮远爲客，邊隅還用兵。","煙塵犯雪嶺，鼓角动江城。","天地日流血，朝廷誰請纓。","濟时敢愛死，寂寞壯心驚。"]', '诗', 'shi', '', NULL, '歲暮 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21500334-b2e4-4199-8c2c-cbff940c9b6d', '和裴迪登蜀州東亭送客逢早梅相憶見寄', '和裴迪登蜀州东亭送客逢早梅相憶见寄', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["東閣官梅動詩興，還如何遜在揚州。","此時對雪遙相憶，送客逢春可自由。","幸不折來傷歲暮，若爲看去亂鄉愁。","江邊一樹垂垂發，朝夕催人自白頭。"]', '["东閣官梅动诗兴，還如何遜在揚州。","此时对雪遙相憶，送客逢春可自由。","幸不折来傷歲暮，若爲看去亂乡愁。","江邊一樹垂垂發，朝夕催人自白头。"]', '诗', 'shi', '', NULL, '和裴迪登蜀州東亭送客逢早梅相憶見寄 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6306447f-ad78-4478-aeb0-9bde2807146f', '寄贈王十將軍承俊', '寄贈王十將軍承俊', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["將軍膽氣雄，臂懸兩角弓。","纏結青驄馬，出入錦城中。","時危未授鉞，勢屈難爲功。","賓客滿堂上，何人高義同。"]', '["將軍膽氣雄，臂懸兩角弓。","纏結青驄马，出入錦城中。","时危未授鉞，勢屈难爲功。","賓客满堂上，何人高義同。"]', '诗', 'shi', '', NULL, '寄贈王十將軍承俊 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('248f3d52-a0cf-4224-9dd0-5b9f12786c51', '暮登四安寺鐘樓寄裴十', '暮登四安寺鐘楼寄裴十', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["暮倚高樓對雪峰，僧來不語自鳴鐘。","孤城返照紅將歛，近市浮煙翠且重。","多病獨愁常閴寂，故人相見未從容。","知君苦思緣詩瘦，大向交遊萬事慵。"]', '["暮倚高楼对雪峰，僧来不語自鳴鐘。","孤城返照紅將歛，近市浮煙翠且重。","多病独愁常閴寂，故人相见未從容。","知君苦思緣诗瘦，大向交游万事慵。"]', '诗', 'shi', '', NULL, '暮登四安寺鐘樓寄裴十 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a77da0a-1228-424b-8bee-57e78dd1a9e3', '散愁二首 一', '散愁二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["久客宜旋斾，興王未息戈。","蜀星陰見少，江雨夜聞多。","百萬傳深入，寰區望匪它。","司徒下燕趙，收取舊山河。"]', '["久客宜旋斾，兴王未息戈。","蜀星陰见少，江雨夜闻多。","百万傳深入，寰區望匪它。","司徒下燕趙，收取旧山河。"]', '诗', 'shi', '', NULL, '散愁二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e5828eb-ebeb-4c30-8894-70ebb94adc3e', '散愁二首 二', '散愁二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["聞道幷州鎮，尚書訓士齊。","幾時通薊北，當日報關西。","戀闕丹心破，霑衣皓首啼。","老魂招不得，歸路恐長迷。"]', '["闻道幷州鎮，尚书訓士齊。","幾时通薊北，當日報关西。","戀闕丹心破，霑衣皓首啼。","老魂招不得，归路恐长迷。"]', '诗', 'shi', '', NULL, '散愁二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('327ec1e1-6d64-4867-9130-51bacc00112c', '奉酬李都督表丈早春作', '奉酬李都督表丈早春作', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["力疾坐清曉，來時悲早春。","轉添愁伴客，更覺老隨人。","紅入桃花嫩，青歸柳葉新。","望鄉應未已，四海尚風塵。"]', '["力疾坐清晓，来时悲早春。","轉添愁伴客，更覺老隨人。","紅入桃花嫩，青归柳葉新。","望乡應未已，四海尚风塵。"]', '诗', 'shi', '', NULL, '奉酬李都督表丈早春作 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9da0cbe5-52d4-4efc-8be2-2f78f1a8f097', '客至', '客至', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["舍南舍北皆春水，但見羣鷗日日來。","花徑不曾緣客掃，蓬門今始爲君開。","盤餐市遠無兼味，樽酒家貧只舊醅。","肯與鄰翁相對飲，隔籬呼取盡餘桮。"]', '["舍南舍北皆春水，但见羣鷗日日来。","花徑不曾緣客掃，蓬门今始爲君开。","盤餐市远無兼味，樽酒家貧只旧醅。","肯與鄰翁相对饮，隔籬呼取尽餘桮。"]', '诗', 'shi', '', NULL, '客至 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4fdb8fe-7069-4925-a41b-a9522bb26653', '遣意二首 一', '遣意二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["囀枝黃鳥近，泛渚白鷗輕。","一徑野花落，孤村春水生。","衰年催釀黍，細雨更移橙。","漸喜交遊絕，幽居不用名。"]', '["囀枝黄鸟近，泛渚白鷗轻。","一徑野花落，孤村春水生。","衰年催釀黍，細雨更移橙。","漸喜交游絕，幽居不用名。"]', '诗', 'shi', '', NULL, '遣意二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('982aa516-163c-40fd-94ab-3c7c743456c9', '遣意二首 二', '遣意二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["簷影微微落，津流脉脉斜。","野船明細火，宿鴈聚圓沙。","雲掩初弦月，香傳小樹花。","鄰人有美酒，稚子夜能賒。"]', '["簷影微微落，津流脉脉斜。","野船明細火，宿鴈聚圓沙。","云掩初弦月，香傳小樹花。","鄰人有美酒，稚子夜能賒。"]', '诗', 'shi', '', NULL, '遣意二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d239ab24-c5d9-4163-9cb0-2dd7c0f95998', '漫成二首 一', '漫成二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["野日荒荒白，春流泯泯清。","渚蒲隨地有，村徑逐門成。","只作披衣慣，常從漉酒生。","眼前無俗物，多病也身輕。"]', '["野日荒荒白，春流泯泯清。","渚蒲隨地有，村徑逐门成。","只作披衣慣，常從漉酒生。","眼前無俗物，多病也身轻。"]', '诗', 'shi', '', NULL, '漫成二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c27559b0-f98d-4b5f-a239-f5ec7cb33f71', '漫成二首 二', '漫成二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["江臯已仲春，花下復清晨。","仰面貪看鳥，回頭錯應人。","讀書難字過，對酒滿壺頻。","近識峨眉老，知予嬾是真。"]', '["江臯已仲春，花下复清晨。","仰面貪看鸟，回头錯應人。","读书难字過，对酒满壺頻。","近識峨眉老，知予嬾是真。"]', '诗', 'shi', '', NULL, '漫成二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6ddd64d-606c-421e-8912-7f37568020b1', '春夜喜雨', '春夜喜雨', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["好雨知時節，當春乃發生。","隨風潛入夜，潤物細無聲。","野徑雲俱黑，江船火獨明。","曉看紅濕處，花重錦官城。"]', '["好雨知时節，當春乃發生。","隨风潛入夜，潤物細無声。","野徑云俱黑，江船火独明。","晓看紅濕处，花重錦官城。"]', '诗', 'shi', '', NULL, '春夜喜雨 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be93d219-ff58-4c9e-8068-9a8cbc8db5e5', '春水', '春水', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["三月桃花浪，江流復舊痕。","朝來沒沙尾，碧色動柴門。","接縷垂芳餌，連筒灌小園。","已添無數鳥，爭浴故相喧。"]', '["三月桃花浪，江流复旧痕。","朝来沒沙尾，碧色动柴门。","接縷垂芳餌，連筒灌小园。","已添無數鸟，爭浴故相喧。"]', '诗', 'shi', '', NULL, '春水 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f53d6111-259a-4fdf-950c-818b70c38a31', '春水生二絕 一', '春水生二絕 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["二月六夜春水生。","門前小灘渾欲平，鸕鶿鸂鶒莫漫喜。","吾與汝曹俱眼明。"]', '["二月六夜春水生。","门前小灘渾欲平，鸕鶿鸂鶒莫漫喜。","吾與汝曹俱眼明。"]', '诗', 'shi', '', NULL, '春水生二絕 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be030244-ee5c-409c-bc75-8a80eb18bb4e', '春水生二絕 二', '春水生二絕 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["一夜水高二尺強，數日不可更禁當。","南市津頭有船賣，無錢即買繫籬旁。"]', '["一夜水高二尺強，數日不可更禁當。","南市津头有船賣，無錢即買繫籬旁。"]', '诗', 'shi', '', NULL, '春水生二絕 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d59c85f4-1fba-4dd6-8300-76b1793afdb2', '江亭', '江亭', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["坦腹江亭暖，長吟野望時。","水流心不競，雲在意俱遲。","寂寂春將晚，欣欣物自私。","故林歸未得，排悶強裁詩。"]', '["坦腹江亭暖，长吟野望时。","水流心不競，云在意俱遲。","寂寂春將晚，欣欣物自私。","故林归未得，排悶強裁诗。"]', '诗', 'shi', '', NULL, '江亭 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d090832-2f35-4f44-a68a-cc5b67e1798d', '村夜', '村夜', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["蕭蕭風色暮，江頭人不行。","村舂雨外急，鄰火夜深明。","胡羯何多難，漁樵寄此生。","中原有兄弟，萬里正含情。"]', '["蕭蕭风色暮，江头人不行。","村舂雨外急，鄰火夜深明。","胡羯何多难，漁樵寄此生。","中原有兄弟，万里正含情。"]', '诗', 'shi', '', NULL, '村夜 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ea7e12e-dd82-4922-88bc-e97fd3e60cdb', '早起', '早起', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["春來常早起，幽事頗相關。","帖石防隤岸，開林出遠山。","一丘藏曲折，緩步有躋攀。","童僕來城市，瓶中得酒還。"]', '["春来常早起，幽事頗相关。","帖石防隤岸，开林出远山。","一丘藏曲折，緩步有躋攀。","童僕来城市，瓶中得酒還。"]', '诗', 'shi', '', NULL, '早起 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9eb8a798-42bf-42a1-bbd0-b4fe04d71aef', '可惜', '可惜', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["花飛有底急，老去願春遲。","可惜歡娛地，都非少壯時。","寬心應是酒，遣興莫過詩。","此意陶潛解，吾生後汝期。"]', '["花飞有底急，老去願春遲。","可惜歡娛地，都非少壯时。","寬心應是酒，遣兴莫過诗。","此意陶潛解，吾生後汝期。"]', '诗', 'shi', '', NULL, '可惜 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09f26016-922c-4bb4-a70f-a846c5b03661', '落日', '落日', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["落日在簾鉤，溪邊春事幽。","芳菲緣岸圃，樵爨倚灘舟。","啅雀爭枝墜，飛蟲滿院遊。","濁醪誰造汝，一酌散千憂。"]', '["落日在簾鉤，溪邊春事幽。","芳菲緣岸圃，樵爨倚灘舟。","啅雀爭枝墜，飞蟲满院游。","濁醪誰造汝，一酌散千憂。"]', '诗', 'shi', '', NULL, '落日 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1e5f620-d20f-4366-8cde-0ce540fcd107', '獨酌', '独酌', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["步屨深林晚，開樽獨酌遲。","仰蜂黏落絮，行蟻上枯梨。","薄劣慚真隱，幽偏得自怡。","本無軒冕意，不是傲當時。"]', '["步屨深林晚，开樽独酌遲。","仰蜂黏落絮，行蟻上枯梨。","薄劣慚真隐，幽偏得自怡。","本無軒冕意，不是傲當时。"]', '诗', 'shi', '', NULL, '獨酌 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7392d578-301d-4562-98b0-2cb5086b62bf', '徐步', '徐步', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["整履步青蕪，荒庭日欲晡。","芹泥隨燕觜，花蘂上蜂鬚。","把酒從衣濕，吟詩信杖扶。","敢論才見忌，實有醉如愚。"]', '["整履步青蕪，荒庭日欲晡。","芹泥隨燕觜，花蘂上蜂鬚。","把酒從衣濕，吟诗信杖扶。","敢論才见忌，實有醉如愚。"]', '诗', 'shi', '', NULL, '徐步 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61275a5a-1dce-4a0b-9491-a43c915c06d3', '寒食', '寒食', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["寒食江村路，風花高下飛。","汀煙輕冉冉，竹日靜暉暉。","田父要皆去，鄰家鬧不違。","地偏相識盡，雞犬亦忘歸。"]', '["寒食江村路，风花高下飞。","汀煙轻冉冉，竹日静暉暉。","田父要皆去，鄰家鬧不違。","地偏相識尽，雞犬亦忘归。"]', '诗', 'shi', '', NULL, '寒食 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('731d79e3-1e7c-4ce8-a484-890b7cf39af5', '高柟', '高柟', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["柟樹色冥冥，江邊一蓋青。","近根開藥圃，接葉製茅亭。","落景陰猶合，微風韻可聽。","尋常絕醉困，臥此片時醒。"]', '["柟樹色冥冥，江邊一蓋青。","近根开藥圃，接葉製茅亭。","落景陰猶合，微风韻可听。","尋常絕醉困，臥此片时醒。"]', '诗', 'shi', '', NULL, '高柟 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d0e997e-203d-4294-8173-9994f02bacdd', '惡樹', '惡樹', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["獨遶虛齋徑，常持小斧柯。","幽陰成頗雜，惡木剪還多。","枸杞因吾有，雞棲奈汝何。","方知不材者，生長漫婆娑。"]', '["独遶虛斋徑，常持小斧柯。","幽陰成頗杂，惡木剪還多。","枸杞因吾有，雞棲奈汝何。","方知不材者，生长漫婆娑。"]', '诗', 'shi', '', NULL, '惡樹 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0e92988-2c74-4996-a1fc-8450d79a9ef0', '石鏡', '石镜', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["蜀王將此鏡，送死置空山。","冥寞憐香骨，提攜近玉顏。","衆妃無復歎，千騎亦虛還。","獨有傷心石，埋輪月宇間。"]', '["蜀王將此镜，送死置空山。","冥寞怜香骨，提携近玉顏。","衆妃無复歎，千騎亦虛還。","独有傷心石，埋輪月宇间。"]', '诗', 'shi', '', NULL, '石鏡 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c5af966-9b25-4030-80ad-c00e403151d5', '琴臺', '琴台', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["茂陵多病後，尚愛卓文君。","酒肆人間世，琴臺日暮雲。","野花留寶靨，蔓草見羅帬。","歸鳳求皇意，寥寥不復聞。"]', '["茂陵多病後，尚愛卓文君。","酒肆人间世，琴台日暮云。","野花留寶靨，蔓草见羅帬。","归鳳求皇意，寥寥不复闻。"]', '诗', 'shi', '', NULL, '琴臺 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62c91219-9aa9-4872-a4cc-8751a8f85e3c', '聞斛斯六官未歸', '闻斛斯六官未归', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["故人南郡去，去索作碑錢。","本賣文爲活，飜令室倒懸。","荆扉深蔓草，土銼冷疎煙。","老罷休無賴，歸來省醉眠。"]', '["故人南郡去，去索作碑錢。","本賣文爲活，飜令室倒懸。","荆扉深蔓草，土銼冷疎煙。","老罷休無賴，归来省醉眠。"]', '诗', 'shi', '', NULL, '聞斛斯六官未歸 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6578791b-8f0c-43a9-b7ec-96de41d55d29', '遊修覺寺', '游修覺寺', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["野寺江天豁，山扉花竹幽。","詩應有神助，吾得及春遊。","徑石相縈帶，川雲自去留。","禪枝宿衆鳥，漂轉暮歸愁。"]', '["野寺江天豁，山扉花竹幽。","诗應有神助，吾得及春游。","徑石相縈带，川云自去留。","禪枝宿衆鸟，漂轉暮归愁。"]', '诗', 'shi', '', NULL, '遊修覺寺 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e21cd9e-d90b-4cb5-a624-4ea522457655', '後遊', '後游', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["寺憶新遊處，橋憐再渡時。","江山如有待，花柳更無私。","野潤煙光薄，沙暄日色遲。","客愁全爲減，捨此復何之。"]', '["寺憶新游处，橋怜再渡时。","江山如有待，花柳更無私。","野潤煙光薄，沙暄日色遲。","客愁全爲減，捨此复何之。"]', '诗', 'shi', '', NULL, '後遊 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d17fb7e-d2f3-4f01-bcee-be11864e9155', '題新津北橋樓', '題新津北橋楼', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["望極春城上，開筵近鳥巢。","白花簷外朵，青柳檻前梢。","池水觀爲政，廚煙覺遠庖。","西川供客眼，唯有此江郊。"]', '["望極春城上，开筵近鸟巢。","白花簷外朵，青柳檻前梢。","池水观爲政，廚煙覺远庖。","西川供客眼，唯有此江郊。"]', '诗', 'shi', '', NULL, '題新津北橋樓 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de032aba-5c58-4587-af44-fac5ac8cba2b', '江漲', '江漲', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["江發蠻夷漲，山添雨雪流。","大聲吹地轉，高浪蹴天浮。","魚鱉爲人得，蛟龍不自謀。","輕帆好去便，吾道付滄洲。"]', '["江發蠻夷漲，山添雨雪流。","大声吹地轉，高浪蹴天浮。","鱼鱉爲人得，蛟龙不自謀。","轻帆好去便，吾道付滄洲。"]', '诗', 'shi', '', NULL, '江漲 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('759ebea2-b15e-4e34-8596-d81ad6a5e982', '晚晴', '晚晴', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["村晚驚風度，庭幽過雨霑。","夕陽薰細草，江色映疎簾。","書亂誰能帙，桮乾可自添。","時聞有餘論，未怪老夫潛。"]', '["村晚驚风度，庭幽過雨霑。","夕陽薰細草，江色映疎簾。","书亂誰能帙，桮乾可自添。","时闻有餘論，未怪老夫潛。"]', '诗', 'shi', '', NULL, '晚晴 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6d2681f-bb88-4a16-b4f3-758588182049', '朝雨', '朝雨', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["涼氣晚蕭蕭，江雲亂眼飄。","風鴛藏近渚，雨燕集深條。","黃綺終辭漢，巢由不見堯。","草堂樽酒在，幸得過清朝。"]', '["涼氣晚蕭蕭，江云亂眼飄。","风鴛藏近渚，雨燕集深條。","黄綺終辞漢，巢由不见堯。","草堂樽酒在，幸得過清朝。"]', '诗', 'shi', '', NULL, '朝雨 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0dc8942-b0f1-4952-af32-511e47fb4dc5', '江上值水如海勢聊短述', '江上值水如海勢聊短述', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["爲人性僻耽佳句，語不驚人死不休。","老去詩篇渾漫興，春來花鳥莫深愁。","新添水檻供垂釣，故著浮槎替入舟。","焉得思如陶謝手，令渠述作與同遊。"]', '["爲人性僻耽佳句，語不驚人死不休。","老去诗篇渾漫兴，春来花鸟莫深愁。","新添水檻供垂釣，故著浮槎替入舟。","焉得思如陶謝手，令渠述作與同游。"]', '诗', 'shi', '', NULL, '江上值水如海勢聊短述 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a78cd6d-86f2-4829-8ef1-80ca35415868', '送裴五赴東川', '送裴五赴东川', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["故人亦流落，高義動乾坤。","何日通燕塞，相看老蜀門。","東行應暫別，北望苦銷魂。","凜凜悲秋意，非君誰與論。"]', '["故人亦流落，高義动乾坤。","何日通燕塞，相看老蜀门。","东行應暫別，北望苦銷魂。","凜凜悲秋意，非君誰與論。"]', '诗', 'shi', '', NULL, '送裴五赴東川 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8a7854a-a95a-4171-8569-56abfb5b1189', '赴青城縣出成都寄陶王二少尹', '赴青城縣出成都寄陶王二少尹', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["老恥妻孥笑，貧嗟出入勞。","客情投異縣，詩態憶吾曹。","東郭滄江合，西山白雪高。","文章差底病，回首興滔滔。"]', '["老恥妻孥笑，貧嗟出入勞。","客情投異縣，诗態憶吾曹。","东郭滄江合，西山白雪高。","文章差底病，回首兴滔滔。"]', '诗', 'shi', '', NULL, '赴青城縣出成都寄陶王二少尹 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f97db092-6895-40e4-a61d-e54cba511c93', '因崔五侍御寄高彭州', '因崔五侍御寄高彭州', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["百年已過半，秋至轉饑寒。","為問彭州牧，何時救急難。"]', '["百年已過半，秋至轉饑寒。","為问彭州牧，何时救急难。"]', '诗', 'shi', '', NULL, '因崔五侍御寄高彭州 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7dfe38bb-ee39-4126-ac0d-33310dbb03ba', '野望因過常少仙', '野望因過常少仙', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["野橋齊度馬，秋望轉悠哉。","竹覆青城合，江從灌口來。","入村樵徑引，嘗果栗皺開。","落盡高天日，幽人未遣迴。"]', '["野橋齊度马，秋望轉悠哉。","竹覆青城合，江從灌口来。","入村樵徑引，嘗果栗皺开。","落尽高天日，幽人未遣迴。"]', '诗', 'shi', '', NULL, '野望因過常少仙 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('503e8554-22b6-4be6-bd23-be42f5591cbf', '寄杜位', '寄杜位', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["近聞寬法離新州，想見懷歸尚百憂。","逐客雖皆萬里去，悲君已是十年流。","干戈況復塵隨眼，鬢髮還應雪滿頭。"]', '["近闻寬法離新州，想见懷归尚百憂。","逐客雖皆万里去，悲君已是十年流。","干戈況复塵隨眼，鬢髮還應雪满头。"]', '诗', 'shi', '', NULL, '寄杜位 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d45a81a-7760-4323-95a0-e33be199c67b', '奉簡高三十五使君', '奉簡高三十五使君', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["當代論才子，如公復幾人。","驊騮開道路，鷹隼出風塵。","行色秋將晚，交情老更親。","天涯喜相見，披豁對吾真。"]', '["當代論才子，如公复幾人。","驊騮开道路，鷹隼出风塵。","行色秋將晚，交情老更親。","天涯喜相见，披豁对吾真。"]', '诗', 'shi', '', NULL, '奉簡高三十五使君 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca2f43ed-1561-4022-b525-b92b76402740', '送韓十四江東覲省', '送韓十四江东覲省', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["兵戈不見老萊衣，歎息人間萬事非。","我已無家尋弟妹，君今何處訪庭闈。","黃牛峽靜灘聲轉，白馬江寒樹影稀。","此別應須各努力，故鄉猶恐未同歸。"]', '["兵戈不见老萊衣，歎息人间万事非。","我已無家尋弟妹，君今何处訪庭闈。","黄牛峽静灘声轉，白马江寒樹影稀。","此別應須各努力，故乡猶恐未同归。"]', '诗', 'shi', '', NULL, '送韓十四江東覲省 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41618e63-3f2a-45a9-972c-ba4b9b30b256', '酬高使君相贈', '酬高使君相贈', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["古寺僧牢落，空房客寓居。","故人供祿米，鄰舍與園蔬。","雙樹容聽法，三車肯載書。","草玄吾豈敢，賦或似相如。"]', '["古寺僧牢落，空房客寓居。","故人供祿米，鄰舍與园蔬。","雙樹容听法，三车肯載书。","草玄吾豈敢，賦或似相如。"]', '诗', 'shi', '', NULL, '酬高使君相贈 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f12c6cd1-db69-4d70-abde-f8fa28cb597d', '草堂即事', '草堂即事', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["荒村建子月，獨樹老夫家。","霧裏江船渡，風前徑竹斜。","寒魚依密藻，宿鷺起圓沙。","蜀酒禁愁得，無錢何處賒。"]', '["荒村建子月，独樹老夫家。","霧裏江船渡，风前徑竹斜。","寒鱼依密藻，宿鷺起圓沙。","蜀酒禁愁得，無錢何处賒。"]', '诗', 'shi', '', NULL, '草堂即事 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9cb4b28-e916-4e05-bb3d-7f4c7cf0ca89', '魏十四侍御就弊廬相別', '魏十四侍御就弊廬相別', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["有客騎驄馬，江邊問草堂。","遠尋留藥價，惜別到文場。","入幕旌旗動，歸軒錦繡香。","時應念衰疾，書疏及滄浪。"]', '["有客騎驄马，江邊问草堂。","远尋留藥價，惜別到文場。","入幕旌旗动，归軒錦繡香。","时應念衰疾，书疏及滄浪。"]', '诗', 'shi', '', NULL, '魏十四侍御就弊廬相別 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00a6e6c6-eba7-48b4-8d9d-f42df46815a6', '徐九少尹見過', '徐九少尹见過', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["晚景孤村僻，行軍數騎來。","交新徒有喜，禮厚媿無才。","賞靜憐雲竹，忘歸步月臺。","何當看花蘂，欲發照江梅。"]', '["晚景孤村僻，行軍數騎来。","交新徒有喜，禮厚媿無才。","賞静怜云竹，忘归步月台。","何當看花蘂，欲發照江梅。"]', '诗', 'shi', '', NULL, '徐九少尹見過 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd7eff0e-218e-4af8-b731-9f32786581aa', '范二員外邈吳十侍御郁特枉駕闕展待聊寄此', '范二員外邈吳十侍御郁特枉駕闕展待聊寄此', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["暫往比鄰去，空聞二妙歸。","幽棲誠簡略，衰白已光輝。","野外貧家遠，村中好客稀。","論文或不媿，肯重欵柴扉。"]', '["暫往比鄰去，空闻二妙归。","幽棲誠簡略，衰白已光輝。","野外貧家远，村中好客稀。","論文或不媿，肯重欵柴扉。"]', '诗', 'shi', '', NULL, '范二員外邈吳十侍御郁特枉駕闕展待聊寄此 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86034140-52f0-45f7-b895-1a8ccfe59ad4', '王十七侍御掄許攜酒至草堂奉寄此詩便請邀高三十五使君同到', '王十七侍御掄許携酒至草堂奉寄此诗便請邀高三十五使君同到', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["老夫臥穩朝慵起，白屋寒多暖始開。","江鸛巧當幽徑浴，鄰雞還過短牆來。","繡衣屢許攜家醞，皂蓋能忘折野梅。","戲假霜威促山簡，須成一醉習池迴。"]', '["老夫臥穩朝慵起，白屋寒多暖始开。","江鸛巧當幽徑浴，鄰雞還過短牆来。","繡衣屢許携家醞，皂蓋能忘折野梅。","戲假霜威促山簡，須成一醉習池迴。"]', '诗', 'shi', '', NULL, '王十七侍御掄許攜酒至草堂奉寄此詩便請邀高三十五使君同到 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1335ae90-298f-40fa-9b43-c46cdfcb5f3e', '王竟攜酒高亦同過共用寒字', '王竟携酒高亦同過共用寒字', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["臥病荒郊遠，通行小徑難。","故人能領客，攜酒重相看。","自媿無鮭菜，空煩卸馬鞍。","移樽勸山簡，頭白恐風寒。"]', '["臥病荒郊远，通行小徑难。","故人能領客，携酒重相看。","自媿無鮭菜，空煩卸马鞍。","移樽勸山簡，头白恐风寒。"]', '诗', 'shi', '', NULL, '王竟攜酒高亦同過共用寒字 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('995a9440-f8e3-4a9b-843d-27a34ea8b671', '陪李七司馬皂江上觀造竹橋即日成往來之人免冬寒入水聊題短作簡李公二首 一', '陪李七司马皂江上观造竹橋即日成往来之人免冬寒入水聊題短作簡李公二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["伐竹爲橋結構同，褰裳不涉往來通。","天寒白鶴歸華表，日落青龍見水中。","顧我老非題柱客，知君才是濟川功。","合歡却笑千年事，驅石何時到海東。"]', '["伐竹爲橋結構同，褰裳不涉往来通。","天寒白鹤归华表，日落青龙见水中。","顧我老非題柱客，知君才是濟川功。","合歡却笑千年事，驱石何时到海东。"]', '诗', 'shi', '', NULL, '陪李七司馬皂江上觀造竹橋即日成往來之人免冬寒入水聊題短作簡李公二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('601d90fb-3589-44f1-9a25-9e16af2102c3', '陪李七司馬皂江上觀造竹橋即日成往來之人免冬寒入水聊題短作簡李公二首 二', '陪李七司马皂江上观造竹橋即日成往来之人免冬寒入水聊題短作簡李公二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["把燭成橋夜，迴舟坐客時。","天高雲去盡，江迥月來遲。","衰謝多扶病，招邀屢有期。","異方乘此興，樂罷不無悲。"]', '["把燭成橋夜，迴舟坐客时。","天高云去尽，江迥月来遲。","衰謝多扶病，招邀屢有期。","異方乘此兴，乐罷不無悲。"]', '诗', 'shi', '', NULL, '陪李七司馬皂江上觀造竹橋即日成往來之人免冬寒入水聊題短作簡李公二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ddd5978-71db-43ff-b8e8-119ec0b4fbef', '李司馬橋了承高使君自成都回', '李司马橋了承高使君自成都回', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["向來江上手紛紛，三日成功事出羣。","已傳童子騎青竹，總擬橋東待使君。"]', '["向来江上手紛紛，三日成功事出羣。","已傳童子騎青竹，總擬橋东待使君。"]', '诗', 'shi', '', NULL, '李司馬橋了承高使君自成都回 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cee19f68-28bd-4565-90ef-957426d73e23', '少年行二首 一', '少年行二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["莫笑田家老瓦盆，自從盛酒長兒孫。","傾銀注瓦驚人眼，共醉終同臥竹根。"]', '["莫笑田家老瓦盆，自從盛酒长兒孫。","傾銀注瓦驚人眼，共醉終同臥竹根。"]', '诗', 'shi', '', NULL, '少年行二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3aeb9d8-1112-4b40-99fe-11d2db52c001', '少年行二首 二', '少年行二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["巢燕養雛渾去盡，江花結子已無多。","黃衫年少來宜數，不見堂前東逝波。"]', '["巢燕養雛渾去尽，江花結子已無多。","黄衫年少来宜數，不见堂前东逝波。"]', '诗', 'shi', '', NULL, '少年行二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('079740ca-693f-457c-8ed8-625cf2661088', '野人送朱櫻', '野人送朱櫻', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["西蜀櫻桃也自紅，野人相贈滿筠籠。","數迴細寫愁仍破，萬顆勻圓訝許同。","憶昨賜霑門下省，退朝擎出大明宮。","金盤玉筯無消息，此日嘗新任轉蓬。"]', '["西蜀櫻桃也自紅，野人相贈满筠籠。","數迴細寫愁仍破，万顆勻圓訝許同。","憶昨賜霑门下省，退朝擎出大明宮。","金盤玉筯無消息，此日嘗新任轉蓬。"]', '诗', 'shi', '', NULL, '野人送朱櫻 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6a8ceab-a865-4bb2-9987-13d42349f38a', '即事', '即事', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["百寶裝腰帶，真珠絡臂韝。","笑時花近眼，舞罷錦纏頭。"]', '["百寶裝腰带，真珠絡臂韝。","笑时花近眼，舞罷錦纏头。"]', '诗', 'shi', '', NULL, '即事 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('846bf783-211a-4122-9587-054fcbdbc6d1', '贈花卿', '贈花卿', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["錦城絲管日紛紛，半入江風半入雲。","此曲秪應天上有，人間能得幾回聞。"]', '["錦城絲管日紛紛，半入江风半入云。","此曲秪應天上有，人间能得幾回闻。"]', '诗', 'shi', '', NULL, '贈花卿 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('469e9b83-b9fe-4f2e-89da-bb59dd7b9067', '少年行', '少年行', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["馬上誰家薄媚郎，臨堦下馬坐人牀。","不通姓字麤豪甚，指點銀瓶索酒嘗。"]', '["马上誰家薄媚郎，臨堦下马坐人牀。","不通姓字麤豪甚，指点銀瓶索酒嘗。"]', '诗', 'shi', '', NULL, '少年行 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c09c67ab-4080-40bb-85a2-2ed5bc2f32bb', '觀李固請司馬弟山水圖三首 一', '观李固請司马弟山水圖三首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["簡易高人意，匡牀竹火爐。","寒天留遠客，碧海挂新圖。","雖對連山好，貪看絕島孤。","羣仙不愁思，冉冉下蓬壺。"]', '["簡易高人意，匡牀竹火爐。","寒天留远客，碧海挂新圖。","雖对連山好，貪看絕島孤。","羣仙不愁思，冉冉下蓬壺。"]', '诗', 'shi', '', NULL, '觀李固請司馬弟山水圖三首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('449addec-d8fe-491c-9ae0-9cc48029574c', '觀李固請司馬弟山水圖三首 二', '观李固請司马弟山水圖三首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["方丈渾連水，天臺總映雲。","人間長見畫，老去恨空聞。","范蠡舟偏小，王喬鶴不羣。","此生隨萬物，何路出塵氛。"]', '["方丈渾連水，天台總映云。","人间长见畫，老去恨空闻。","范蠡舟偏小，王喬鹤不羣。","此生隨万物，何路出塵氛。"]', '诗', 'shi', '', NULL, '觀李固請司馬弟山水圖三首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f072a04-f0e8-4487-b814-ff6828d0e3de', '觀李固請司馬弟山水圖三首 三', '观李固請司马弟山水圖三首 三', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["高浪垂翻屋，崩崖欲壓牀。","野橋分子細，沙岸繞微茫。","紅浸珊瑚短，青懸薜荔長。","浮查並坐得，仙老暫相將。"]', '["高浪垂翻屋，崩崖欲壓牀。","野橋分子細，沙岸繞微茫。","紅浸珊瑚短，青懸薜荔长。","浮查並坐得，仙老暫相將。"]', '诗', 'shi', '', NULL, '觀李固請司馬弟山水圖三首 三 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f1258da-f56c-4485-aea5-e405a6ce4997', '題桃樹', '題桃樹', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["小徑升堂舊不斜，五株桃樹亦從遮。","高秋總餧貧人實，來歲還舒滿眼花。","簾戶每宜通乳燕，兒童莫信打慈鵶。","寡妻羣盜非今日，天下車書正一家。"]', '["小徑升堂旧不斜，五株桃樹亦從遮。","高秋總餧貧人實，来歲還舒满眼花。","簾戶每宜通乳燕，兒童莫信打慈鵶。","寡妻羣盜非今日，天下车书正一家。"]', '诗', 'shi', '', NULL, '題桃樹 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76d1a527-f7ad-4732-98a1-248d9b64c781', '蕭八明府隄處覓桃栽', '蕭八明府隄处覓桃栽', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["奉乞桃栽一百根，春前爲送浣花村。","河陽縣裏雖無數，濯錦江邊未滿園。"]', '["奉乞桃栽一百根，春前爲送浣花村。","河陽縣裏雖無數，濯錦江邊未满园。"]', '诗', 'shi', '', NULL, '蕭八明府隄處覓桃栽 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b53c554d-abd0-4532-84d2-529d14fdebce', '從韋二明府續處覓綿竹', '從韋二明府續处覓綿竹', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["華軒藹藹他年到，綿竹亭亭出縣高。","江上舍前無此物，幸分蒼翠拂波濤。"]', '["华軒藹藹他年到，綿竹亭亭出縣高。","江上舍前無此物，幸分蒼翠拂波濤。"]', '诗', 'shi', '', NULL, '從韋二明府續處覓綿竹 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b31ab8d7-ae0d-4311-ae58-3a2b1e8854b1', '憑何十一少府邕覓榿木栽', '憑何十一少府邕覓榿木栽', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["草堂塹西無樹林，非子誰復見幽心。","飽聞榿木三年大，與致溪邊十畝陰。"]', '["草堂塹西無樹林，非子誰复见幽心。","飽闻榿木三年大，與致溪邊十畝陰。"]', '诗', 'shi', '', NULL, '憑何十一少府邕覓榿木栽 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4786e50d-a729-4149-b919-d6947757b010', '憑韋少府班覓松樹子', '憑韋少府班覓松樹子', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["落落出羣非櫸柳，青青不朽豈楊梅。","欲存老蓋千年意，爲覓霜根數寸栽。"]', '["落落出羣非櫸柳，青青不朽豈楊梅。","欲存老蓋千年意，爲覓霜根數寸栽。"]', '诗', 'shi', '', NULL, '憑韋少府班覓松樹子 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e4817d5-dad7-4724-9649-c26b1d2e5b42', '又于韋處乞大邑瓷盌', '又于韋处乞大邑瓷盌', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["大邑燒瓷輕且堅，扣如哀玉錦城傳。","君家白盌勝霜雪，急送茅齋也可憐。"]', '["大邑燒瓷轻且堅，扣如哀玉錦城傳。","君家白盌勝霜雪，急送茅斋也可怜。"]', '诗', 'shi', '', NULL, '又于韋處乞大邑瓷盌 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07452799-e7a9-49e9-ae54-0a10684431fb', '詣徐卿覓果栽', '詣徐卿覓果栽', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["草堂少花今欲栽，不問綠李與黃梅。","石笋街中却歸去，果園坊裏爲求來。"]', '["草堂少花今欲栽，不问綠李與黄梅。","石笋街中却归去，果园坊裏爲求来。"]', '诗', 'shi', '', NULL, '詣徐卿覓果栽 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4581792b-5959-4d76-86a0-4802beae1ace', '贈別何邕', '贈別何邕', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["生死論交地，何由見一人。","悲君隨燕雀，薄宦走風塵。","綿谷元通漢，沱江不向秦。","五陵花滿眼，傳語故鄉春。"]', '["生死論交地，何由见一人。","悲君隨燕雀，薄宦走风塵。","綿谷元通漢，沱江不向秦。","五陵花满眼，傳語故乡春。"]', '诗', 'shi', '', NULL, '贈別何邕 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6762895b-27c7-4f96-9433-0a6cec62d77f', '贈別鄭鍊赴襄陽', '贈別鄭鍊赴襄陽', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["戎馬交馳際，柴門老病身。","把君詩過日，念此別驚神。","地闊峨眉晚，天高峴首春。","爲於耆舊內，試覓姓龐人。"]', '["戎马交驰際，柴门老病身。","把君诗過日，念此別驚神。","地闊峨眉晚，天高峴首春。","爲於耆旧內，試覓姓龐人。"]', '诗', 'shi', '', NULL, '贈別鄭鍊赴襄陽 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bdf17c2d-cce3-4dab-b352-d320ab10dc63', '重贈鄭鍊', '重贈鄭鍊', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["鄭子將行罷使臣，囊無一物獻尊親。","江山路遠羇離日，裘馬誰爲感激人。"]', '["鄭子將行罷使臣，囊無一物獻尊親。","江山路远羇離日，裘马誰爲感激人。"]', '诗', 'shi', '', NULL, '重贈鄭鍊 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63d30939-2ba1-4403-a51e-774249ba209b', '奉和嚴中丞西城晚眺十韻', '奉和嚴中丞西城晚眺十韻', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["汲黯匡君切，廉頗出將頻。","直詞才不世，雄略動如神。","政簡移風速，詩清立意新。","層城臨暇景，絕域望餘春。","旗尾蛟龍會，樓頭燕雀馴。","地平江動蜀，天闊樹浮秦。","帝念深分閫，軍須遠算緡。","花羅封蛺蝶，瑞錦送麒麟。","辭第輸高義，觀圖憶古人。","征南多興緒，事業闇相親。"]', '["汲黯匡君切，廉頗出將頻。","直词才不世，雄略动如神。","政簡移风速，诗清立意新。","層城臨暇景，絕域望餘春。","旗尾蛟龙會，楼头燕雀馴。","地平江动蜀，天闊樹浮秦。","帝念深分閫，軍須远算緡。","花羅封蛺蝶，瑞錦送麒麟。","辞第輸高義，观圖憶古人。","征南多兴緒，事業闇相親。"]', '诗', 'shi', '', NULL, '奉和嚴中丞西城晚眺十韻 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35976f47-d2ee-4703-82c3-7c675e65929b', '嚴中丞枉駕見過', '嚴中丞枉駕见過', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["元戎小隊出郊坰，問柳尋花到野亭。","川合東西瞻使節，地分南北任流萍。","扁舟不獨如張翰，白帽還應似管寧。","寂寞江天雲霧裏，何人道有少微星。"]', '["元戎小隊出郊坰，问柳尋花到野亭。","川合东西瞻使節，地分南北任流萍。","扁舟不独如張翰，白帽還應似管寧。","寂寞江天云霧裏，何人道有少微星。"]', '诗', 'shi', '', NULL, '嚴中丞枉駕見過 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('069d67fe-d21b-4f83-b2ae-de6cb3af910b', '廣州段功曹到得楊五長史譚書功曹却歸聊寄此詩', '廣州段功曹到得楊五长史譚书功曹却归聊寄此诗', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["衛青開幕府，楊僕將樓船。","漢節梅花外，春城海水邊。","銅梁書遠及，珠浦使將旋。","貧病他鄉老，煩君萬里傳。"]', '["衛青开幕府，楊僕將楼船。","漢節梅花外，春城海水邊。","銅梁书远及，珠浦使將旋。","貧病他乡老，煩君万里傳。"]', '诗', 'shi', '', NULL, '廣州段功曹到得楊五長史譚書功曹却歸聊寄此詩 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a57a598-b725-46c4-b02a-067039c14263', '得廣州張判官叔卿書使還以詩代意', '得廣州張判官叔卿书使還以诗代意', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["鄉關胡騎遠，宇宙蜀城偏。","忽得炎州信，遙從月峽傳。","雲深驃騎幕，夜隔孝廉船。","却寄雙愁眼，相思淚點懸。"]', '["乡关胡騎远，宇宙蜀城偏。","忽得炎州信，遙從月峽傳。","云深驃騎幕，夜隔孝廉船。","却寄雙愁眼，相思泪点懸。"]', '诗', 'shi', '', NULL, '得廣州張判官叔卿書使還以詩代意 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28431a64-2f55-46b1-98a3-5752ba6190a5', '送段功曹歸廣州', '送段功曹归廣州', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["南海春天外，功曹幾月程。","峽雲籠樹小，湖日落船明。","交趾丹砂重，韶州白葛輕。","幸君因旅客，時寄錦官城。"]', '["南海春天外，功曹幾月程。","峽云籠樹小，湖日落船明。","交趾丹砂重，韶州白葛轻。","幸君因旅客，时寄錦官城。"]', '诗', 'shi', '', NULL, '送段功曹歸廣州 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cc96131-623f-46e5-994b-5c3e0f924224', '絕句漫興九首 一', '絕句漫兴九首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["眼見客愁愁不醒，無賴春色到江亭。","即遣花開深造次，便覺鶯語太丁寧。"]', '["眼见客愁愁不醒，無賴春色到江亭。","即遣花开深造次，便覺鶯語太丁寧。"]', '诗', 'shi', '', NULL, '絕句漫興九首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09a20b1a-c3e2-44cf-9e1f-f4cb5737dd7f', '絕句漫興九首 二', '絕句漫兴九首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["手種桃李非無主，野老牆低還似家。","恰似春風相欺得，夜來吹折數枝花。"]', '["手種桃李非無主，野老牆低還似家。","恰似春风相欺得，夜来吹折數枝花。"]', '诗', 'shi', '', NULL, '絕句漫興九首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18ea78a0-a031-4bf3-88b6-84810110737e', '絕句漫興九首 三', '絕句漫兴九首 三', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["熟知茅齋絕低小，江上燕子故來頻。","銜泥點污琴書內，更接飛蟲打著人。"]', '["熟知茅斋絕低小，江上燕子故来頻。","銜泥点污琴书內，更接飞蟲打著人。"]', '诗', 'shi', '', NULL, '絕句漫興九首 三 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b404e60a-6bdf-47fc-9b84-9e224df3a938', '絕句漫興九首 四', '絕句漫兴九首 四', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["二月已破三月來，漸老逢春能幾迴。","莫思身外無窮事，且盡生前有限桮。"]', '["二月已破三月来，漸老逢春能幾迴。","莫思身外無窮事，且尽生前有限桮。"]', '诗', 'shi', '', NULL, '絕句漫興九首 四 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0970d861-e8b1-4379-86d5-cfea6900e51a', '絕句漫興九首 五', '絕句漫兴九首 五', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["腸斷春江欲盡頭，杖藜徐步立芳洲。","顛狂柳絮隨風去，輕薄桃花逐水流。"]', '["腸斷春江欲尽头，杖藜徐步立芳洲。","顛狂柳絮隨风去，轻薄桃花逐水流。"]', '诗', 'shi', '', NULL, '絕句漫興九首 五 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83648d7d-4cd5-4a8d-9df7-b3c8eb7bb1cc', '絕句漫興九首 六', '絕句漫兴九首 六', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["嬾慢無堪不出村，呼兒日在掩柴門。","蒼苔濁酒林中靜，碧水春風野外昏。"]', '["嬾慢無堪不出村，呼兒日在掩柴门。","蒼苔濁酒林中静，碧水春风野外昏。"]', '诗', 'shi', '', NULL, '絕句漫興九首 六 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58ba4d44-398a-4af4-9ae5-764f809b0de1', '絕句漫興九首 七', '絕句漫兴九首 七', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["糝徑楊花鋪白氈，點溪荷葉疊青錢。","筍根稚子無人見，沙上鳧雛傍母眠。"]', '["糝徑楊花鋪白氈，点溪荷葉叠青錢。","筍根稚子無人见，沙上鳧雛傍母眠。"]', '诗', 'shi', '', NULL, '絕句漫興九首 七 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db15a7ee-09b5-4207-86d2-1dd41208ea23', '絕句漫興九首 八', '絕句漫兴九首 八', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["舍西柔桑葉可拈，江畔細麥復纖纖。","人生幾何春已夏，不放香醪如蜜甜。"]', '["舍西柔桑葉可拈，江畔細麦复纖纖。","人生幾何春已夏，不放香醪如蜜甜。"]', '诗', 'shi', '', NULL, '絕句漫興九首 八 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a88edd5-84ad-4d97-a77b-f60be6dcf70e', '絕句漫興九首 九', '絕句漫兴九首 九', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["隔戶楊柳弱嫋嫋，恰似十五女兒腰。","誰謂朝來不作意，狂風挽斷最長條。"]', '["隔戶楊柳弱嫋嫋，恰似十五女兒腰。","誰謂朝来不作意，狂风挽斷最长條。"]', '诗', 'shi', '', NULL, '絕句漫興九首 九 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e8b6fb6-8dc7-4b6e-b55d-3078e5d22734', '江畔獨步尋花七絕句 一', '江畔独步尋花七絕句 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["江上被花惱不徹，無處告訴只顛狂。","走覓南鄰愛酒伴，經旬出飲獨空牀。"]', '["江上被花惱不徹，無处告訴只顛狂。","走覓南鄰愛酒伴，經旬出饮独空牀。"]', '诗', 'shi', '', NULL, '江畔獨步尋花七絕句 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d19ca9d-420c-46cb-b165-936133fc2658', '江畔獨步尋花七絕句 二', '江畔独步尋花七絕句 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["稠花亂蘂畏江濱，行步欹危實怕春。","詩酒尚堪驅使在，未須料理白頭人。"]', '["稠花亂蘂畏江濱，行步欹危實怕春。","诗酒尚堪驱使在，未須料理白头人。"]', '诗', 'shi', '', NULL, '江畔獨步尋花七絕句 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8036c622-e19b-454b-be17-d5fd4f9ec789', '江畔獨步尋花七絕句 三', '江畔独步尋花七絕句 三', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["江深竹靜兩三家，多事紅花映白花。","報答春光知有處，應須美酒送生涯。"]', '["江深竹静兩三家，多事紅花映白花。","報答春光知有处，應須美酒送生涯。"]', '诗', 'shi', '', NULL, '江畔獨步尋花七絕句 三 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da2b176c-74f1-4ef1-a4d0-1982c14d44ec', '江畔獨步尋花七絕句 四', '江畔独步尋花七絕句 四', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["東望少城花滿煙，百花高樓更可憐。","誰能載酒開金盞，喚取佳人舞繡筵。"]', '["东望少城花满煙，百花高楼更可怜。","誰能載酒开金盞，喚取佳人舞繡筵。"]', '诗', 'shi', '', NULL, '江畔獨步尋花七絕句 四 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f24216b-df07-4b64-9071-d2eb78e4c7cb', '江畔獨步尋花七絕句 五', '江畔独步尋花七絕句 五', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["黃師塔前江水東，春光嬾困倚微風。","桃花一簇開無主，可愛深紅愛淺紅。"]', '["黄師塔前江水东，春光嬾困倚微风。","桃花一簇开無主，可愛深紅愛淺紅。"]', '诗', 'shi', '', NULL, '江畔獨步尋花七絕句 五 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('573bb059-28f0-4ff4-aaed-619bb2924198', '江畔獨步尋花七絕句 六', '江畔独步尋花七絕句 六', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["黃四娘家花滿蹊，千朵萬朵壓枝低。","留連戲蝶時時舞，自在嬌鶯恰恰啼。"]', '["黄四娘家花满蹊，千朵万朵壓枝低。","留連戲蝶时时舞，自在嬌鶯恰恰啼。"]', '诗', 'shi', '', NULL, '江畔獨步尋花七絕句 六 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb02a25c-ef4d-4aeb-9fc7-3a361d2643f3', '江畔獨步尋花七絕句 七', '江畔独步尋花七絕句 七', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["不是愛花即肯死，只恐花盡老相催。","繁枝容易紛紛落，嫩葉商量細細開。"]', '["不是愛花即肯死，只恐花尽老相催。","繁枝容易紛紛落，嫩葉商量細細开。"]', '诗', 'shi', '', NULL, '江畔獨步尋花七絕句 七 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87ac0c18-5dc2-4a90-88f7-bbabb262d585', '三絕句 一', '三絕句 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["楸樹馨香倚釣磯，斬新花蘂未應飛。","不如醉裏風吹盡，可忍醒時雨打稀。"]', '["楸樹馨香倚釣磯，斬新花蘂未應飞。","不如醉裏风吹尽，可忍醒时雨打稀。"]', '诗', 'shi', '', NULL, '三絕句 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1845dbc5-ff20-4c9c-9394-7781f94aaef9', '三絕句 二', '三絕句 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["門外鸕鷀去不來，沙頭忽見眼相猜。","自今已後知人意，一日須來一百回。"]', '["门外鸕鷀去不来，沙头忽见眼相猜。","自今已後知人意，一日須来一百回。"]', '诗', 'shi', '', NULL, '三絕句 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27e9b2c5-664f-49fb-b6c2-a56c2085c232', '三絕句 三', '三絕句 三', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["無數春笋滿林生，柴門密掩斷人行。","會須上番看成竹，客至從嗔不出迎。"]', '["無數春笋满林生，柴门密掩斷人行。","會須上番看成竹，客至從嗔不出迎。"]', '诗', 'shi', '', NULL, '三絕句 三 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db0b8b88-0632-4a98-b864-bf722b7814e6', '戲爲六絕句 一', '戲爲六絕句 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["庾信文章老更成，凌雲健筆意縱橫。","今人嗤點流傳賦，不覺前賢畏後生。"]', '["庾信文章老更成，凌云健笔意縱橫。","今人嗤点流傳賦，不覺前賢畏後生。"]', '诗', 'shi', '', NULL, '戲爲六絕句 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33a67972-ca3d-4597-a45e-e6e1dd2623b4', '戲爲六絕句 二', '戲爲六絕句 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["楊王盧駱當時體，輕薄爲文哂未休。","爾曹身與名俱滅，不廢江河萬古流。"]', '["楊王盧駱當时體，轻薄爲文哂未休。","爾曹身與名俱滅，不廢江河万古流。"]', '诗', 'shi', '', NULL, '戲爲六絕句 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b664d03-c089-40df-9909-16b9a0faea26', '戲爲六絕句 三', '戲爲六絕句 三', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["從使盧王操翰墨，劣于漢魏近風騷。","龍文虎脊皆君馭，歷塊過都見爾曹。"]', '["從使盧王操翰墨，劣于漢魏近风騷。","龙文虎脊皆君馭，歷塊過都见爾曹。"]', '诗', 'shi', '', NULL, '戲爲六絕句 三 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25dc0364-8d19-4385-b35a-e56abc13fcab', '戲爲六絕句 四', '戲爲六絕句 四', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["才力應難誇數公，凡今誰是出羣雄。","或看翡翠蘭苕上，未掣鯨魚碧海中。"]', '["才力應难誇數公，凡今誰是出羣雄。","或看翡翠蘭苕上，未掣鯨鱼碧海中。"]', '诗', 'shi', '', NULL, '戲爲六絕句 四 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d29fb28a-590d-4d67-9be7-a0217dc6f0c8', '戲爲六絕句 五', '戲爲六絕句 五', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["不薄今人愛古人，清詞麗句必爲鄰。","竊攀屈宋宜方駕，恐與齊梁作後塵。"]', '["不薄今人愛古人，清词丽句必爲鄰。","竊攀屈宋宜方駕，恐與齊梁作後塵。"]', '诗', 'shi', '', NULL, '戲爲六絕句 五 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25ab327b-62f9-426e-b195-bd7522b5db7f', '戲爲六絕句 六', '戲爲六絕句 六', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["未及前賢更勿疑，遞相祖述復先誰。","別裁僞體親風雅，轉益多師是汝師。"]', '["未及前賢更勿疑，遞相祖述复先誰。","別裁僞體親风雅，轉益多師是汝師。"]', '诗', 'shi', '', NULL, '戲爲六絕句 六 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ccf27df-fb7e-4665-a27b-c7cd92e8321d', '江頭四詠 丁香', '江头四詠 丁香', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["丁香體柔弱，亂結枝猶墊。","細葉帶浮毛，疎花披素豔。","深栽小齋後，庶近幽人占。","晚墮蘭麝中，休懷粉身念。"]', '["丁香體柔弱，亂結枝猶墊。","細葉带浮毛，疎花披素豔。","深栽小斋後，庶近幽人占。","晚墮蘭麝中，休懷粉身念。"]', '诗', 'shi', '', NULL, '江頭四詠 丁香 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e048354-fb21-45be-b06b-6429129fca07', '江頭四詠 梔子', '江头四詠 梔子', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["梔子比衆木，人間誠未多。","於身色有用，與道氣傷和。","紅取風霜實，青看雨露柯。","無情移得汝，貴在映江波。"]', '["梔子比衆木，人间誠未多。","於身色有用，與道氣傷和。","紅取风霜實，青看雨露柯。","無情移得汝，貴在映江波。"]', '诗', 'shi', '', NULL, '江頭四詠 梔子 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c114f681-f10b-4974-9640-c09d4b7f4658', '江頭四詠 鸂鶒', '江头四詠 鸂鶒', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["故使籠寬織，須知動損毛。","看雲莫悵望，失水任呼號。","六翮曾經剪，孤飛卒未高。","且無鷹隼慮，留滯莫辭勞。"]', '["故使籠寬织，須知动損毛。","看云莫悵望，失水任呼號。","六翮曾經剪，孤飞卒未高。","且無鷹隼慮，留滯莫辞勞。"]', '诗', 'shi', '', NULL, '江頭四詠 鸂鶒 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3df2ee44-0907-409e-8efb-4d21c1b65908', '江頭四詠 花鴨', '江头四詠 花鴨', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["花鴨無泥滓，堦前每緩行。","羽毛知獨立，黑白太分明。","不覺羣心妒，休牽衆眼驚。","稻粱霑汝在，作意莫先鳴。"]', '["花鴨無泥滓，堦前每緩行。","羽毛知独立，黑白太分明。","不覺羣心妒，休牽衆眼驚。","稻粱霑汝在，作意莫先鳴。"]', '诗', 'shi', '', NULL, '江頭四詠 花鴨 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55ea6a6b-4849-4712-b076-f343e5c9080c', '畏人', '畏人', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["早花隨處發，春鳥異方啼。","萬里清江上，三年落日低。","畏人成小築，褊性合幽棲。","門徑從榛草，無心走馬蹄。"]', '["早花隨处發，春鸟異方啼。","万里清江上，三年落日低。","畏人成小築，褊性合幽棲。","门徑從榛草，無心走马蹄。"]', '诗', 'shi', '', NULL, '畏人 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef3344f2-2cdc-4221-b650-d744a5d454d4', '遠遊', '远游', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["賤子何人記，迷芳著處家。","竹風連野色，江沫擁春沙。","種藥扶衰病，吟詩解歎嗟。","似聞胡騎走，失喜問京華。"]', '["賤子何人記，迷芳著处家。","竹风連野色，江沫擁春沙。","種藥扶衰病，吟诗解歎嗟。","似闻胡騎走，失喜问京华。"]', '诗', 'shi', '', NULL, '遠遊 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d77f340f-1a04-4c5b-9704-2536e4249c6b', '野望', '野望', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["西山白雪三奇戍，南浦清江萬里橋。","海內風塵諸弟隔，天涯涕淚一身遙。","唯將遲暮供多病，未有涓埃荅聖朝。","跨馬出郊時極目，不堪人事日蕭條。"]', '["西山白雪三奇戍，南浦清江万里橋。","海內风塵諸弟隔，天涯涕泪一身遙。","唯將遲暮供多病，未有涓埃荅聖朝。","跨马出郊时極目，不堪人事日蕭條。"]', '诗', 'shi', '', NULL, '野望 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d667cadd-45f0-44ef-947c-1c166be18ccd', '官池春鴈二首 一', '官池春鴈二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["自古稻粱多不足，至今鸂鶒亂爲羣。","且休悵望看春水，更恐歸飛隔暮雲。"]', '["自古稻粱多不足，至今鸂鶒亂爲羣。","且休悵望看春水，更恐归飞隔暮云。"]', '诗', 'shi', '', NULL, '官池春鴈二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4d1bf61-c4e9-4826-86d9-83b237289e87', '官池春鴈二首 二', '官池春鴈二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["青春欲盡急還鄉，紫塞寧論尚有霜。","翅在雲天終不遠，力微[矰]繳絕須防。"]', '["青春欲尽急還乡，紫塞寧論尚有霜。","翅在云天終不远，力微[矰]繳絕須防。"]', '诗', 'shi', '', NULL, '官池春鴈二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ddcb96ce-37ef-4674-9ce3-c9b3b9116191', '水檻遣心二首 一', '水檻遣心二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["去郭軒楹敞，無村眺望賒。","澄江平少岸，幽樹晚多花。","細雨魚兒出，微風燕子斜。","城中十萬戶，此地兩三家。"]', '["去郭軒楹敞，無村眺望賒。","澄江平少岸，幽樹晚多花。","細雨鱼兒出，微风燕子斜。","城中十万戶，此地兩三家。"]', '诗', 'shi', '', NULL, '水檻遣心二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01005a3d-74b2-4be9-b025-6b82b05d936f', '水檻遣心二首 二', '水檻遣心二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["蜀天常夜雨，江檻已朝晴。","葉潤林塘密，衣乾枕席清。","不堪秪老病，何得尚浮名。","淺把涓涓酒，深憑送此生。"]', '["蜀天常夜雨，江檻已朝晴。","葉潤林塘密，衣乾枕席清。","不堪秪老病，何得尚浮名。","淺把涓涓酒，深憑送此生。"]', '诗', 'shi', '', NULL, '水檻遣心二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f54ce551-a776-477b-b9a7-0a5896fa2325', '屏跡三首 一', '屏跡三首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["用拙存吾道，幽居近物情。","桑麻深雨露，燕雀半生成。","村鼓時時急，漁舟箇箇輕。","杖藜從白首，心跡喜雙清。"]', '["用拙存吾道，幽居近物情。","桑麻深雨露，燕雀半生成。","村鼓时时急，漁舟箇箇轻。","杖藜從白首，心跡喜雙清。"]', '诗', 'shi', '', NULL, '屏跡三首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c78c67c0-9223-44c3-a77c-0ebd19d09a56', '屏跡三首 二', '屏跡三首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["晚起家何事，無營地轉幽。","竹光團野色，舍影漾江流。","失學從兒嬾，長貧任婦愁。","百年渾得醉，一月不梳頭。"]', '["晚起家何事，無營地轉幽。","竹光團野色，舍影漾江流。","失学從兒嬾，长貧任婦愁。","百年渾得醉，一月不梳头。"]', '诗', 'shi', '', NULL, '屏跡三首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e9f685e-b34b-416b-ba2b-77fb54c47ec1', '屏跡三首 三', '屏跡三首 三', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["衰顏甘屏迹，幽事供高臥。","鳥下竹根行，龜開萍葉過。","年荒酒價乏，日併園蔬課。","猶酌甘泉歌，歌長擊樽破。"]', '["衰顏甘屏迹，幽事供高臥。","鸟下竹根行，龟开萍葉過。","年荒酒價乏，日併园蔬課。","猶酌甘泉歌，歌长擊樽破。"]', '诗', 'shi', '', NULL, '屏跡三首 三 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbacb2f4-5bbb-427e-94ad-6ceac6e92253', '奉酬嚴公寄題野亭之作', '奉酬嚴公寄題野亭之作', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["拾遺曾奏數行書，嬾性從來水竹居。","奉引濫騎沙苑馬，幽棲真釣錦江魚。","謝安不倦登臨費，阮籍焉知禮法疎。","枉沐旌麾出城府，草茅無徑欲教鋤。"]', '["拾遺曾奏數行书，嬾性從来水竹居。","奉引濫騎沙苑马，幽棲真釣錦江鱼。","謝安不倦登臨費，阮籍焉知禮法疎。","枉沐旌麾出城府，草茅無徑欲教鋤。"]', '诗', 'shi', '', NULL, '奉酬嚴公寄題野亭之作 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a79d86da-f914-4a15-97e6-34a36d856701', '中丞嚴公雨中垂寄見憶一絕奉荅二絕 一', '中丞嚴公雨中垂寄见憶一絕奉荅二絕 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["雨映行宮辱贈詩，元戎肯赴野人期。","江邊老病雖無力，強擬晴天理釣絲。"]', '["雨映行宮辱贈诗，元戎肯赴野人期。","江邊老病雖無力，強擬晴天理釣絲。"]', '诗', 'shi', '', NULL, '中丞嚴公雨中垂寄見憶一絕奉荅二絕 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a36829d1-e25f-4c31-99cc-f76f540e84b9', '中丞嚴公雨中垂寄見憶一絕奉荅二絕 二', '中丞嚴公雨中垂寄见憶一絕奉荅二絕 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["何日雨晴雲出溪，白沙青石先無泥。","只須伐竹開荒徑，倚杖穿花聽馬嘶。"]', '["何日雨晴云出溪，白沙青石先無泥。","只須伐竹开荒徑，倚杖穿花听马嘶。"]', '诗', 'shi', '', NULL, '中丞嚴公雨中垂寄見憶一絕奉荅二絕 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7961f8c-6bd0-4a4d-89f8-0a10ba3f77b9', '謝嚴中丞送青城山道士乳酒一瓶', '謝嚴中丞送青城山道士乳酒一瓶', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["山瓶乳酒下青雲，氣味濃香幸見分。","鳴鞭走送憐漁父，洗盞開嘗對馬軍。"]', '["山瓶乳酒下青云，氣味濃香幸见分。","鳴鞭走送怜漁父，洗盞开嘗对马軍。"]', '诗', 'shi', '', NULL, '謝嚴中丞送青城山道士乳酒一瓶 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cc5a45c-2739-4fc6-9ea9-ca01d2eee3e7', '嚴公仲夏枉駕草堂兼攜酒饌', '嚴公仲夏枉駕草堂兼携酒饌', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["竹裏行廚洗玉盤，花邊立馬簇金鞍。","非關使者徵求急，自識將軍禮數寬。","百年地闢柴門逈，五月江深草閣寒。","看弄漁舟移白日，老農何有罄交歡。"]', '["竹裏行廚洗玉盤，花邊立马簇金鞍。","非关使者徵求急，自識將軍禮數寬。","百年地闢柴门逈，五月江深草閣寒。","看弄漁舟移白日，老農何有罄交歡。"]', '诗', 'shi', '', NULL, '嚴公仲夏枉駕草堂兼攜酒饌 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e754fed-aabb-441a-8bdb-ed98dfa07e89', '嚴公廳宴同詠蜀道畫圖', '嚴公廳宴同詠蜀道畫圖', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["日臨公館靜，畫滿地圖雄。","劒閣星橋北，松州雪嶺東。","華夷山不斷，吳蜀水相通。","興與煙霞會，清樽幸不空。"]', '["日臨公館静，畫满地圖雄。","劒閣星橋北，松州雪嶺东。","华夷山不斷，吳蜀水相通。","兴與煙霞會，清樽幸不空。"]', '诗', 'shi', '', NULL, '嚴公廳宴同詠蜀道畫圖 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39df70ad-1359-4f75-9358-421aa7db5fe6', '奉送嚴公入朝十韻', '奉送嚴公入朝十韻', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["鼎湖瞻望遠，象闕憲章新。","四海猶多難，中原憶舊臣。","與時安反側，自昔有經綸。","感激張天步，從容靜塞塵。","南圖迴羽翮，北極捧星辰，漏鼓還思晝，宮鶯罷囀春。","空留玉帳術，愁殺錦城人。","閣道通丹地，江潭隱白蘋。","此生那老蜀，不死會歸秦。","公若登台輔，臨危莫愛身。"]', '["鼎湖瞻望远，象闕憲章新。","四海猶多难，中原憶旧臣。","與时安反側，自昔有經綸。","感激張天步，從容静塞塵。","南圖迴羽翮，北極捧星辰，漏鼓還思晝，宮鶯罷囀春。","空留玉帳術，愁殺錦城人。","閣道通丹地，江潭隐白蘋。","此生那老蜀，不死會归秦。","公若登台輔，臨危莫愛身。"]', '诗', 'shi', '', NULL, '奉送嚴公入朝十韻 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11d6a21c-af79-4347-91b6-27c5009d8b42', '送嚴侍郎到綿州同登杜使君江樓', '送嚴侍郎到綿州同登杜使君江楼', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["野興每難盡，江樓延賞心。","歸朝送使節，落景惜登臨。","稍稍煙集渚，微微風動襟。","重船依淺瀨，輕鳥度層陰。","檻峻背幽谷，窗虛交茂林。","燈光散遠近，月彩靜高深。","城擁朝來客，天橫醉後參。","窮途衰謝意，苦調短長吟。","此會共能幾，諸孫賢至今。","不勞朱戶閉，自待白河沈。"]', '["野兴每难尽，江楼延賞心。","归朝送使節，落景惜登臨。","稍稍煙集渚，微微风动襟。","重船依淺瀨，轻鸟度層陰。","檻峻背幽谷，窗虛交茂林。","灯光散远近，月彩静高深。","城擁朝来客，天橫醉後參。","窮途衰謝意，苦調短长吟。","此會共能幾，諸孫賢至今。","不勞朱戶閉，自待白河沈。"]', '诗', 'shi', '', NULL, '送嚴侍郎到綿州同登杜使君江樓 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2c83ee2-940f-4ae3-9ab3-4f509d2991f3', '奉濟驛重送嚴公四韻', '奉濟驛重送嚴公四韻', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["遠送從此別，青山空復情。","幾時桮重把，昨夜月同行。","列郡謳歌惜，三朝出入榮。","江村獨歸處，寂寞養殘生。"]', '["远送從此別，青山空复情。","幾时桮重把，昨夜月同行。","列郡謳歌惜，三朝出入榮。","江村独归处，寂寞養殘生。"]', '诗', 'shi', '', NULL, '奉濟驛重送嚴公四韻 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('522051e4-d5f3-4417-886a-93f2a54b6a7d', '送梓州李使君之任', '送梓州李使君之任', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["籍甚黃丞相，能名自潁川。","近看除刺史，還喜得吾賢。","五馬何時到，雙魚會早傳。","老思筇竹杖，冬要錦衾眠。","不作臨岐恨，惟聽舉最先。","火雲揮汗日，山驛醒心泉。","遇害陳公殞，於今蜀道憐。","君行射洪縣，爲我一潸然。"]', '["籍甚黄丞相，能名自潁川。","近看除刺史，還喜得吾賢。","五马何时到，雙鱼會早傳。","老思筇竹杖，冬要錦衾眠。","不作臨岐恨，惟听舉最先。","火云揮汗日，山驛醒心泉。","遇害陳公殞，於今蜀道怜。","君行射洪縣，爲我一潸然。"]', '诗', 'shi', '', NULL, '送梓州李使君之任 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5536e9ad-1b12-4070-b6e0-908f7874e832', '巴西驛亭觀江漲呈竇使君', '巴西驛亭观江漲呈竇使君', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["宿雨南江漲，波濤亂遠峰。","孤亭凌噴薄，萬井逼舂容。","霄漢愁高鳥，泥沙困老龍。","天邊同客舍，攜我豁心胸。"]', '["宿雨南江漲，波濤亂远峰。","孤亭凌噴薄，万井逼舂容。","霄漢愁高鸟，泥沙困老龙。","天邊同客舍，携我豁心胸。"]', '诗', 'shi', '', NULL, '巴西驛亭觀江漲呈竇使君 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04fa7a4c-e624-4083-9668-b05394a5a61d', '九日登梓州城', '九日登梓州城', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["伊昔黃花酒，如今白髮翁。","追歡筋力異，望遠歲時同。","弟妹悲歌裏，朝廷醉眼中。","兵戈與關塞，此日意無窮。"]', '["伊昔黄花酒，如今白髮翁。","追歡筋力異，望远歲时同。","弟妹悲歌裏，朝廷醉眼中。","兵戈與关塞，此日意無窮。"]', '诗', 'shi', '', NULL, '九日登梓州城 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c56fd82e-2fab-4c3b-b52c-2631132e0ddf', '九日奉寄嚴大夫', '九日奉寄嚴大夫', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["九日應愁思，經時冒險艱。","不眠持漢節，何路出巴山。","小驛香醪嫩，重巖細菊斑。","遙知簇鞍馬，迴首白雲間。"]', '["九日應愁思，經时冒險艱。","不眠持漢節，何路出巴山。","小驛香醪嫩，重巖細菊斑。","遙知簇鞍马，迴首白云间。"]', '诗', 'shi', '', NULL, '九日奉寄嚴大夫 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a5a2b89-5aa0-4c83-ade1-9fba0784f6e6', '黃草', '黄草', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["黃草峽西船不歸，赤甲山下行人稀。","秦中驛使無消息，蜀道兵戈有是非。","萬里秋風吹錦水，誰家別淚濕羅衣。","莫愁劒閣終堪據，聞道松州已被圍。"]', '["黄草峽西船不归，赤甲山下行人稀。","秦中驛使無消息，蜀道兵戈有是非。","万里秋风吹錦水，誰家別泪濕羅衣。","莫愁劒閣終堪據，闻道松州已被圍。"]', '诗', 'shi', '', NULL, '黃草 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15bd7c09-3748-4340-b221-13d9e3e1ea38', '懷舊', '懷旧', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["地下蘇司業，情親獨有君。","那因喪亂後，便有死生分。","老罷知明鏡，悲來望白雲。","自從失詞伯，不復更論文。"]', '["地下蘇司業，情親独有君。","那因喪亂後，便有死生分。","老罷知明镜，悲来望白云。","自從失词伯，不复更論文。"]', '诗', 'shi', '', NULL, '懷舊 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('963be762-f666-4505-918f-9576c1696f8f', '所思', '所思', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["鄭老身仍竄，台州信所傳。","爲農山澗曲，臥病海雲邊。","世已疎儒素，人猶乞酒錢。","徒勞望牛斗，無計劚龍泉。"]', '["鄭老身仍竄，台州信所傳。","爲農山澗曲，臥病海云邊。","世已疎儒素，人猶乞酒錢。","徒勞望牛斗，無計劚龙泉。"]', '诗', 'shi', '', NULL, '所思 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bce54d8-5f1a-487b-807c-b30714c006f4', '不見', '不见', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["不見李生久，佯狂真可哀。","世人皆欲殺，吾意獨憐才。","敏捷詩千首，飄零酒一桮。","匡山讀書處，頭白好歸來。"]', '["不见李生久，佯狂真可哀。","世人皆欲殺，吾意独怜才。","敏捷诗千首，飄零酒一桮。","匡山读书处，头白好归来。"]', '诗', 'shi', '', NULL, '不見 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('785ea8b0-4589-4ea2-a01c-226a2556dbe5', '題玄武禪師屋壁', '題玄武禪師屋壁', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["何年顧虎頭，滿壁畫瀛州。","赤日石林氣，青天江海流。","錫飛常近鶴，桮度不驚鷗。","似得廬山路，真隨惠遠遊。"]', '["何年顧虎头，满壁畫瀛州。","赤日石林氣，青天江海流。","錫飞常近鹤，桮度不驚鷗。","似得廬山路，真隨惠远游。"]', '诗', 'shi', '', NULL, '題玄武禪師屋壁 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a60d32f9-47fc-4974-8e11-e4473e976fa9', '客夜', '客夜', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["客睡何曾著，秋天不肯明。","卷簾殘月影，高枕遠江聲。","計拙無衣食，途窮仗友生。","老妻書數紙，應悉未歸情。"]', '["客睡何曾著，秋天不肯明。","卷簾殘月影，高枕远江声。","計拙無衣食，途窮仗友生。","老妻书數紙，應悉未归情。"]', '诗', 'shi', '', NULL, '客夜 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0d0cc44-b364-4ac6-82cf-bedbe162d184', '客亭', '客亭', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["秋窗猶曙色，落木更天風。","日出寒山外，江流宿霧中。","聖朝無棄物，老病已成翁。","多少殘生事，飄零似轉蓬。"]', '["秋窗猶曙色，落木更天风。","日出寒山外，江流宿霧中。","聖朝無棄物，老病已成翁。","多少殘生事，飄零似轉蓬。"]', '诗', 'shi', '', NULL, '客亭 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f0c8f24-0fc9-49b9-9f2a-151c2dd1d7ef', '秋盡', '秋尽', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["秋盡東行且未迴，茅齋寄在少城隈。","籬邊老却陶潛菊，江上徒逢袁紹桮。","雪嶺獨看西日落，劒門猶阻北人來。","不辭萬里長爲客，懷抱何時得好開。"]', '["秋尽东行且未迴，茅斋寄在少城隈。","籬邊老却陶潛菊，江上徒逢袁紹桮。","雪嶺独看西日落，劒门猶阻北人来。","不辞万里长爲客，懷抱何时得好开。"]', '诗', 'shi', '', NULL, '秋盡 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6d43315-55b6-466c-93e9-2ca33b1c7f41', '陪王侍御宴通泉東山野亭', '陪王侍御宴通泉东山野亭', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["江水東流去，清樽日復斜。","異方同宴賞，何處是京華。","亭景臨山水，村煙對浦沙。","狂歌過于勝，得醉即爲家。"]', '["江水东流去，清樽日复斜。","異方同宴賞，何处是京华。","亭景臨山水，村煙对浦沙。","狂歌過于勝，得醉即爲家。"]', '诗', 'shi', '', NULL, '陪王侍御宴通泉東山野亭 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6261e535-3294-4e7f-b9ba-f014cb45fdf2', '野望', '野望', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["金華山北涪水西，仲冬風日始淒淒。","山連越巂蟠三蜀，水散巴渝下五溪。","獨鶴不知何事舞，飢烏似欲向人啼。","射洪春酒寒仍綠，目極傷神誰爲攜。"]', '["金华山北涪水西，仲冬风日始淒淒。","山連越巂蟠三蜀，水散巴渝下五溪。","独鹤不知何事舞，飢烏似欲向人啼。","射洪春酒寒仍綠，目極傷神誰爲携。"]', '诗', 'shi', '', NULL, '野望 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22e90c0d-2b59-4500-8e5d-80d38ec4692c', '聞官軍收河南河北', '闻官軍收河南河北', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["劒外忽傳收薊北，初聞涕淚滿衣裳。","却看妻子愁何在，漫卷詩書喜欲狂。","白日放歌須縱酒，青春作伴好還鄉。","即從巴峽穿巫峽，便下襄陽向洛陽。"]', '["劒外忽傳收薊北，初闻涕泪满衣裳。","却看妻子愁何在，漫卷诗书喜欲狂。","白日放歌須縱酒，青春作伴好還乡。","即從巴峽穿巫峽，便下襄陽向洛陽。"]', '诗', 'shi', '', NULL, '聞官軍收河南河北 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26c93a67-071e-4dae-b2af-94bb6e5b6c40', '涪江泛舟送韋班歸京', '涪江泛舟送韋班归京', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["追餞同舟日，傷春一水間。","飄零爲客久，衰老羨君還。","花遠重重樹，雲輕處處山。","天涯故人少，更益鬢毛斑。"]', '["追餞同舟日，傷春一水间。","飄零爲客久，衰老羨君還。","花远重重樹，云轻处处山。","天涯故人少，更益鬢毛斑。"]', '诗', 'shi', '', NULL, '涪江泛舟送韋班歸京 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('199341fd-ab03-4ea1-8862-f5948784254f', '春日梓州登樓二首 一', '春日梓州登楼二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["行路難如此，登樓望欲迷。","身無却少壯，跡有但羇栖。","江水流城郭，春風入鼓鞞。","雙雙新燕子，依舊已銜泥。"]', '["行路难如此，登楼望欲迷。","身無却少壯，跡有但羇栖。","江水流城郭，春风入鼓鞞。","雙雙新燕子，依旧已銜泥。"]', '诗', 'shi', '', NULL, '春日梓州登樓二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb5d2cce-6719-4c86-809a-d5b9e9ec5317', '春日梓州登樓二首 二', '春日梓州登楼二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["天畔登樓眼，隨春入故園。","戰場今始定，移柳更能存。","厭蜀交遊冷，思吳勝事繁。","應須理舟楫，長嘯下荆門。"]', '["天畔登楼眼，隨春入故园。","戰場今始定，移柳更能存。","厭蜀交游冷，思吳勝事繁。","應須理舟楫，长嘯下荆门。"]', '诗', 'shi', '', NULL, '春日梓州登樓二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a77f43c-343a-4023-88af-959e5ef629d9', '郪城西原送李判官兄武判官弟赴成都府', '郪城西原送李判官兄武判官弟赴成都府', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["憑高送所親，久坐惜芳辰。","遠水非無浪，他山自有春。","野花隨處發，官柳著行新。","天際傷愁別，離筵何太頻。"]', '["憑高送所親，久坐惜芳辰。","远水非無浪，他山自有春。","野花隨处發，官柳著行新。","天際傷愁別，離筵何太頻。"]', '诗', 'shi', '', NULL, '郪城西原送李判官兄武判官弟赴成都府 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d44ba72-a869-4ab1-a67b-07dbaf6deefe', '泛江送魏十八倉曹還京因寄岑中允參范郎中季明', '泛江送魏十八倉曹還京因寄岑中允參范郎中季明', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["遲日深春水，輕舟送別筵。","帝鄉愁緒外，春色淚痕邊。","見酒須相憶，將詩莫浪傳。","若逢岑與范，爲報各衰年。"]', '["遲日深春水，轻舟送別筵。","帝乡愁緒外，春色泪痕邊。","见酒須相憶，將诗莫浪傳。","若逢岑與范，爲報各衰年。"]', '诗', 'shi', '', NULL, '泛江送魏十八倉曹還京因寄岑中允參范郎中季明 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a3b9a26-f709-4ea8-a717-29545fb55d61', '送路六侍御入朝', '送路六侍御入朝', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["童稚情親四十年，中間消息兩茫然。","更爲後會知何地，忽漫相逢是別筵。","不分桃花紅勝錦，生憎柳絮白於綿。","劒南春色還無賴，觸忤愁人到酒邊。"]', '["童稚情親四十年，中间消息兩茫然。","更爲後會知何地，忽漫相逢是別筵。","不分桃花紅勝錦，生憎柳絮白於綿。","劒南春色還無賴，觸忤愁人到酒邊。"]', '诗', 'shi', '', NULL, '送路六侍御入朝 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce481d03-508e-4392-95f6-06ff82d8bb3c', '泛江送客', '泛江送客', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["二月頻送客，東津江欲平。","煙花山際重，舟楫浪前輕。","淚逐勸桮下，愁連吹笛生。","離筵不隔日，那得易爲情。"]', '["二月頻送客，东津江欲平。","煙花山際重，舟楫浪前轻。","泪逐勸桮下，愁連吹笛生。","離筵不隔日，那得易爲情。"]', '诗', 'shi', '', NULL, '泛江送客 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0a4bf94-c1b4-45fa-98bc-26705d77a88a', '上牛頭寺', '上牛头寺', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["青山意不盡，衮衮上牛頭。","無復能拘礙，真成浪出遊。","花濃春寺靜，竹細野池幽。","何處鶯啼切，移時獨未休。"]', '["青山意不尽，衮衮上牛头。","無复能拘礙，真成浪出游。","花濃春寺静，竹細野池幽。","何处鶯啼切，移时独未休。"]', '诗', 'shi', '', NULL, '上牛頭寺 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('370c5c28-2d1b-4142-a1c0-f65ed1dd3275', '望牛頭寺', '望牛头寺', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["牛頭見鶴林，梯徑繞幽深。","春色浮山外，天河宿殿陰。","傳燈無白日，布地有黃金。","休作狂歌老，迴看不住心。"]', '["牛头见鹤林，梯徑繞幽深。","春色浮山外，天河宿殿陰。","傳灯無白日，布地有黄金。","休作狂歌老，迴看不住心。"]', '诗', 'shi', '', NULL, '望牛頭寺 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c341f4ff-dc3d-43a5-acaa-3554bc604c89', '上兜率寺', '上兜率寺', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["兜率知名寺，真如會法堂。","江山有巴蜀，棟宇自齊梁。","庾信哀雖久，何顒好不忘。","白牛車遠近，且欲上慈航。"]', '["兜率知名寺，真如會法堂。","江山有巴蜀，棟宇自齊梁。","庾信哀雖久，何顒好不忘。","白牛车远近，且欲上慈航。"]', '诗', 'shi', '', NULL, '上兜率寺 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('390a0252-d484-4267-be3a-6326461d93cf', '望兜率寺', '望兜率寺', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["樹密當山徑，江深隔寺門。","霏霏雲氣重，閃閃浪花飜。","不復知天大，空餘見佛尊。","時應清盥罷，隨喜給孤園。"]', '["樹密當山徑，江深隔寺门。","霏霏云氣重，閃閃浪花飜。","不复知天大，空餘见佛尊。","时應清盥罷，隨喜給孤园。"]', '诗', 'shi', '', NULL, '望兜率寺 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09d3f32e-3fc8-48dc-8dfe-0fbbef4614a1', '甘園', '甘园', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["春日清江岸，千甘二頃園。","青雲羞葉密，白雪避花繁。","結子隨邊使，開筒近至尊。","後於桃李熟，終得獻金門。"]', '["春日清江岸，千甘二頃园。","青云羞葉密，白雪避花繁。","結子隨邊使，开筒近至尊。","後於桃李熟，終得獻金门。"]', '诗', 'shi', '', NULL, '甘園 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cedb3c9c-602a-47db-b024-c51c9247233d', '數陪李梓州泛江有女樂在諸舫戲爲豔曲二首贈李 一', '數陪李梓州泛江有女乐在諸舫戲爲豔曲二首贈李 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["上客迴空騎，佳人滿近船。","江清歌扇底，野曠舞衣前。","玉袖凌風並，金壺隱浪偏。","競將明媚色，偷眼豔陽天。"]', '["上客迴空騎，佳人满近船。","江清歌扇底，野曠舞衣前。","玉袖凌风並，金壺隐浪偏。","競將明媚色，偷眼豔陽天。"]', '诗', 'shi', '', NULL, '數陪李梓州泛江有女樂在諸舫戲爲豔曲二首贈李 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40e3b186-d3b4-4ae8-a65c-bd5ba20d80de', '數陪李梓州泛江有女樂在諸舫戲爲豔曲二首贈李 二', '數陪李梓州泛江有女乐在諸舫戲爲豔曲二首贈李 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["白日移歌袖，清霄近笛牀。","翠眉縈度曲，雲鬢儼分行。","立馬千山暮，迴舟一水香。","使君自有婦，莫學野鴛鴦。"]', '["白日移歌袖，清霄近笛牀。","翠眉縈度曲，云鬢儼分行。","立马千山暮，迴舟一水香。","使君自有婦，莫学野鴛鴦。"]', '诗', 'shi', '', NULL, '數陪李梓州泛江有女樂在諸舫戲爲豔曲二首贈李 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c40be16a-a428-4903-abb8-27d292a62cf9', '登牛頭山亭子', '登牛头山亭子', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["路出雙林外，亭窺萬井中。","江城孤照日，山谷遠含風。","兵革身將老，關河信不通。","猶殘數行淚，忍對百花叢。"]', '["路出雙林外，亭窺万井中。","江城孤照日，山谷远含风。","兵革身將老，关河信不通。","猶殘數行泪，忍对百花叢。"]', '诗', 'shi', '', NULL, '登牛頭山亭子 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3068ad59-dc74-4ef7-8f15-30c1d235ec0b', '陪李梓州王閬州蘇遂州李果州四使君登惠義寺', '陪李梓州王閬州蘇遂州李果州四使君登惠義寺', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["春日無人境，虛空不住天。","鶯花隨世界，樓閣寄山巔。","遲暮身何得，登臨意惘然。","誰能解金印，瀟灑共安禪。"]', '["春日無人境，虛空不住天。","鶯花隨世界，楼閣寄山巔。","遲暮身何得，登臨意惘然。","誰能解金印，瀟灑共安禪。"]', '诗', 'shi', '', NULL, '陪李梓州王閬州蘇遂州李果州四使君登惠義寺 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('197b472d-2b3f-4099-be8e-11a17dd96c20', '送何侍御歸朝', '送何侍御归朝', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["舟楫諸侯餞，車輿使者歸。","山花相映發，水鳥自孤飛。","春日垂霜鬢，天隅把繡衣。","故人從此去，寥落寸心違。"]', '["舟楫諸侯餞，车輿使者归。","山花相映發，水鸟自孤飞。","春日垂霜鬢，天隅把繡衣。","故人從此去，寥落寸心違。"]', '诗', 'shi', '', NULL, '送何侍御歸朝 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18c5fa19-1eba-4c04-933c-f66b8f3e8d84', '江亭送眉州辛別駕昇之', '江亭送眉州辛別駕昇之', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["柳影含雲幕，江波近酒壺。","異方驚會面，終宴惜征途。","沙晚低風蝶，天晴喜浴鳧。","別離傷老大，意緒日荒蕪。"]', '["柳影含云幕，江波近酒壺。","異方驚會面，終宴惜征途。","沙晚低风蝶，天晴喜浴鳧。","別離傷老大，意緒日荒蕪。"]', '诗', 'shi', '', NULL, '江亭送眉州辛別駕昇之 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c7af851-a5b4-4726-bb19-551d2e2035df', '涪城縣香積寺官閣', '涪城縣香積寺官閣', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["寺下春江深不流，山腰官閣迥添愁。","含風翠壁孤雲細，背日丹楓萬木稠。","小院迴廊春寂寂，浴鳧飛鷺晚悠悠。","諸天合在藤蘿外，昏黑應須到上頭。"]', '["寺下春江深不流，山腰官閣迥添愁。","含风翠壁孤云細，背日丹楓万木稠。","小院迴廊春寂寂，浴鳧飞鷺晚悠悠。","諸天合在藤蘿外，昏黑應須到上头。"]', '诗', 'shi', '', NULL, '涪城縣香積寺官閣 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20c07417-d1ac-43f8-b3e9-504103647e99', '戲題寄上漢中王三首 一', '戲題寄上漢中王三首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["西漢親王子，成都老客星。","百年雙白鬢，一別五秋螢。","忍斷桮中物，秪看座右銘。","不能隨皂蓋，自醉逐浮萍。"]', '["西漢親王子，成都老客星。","百年雙白鬢，一別五秋螢。","忍斷桮中物，秪看座右銘。","不能隨皂蓋，自醉逐浮萍。"]', '诗', 'shi', '', NULL, '戲題寄上漢中王三首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47a316ac-ed57-45fb-8ca7-8ee26389a7d2', '戲題寄上漢中王三首 二', '戲題寄上漢中王三首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["策杖時能出，王門異昔遊。","已知嗟不起，未許醉相留。","蜀酒濃無敵，江魚美可求。","終思一酩酊，淨掃鴈池頭。"]', '["策杖时能出，王门異昔游。","已知嗟不起，未許醉相留。","蜀酒濃無敵，江鱼美可求。","終思一酩酊，淨掃鴈池头。"]', '诗', 'shi', '', NULL, '戲題寄上漢中王三首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4c8cd03-d2a8-4bc9-97f1-496566f10b3a', '戲題寄上漢中王三首 三', '戲題寄上漢中王三首 三', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["羣盜無歸路，衰顏會遠方。","尚憐詩警策，猶記酒顛狂。","魯衛彌尊重，徐陳略喪亡。","空餘枚叟在，應念早升堂。"]', '["羣盜無归路，衰顏會远方。","尚怜诗警策，猶記酒顛狂。","魯衛彌尊重，徐陳略喪亡。","空餘枚叟在，應念早升堂。"]', '诗', 'shi', '', NULL, '戲題寄上漢中王三首 三 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e339d42e-c929-458f-ab1c-a37215e654e5', '陪章留後侍御宴南樓', '陪章留後侍御宴南楼', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["絕域長夏晚，茲樓清宴同。","朝廷燒棧北，鼓角滿天東。","屢食將軍第，仍騎御史驄。","本無丹竈術，那免白頭翁。","寇盜狂歌外，形骸痛飲中。","野雲低渡水，簷雨細隨風。","出號江城黑，題詩蠟炬紅。","此身醒[復]醉，不擬哭途窮。"]', '["絕域长夏晚，茲楼清宴同。","朝廷燒棧北，鼓角满天东。","屢食將軍第，仍騎御史驄。","本無丹竈術，那免白头翁。","寇盜狂歌外，形骸痛饮中。","野云低渡水，簷雨細隨风。","出號江城黑，題诗蠟炬紅。","此身醒[复]醉，不擬哭途窮。"]', '诗', 'shi', '', NULL, '陪章留後侍御宴南樓 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e00f687e-eb10-4e20-a11c-fbe28180a0c9', '臺上', '台上', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["改席臺能迥，留門月復光。","雲行遺暑濕，山谷進風涼。","老去一桮足，誰憐屢舞長。","何須把官燭，似惱鬢毛蒼。"]', '["改席台能迥，留门月复光。","云行遺暑濕，山谷進风涼。","老去一桮足，誰怜屢舞长。","何須把官燭，似惱鬢毛蒼。"]', '诗', 'shi', '', NULL, '臺上 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99862a76-dfe7-4990-b83c-156f72808a7e', '送王十五判官扶侍還黔中', '送王十五判官扶侍還黔中', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["大家東征逐子迴，風生洲渚錦帆開。","青青竹笋迎船出，日日江魚入饌來。","離別不堪無限意，艱危深仗濟時才。","黔陽信使應稀少，莫怪頻頻勸酒杯。"]', '["大家东征逐子迴，风生洲渚錦帆开。","青青竹笋迎船出，日日江鱼入饌来。","離別不堪無限意，艱危深仗濟时才。","黔陽信使應稀少，莫怪頻頻勸酒杯。"]', '诗', 'shi', '', NULL, '送王十五判官扶侍還黔中 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0650e64-eb25-45ff-90b5-c14f3bab9f44', '倦夜', '倦夜', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["竹涼浸臥內，野月滿庭隅。","重露成涓滴，稀星乍有無。","暗飛螢自照，水宿鳥相呼。","萬事干戈裏，空悲清夜徂。"]', '["竹涼浸臥內，野月满庭隅。","重露成涓滴，稀星乍有無。","暗飞螢自照，水宿鸟相呼。","万事干戈裏，空悲清夜徂。"]', '诗', 'shi', '', NULL, '倦夜 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28ec8f35-8740-4889-a17b-7b344d9c6b9a', '悲秋', '悲秋', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["涼風動萬里，羣盜尚縱橫。","家遠傳書日，秋來爲客情。","秋窺高鳥過，老逐衆人行。","始欲投三峽，何由見兩京。"]', '["涼风动万里，羣盜尚縱橫。","家远傳书日，秋来爲客情。","秋窺高鸟過，老逐衆人行。","始欲投三峽，何由见兩京。"]', '诗', 'shi', '', NULL, '悲秋 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1d50761-3ecb-4fa7-903d-9245dffe99d8', '對雨', '对雨', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["莽莽天涯雨，江邊獨立時。","不愁巴道路，恐濕漢旌旗。","雪嶺防秋急，繩橋戰勝遲。","西戎甥舅禮，未敢背恩私。"]', '["莽莽天涯雨，江邊独立时。","不愁巴道路，恐濕漢旌旗。","雪嶺防秋急，繩橋戰勝遲。","西戎甥舅禮，未敢背恩私。"]', '诗', 'shi', '', NULL, '對雨 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c914be80-dbd6-4137-af06-5a38dfbb325f', '警急', '警急', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["才名舊楚將，妙略擁兵機。","玉壘雖傳檄，松州會解圍。","和親知拙計，公主漫無歸。","青海今誰得，西戎實飽飛。"]', '["才名旧楚將，妙略擁兵機。","玉壘雖傳檄，松州會解圍。","和親知拙計，公主漫無归。","青海今誰得，西戎實飽飞。"]', '诗', 'shi', '', NULL, '警急 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d89dc1a-b63d-4061-8284-3a5538524bd8', '王命', '王命', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["漢北豺狼滿，巴西道路難。","血埋諸將甲，骨斷使臣鞍。","牢落新燒棧，蒼茫舊築壇。","深懷喻蜀意，慟哭望王官。"]', '["漢北豺狼满，巴西道路难。","血埋諸將甲，骨斷使臣鞍。","牢落新燒棧，蒼茫旧築壇。","深懷喻蜀意，慟哭望王官。"]', '诗', 'shi', '', NULL, '王命 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0eb40e92-9106-40de-8045-8ecb376e5519', '征夫', '征夫', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["十室幾人在，千山空自多。","路衢唯見哭，城市不聞歌。","漂梗無安地，銜枚有荷戈。","官軍未通蜀，吾道竟如何。"]', '["十室幾人在，千山空自多。","路衢唯见哭，城市不闻歌。","漂梗無安地，銜枚有荷戈。","官軍未通蜀，吾道竟如何。"]', '诗', 'shi', '', NULL, '征夫 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4d82478-9848-469c-a277-ee7b5c6cb01f', '有感五首 一', '有感五首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["將帥蒙恩澤，兵戈有歲年。","至今勞聖主，何以報皇天。","白骨新交戰，雲臺舊拓邊乘槎斷消息，無處覓張騫。"]', '["將帥蒙恩澤，兵戈有歲年。","至今勞聖主，何以報皇天。","白骨新交戰，云台旧拓邊乘槎斷消息，無处覓張騫。"]', '诗', 'shi', '', NULL, '有感五首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4fe56ec8-afff-43c7-a1f2-f5cc8e8701c5', '有感五首 二', '有感五首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["幽薊餘虵豕，乾坤尚虎狼。","諸侯春不貢，使者日相望。","慎勿吞青海，無勞問越裳。","大君先息戰，歸馬華山陽。"]', '["幽薊餘虵豕，乾坤尚虎狼。","諸侯春不貢，使者日相望。","慎勿吞青海，無勞问越裳。","大君先息戰，归马华山陽。"]', '诗', 'shi', '', NULL, '有感五首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc17a18c-4b21-44cb-a1f1-df4a7999392b', '有感五首 三', '有感五首 三', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["洛下舟車入，天中貢賦均。","日聞紅粟腐，寒待翠華春。","莫取金湯固，長令宇宙新。","不過行儉德，盜賊本王臣。"]', '["洛下舟车入，天中貢賦均。","日闻紅粟腐，寒待翠华春。","莫取金湯固，长令宇宙新。","不過行儉德，盜賊本王臣。"]', '诗', 'shi', '', NULL, '有感五首 三 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c87e5521-7e1c-4998-a0b0-952ec1dc8bb5', '有感五首 四', '有感五首 四', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["丹桂風霜急，青梧日夜凋。","由來強幹地，未有不臣朝。","受鉞親賢往，卑宮制詔遙。","終依古封建，豈獨聽簫韶。"]', '["丹桂风霜急，青梧日夜凋。","由来強幹地，未有不臣朝。","受鉞親賢往，卑宮制詔遙。","終依古封建，豈独听簫韶。"]', '诗', 'shi', '', NULL, '有感五首 四 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1176aa60-c713-464f-bcf8-b48cb11a1af6', '有感五首 五', '有感五首 五', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["盜滅人還亂，兵殘將自疑。","登壇名絕假，報主爾何遲。","領郡輙無色，之官皆有詞。","願聞哀痛詔，端拱問瘡痍。"]', '["盜滅人還亂，兵殘將自疑。","登壇名絕假，報主爾何遲。","領郡輙無色，之官皆有词。","願闻哀痛詔，端拱问瘡痍。"]', '诗', 'shi', '', NULL, '有感五首 五 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0549697d-6b1c-45e1-a103-3544530cf6c1', '送元二適江左', '送元二適江左', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["亂後今相見，秋深復遠行。","風塵爲客日，江海送君情。","晉室丹陽尹，公孫白帝城。","經過自愛惜，取次莫論兵。"]', '["亂後今相见，秋深复远行。","风塵爲客日，江海送君情。","晉室丹陽尹，公孫白帝城。","經過自愛惜，取次莫論兵。"]', '诗', 'shi', '', NULL, '送元二適江左 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4483613-0e22-4a92-b300-32a04e7b795e', '章梓州水亭', '章梓州水亭', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["城晚通雲霧，亭深到芰荷。","吏人橋外少，秋水席邊多。","近屬淮王至，高門薊子過。","荆州愛山簡，吾醉亦長歌。"]', '["城晚通云霧，亭深到芰荷。","吏人橋外少，秋水席邊多。","近屬淮王至，高门薊子過。","荆州愛山簡，吾醉亦长歌。"]', '诗', 'shi', '', NULL, '章梓州水亭 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8c7c683-7bc9-4fe3-bf8f-83561f4d5be4', '翫月呈漢中王', '翫月呈漢中王', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["夜深露氣清，江月滿江城。","浮客轉危坐，歸舟應獨行。","關山同一照，烏鵲自多驚。","欲得淮王術，風吹暈已生。"]', '["夜深露氣清，江月满江城。","浮客轉危坐，归舟應独行。","关山同一照，烏鵲自多驚。","欲得淮王術，风吹暈已生。"]', '诗', 'shi', '', NULL, '翫月呈漢中王 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d1e2cf0-65a6-4b4f-8c24-0e507c1113fc', '戲作寄上漢中王二首 一', '戲作寄上漢中王二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["雲裏不聞雙鴈過，掌中貪見一珠新。","秋風嫋嫋吹江漢，只在他鄉何處人。"]', '["云裏不闻雙鴈過，掌中貪见一珠新。","秋风嫋嫋吹江漢，只在他乡何处人。"]', '诗', 'shi', '', NULL, '戲作寄上漢中王二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('550784b8-2f3b-4e4f-a131-bb835ad1e92f', '戲作寄上漢中王二首 二', '戲作寄上漢中王二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["謝安舟楫風還起，梁苑池臺雪欲飛。","杳杳東山攜漢妓，泠泠修竹待王歸。"]', '["謝安舟楫风還起，梁苑池台雪欲飞。","杳杳东山携漢妓，泠泠修竹待王归。"]', '诗', 'shi', '', NULL, '戲作寄上漢中王二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38740d36-f32e-4ae4-b0db-a120d8a2dcbe', '投簡梓州幕府兼簡韋十郎官', '投簡梓州幕府兼簡韋十郎官', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["幕下郎官安穩無，從來不奉一行書。","固知貧病人須棄，能使韋郎跡也疎。"]', '["幕下郎官安穩無，從来不奉一行书。","固知貧病人須棄，能使韋郎跡也疎。"]', '诗', 'shi', '', NULL, '投簡梓州幕府兼簡韋十郎官 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4d718ee-c020-42b4-97df-499cd0076f7b', '登高', '登高', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["風急天高猨嘯哀，渚清沙白鳥飛迴。","無邊落木蕭蕭下，不盡長江衮衮來。","萬里悲秋常作客，百年多病獨登臺。","艱難苦恨繁霜鬢，潦倒新停濁酒桮。"]', '["风急天高猨嘯哀，渚清沙白鸟飞迴。","無邊落木蕭蕭下，不尽长江衮衮来。","万里悲秋常作客，百年多病独登台。","艱难苦恨繁霜鬢，潦倒新停濁酒桮。"]', '诗', 'shi', '', NULL, '登高 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0a22f26-bd2a-457b-8f7d-74add294e009', '九日', '九日', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["去年登高郪縣北，今日重在涪江濱。","苦遭白髮不相放，羞見黃花無數新。","世亂鬱鬱久爲客，路難悠悠常傍人。","酒闌却憶十年事，腸斷驪山清路塵。"]', '["去年登高郪縣北，今日重在涪江濱。","苦遭白髮不相放，羞见黄花無數新。","世亂鬱鬱久爲客，路难悠悠常傍人。","酒闌却憶十年事，腸斷驪山清路塵。"]', '诗', 'shi', '', NULL, '九日 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45a36ed3-5e37-4daa-a253-33734a21e2e4', '遣憤', '遣憤', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["聞道花門將，論功未盡歸。","自從收帝里，誰復總戎機。","蜂蠆終懷毒，雷霆可震威。","莫令鞭血地，再濕漢臣衣。"]', '["闻道花门將，論功未尽归。","自從收帝里，誰复總戎機。","蜂蠆終懷毒，雷霆可震威。","莫令鞭血地，再濕漢臣衣。"]', '诗', 'shi', '', NULL, '遣憤 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('290c5ecc-f832-4b5f-b0cd-51630106148f', '章梓州橘亭餞成都竇少尹', '章梓州橘亭餞成都竇少尹', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["秋日野亭千橘香，玉盤錦席高雲涼。","主人送客何所作，行酒賦詩殊未央。","衰老應爲難離別，賢聲此去有輝光。","預傳籍籍新京尹，青史無勞數趙張。"]', '["秋日野亭千橘香，玉盤錦席高云涼。","主人送客何所作，行酒賦诗殊未央。","衰老應爲难離別，賢声此去有輝光。","預傳籍籍新京尹，青史無勞數趙張。"]', '诗', 'shi', '', NULL, '章梓州橘亭餞成都竇少尹 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfcaab39-5c64-4eba-911e-2dec1cedc259', '送陵州路使君赴任', '送陵州路使君赴任', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["王室比多難，高官皆武臣。","幽燕通使者，岳牧用詞人。","國待賢良急，君當拔擢新。","佩刀成氣象，行蓋出風塵。","戰伐乾坤破，瘡痍府庫貧。","衆僚宜潔白，萬役但平均。","霄漢瞻佳士，泥途任此身。","秋天正搖落，迴首大江濱。"]', '["王室比多难，高官皆武臣。","幽燕通使者，岳牧用词人。","国待賢良急，君當拔擢新。","佩刀成氣象，行蓋出风塵。","戰伐乾坤破，瘡痍府庫貧。","衆僚宜潔白，万役但平均。","霄漢瞻佳士，泥途任此身。","秋天正搖落，迴首大江濱。"]', '诗', 'shi', '', NULL, '送陵州路使君赴任 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3de9c519-a79d-41d1-9750-53ac57588765', '薄暮', '薄暮', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["江水長流地，山雲薄暮時。","寒花隱亂草，宿鳥擇深枝。","舊國見何日，高秋心苦悲。","人生不再好，鬢髮白成絲。"]', '["江水长流地，山云薄暮时。","寒花隐亂草，宿鸟擇深枝。","旧国见何日，高秋心苦悲。","人生不再好，鬢髮白成絲。"]', '诗', 'shi', '', NULL, '薄暮 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d95a8c6-e757-4b75-8c96-a3506d6c7c6f', '西山三首 一', '西山三首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["彝界荒山頂，蕃州積雪邊。","築城依白帝，轉粟上青天。","蜀將分旗鼓，羌兵助井泉。","西戎背和好，殺氣日相纏。"]', '["彝界荒山頂，蕃州積雪邊。","築城依白帝，轉粟上青天。","蜀將分旗鼓，羌兵助井泉。","西戎背和好，殺氣日相纏。"]', '诗', 'shi', '', NULL, '西山三首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0a261d6-76ee-446e-b25d-3fd213d0ddbc', '西山三首 二', '西山三首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["辛苦三城戍，長防萬里秋。","煙塵浸火井，雨雪閉松州。","風動將軍幕，天寒使者裘。","漫山賊營壘，迴首得無憂。"]', '["辛苦三城戍，长防万里秋。","煙塵浸火井，雨雪閉松州。","风动將軍幕，天寒使者裘。","漫山賊營壘，迴首得無憂。"]', '诗', 'shi', '', NULL, '西山三首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23b089b2-2b63-471c-aaac-952b04185e5b', '西山三首 三', '西山三首 三', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["子弟猶深入，關城未解圍。","蠶崖鐵馬瘦，灌口米船稀。","辯士安邊策，元戎決勝威。","今朝烏鵲喜，欲報凱歌歸。"]', '["子弟猶深入，关城未解圍。","蠶崖鐵马瘦，灌口米船稀。","辯士安邊策，元戎決勝威。","今朝烏鵲喜，欲報凱歌归。"]', '诗', 'shi', '', NULL, '西山三首 三 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7cec2aa6-8090-476f-bdbb-aaaa8aecf58c', '薄遊', '薄游', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["淅淅風生砌，團團日隱牆。","遙空秋鴈滅，半嶺暮雲長。","病葉多先墜，寒花只暫香。","巴城添淚眼，今夜復清光。"]', '["淅淅风生砌，團團日隐牆。","遙空秋鴈滅，半嶺暮云长。","病葉多先墜，寒花只暫香。","巴城添泪眼，今夜复清光。"]', '诗', 'shi', '', NULL, '薄遊 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf516a51-e7a6-4240-a5be-5deae79afe96', '贈韋贊善別', '贈韋贊善別', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["扶病送君發，自憐猶不歸。","秪應盡客淚，復作掩荆扉。","江漢故人少，音書從此稀。","往還二十載，歲晚寸心違。"]', '["扶病送君發，自怜猶不归。","秪應尽客泪，复作掩荆扉。","江漢故人少，音书從此稀。","往還二十載，歲晚寸心違。"]', '诗', 'shi', '', NULL, '贈韋贊善別 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a994e456-ce7d-4226-b287-10e41612b718', '送李卿嘩', '送李卿嘩', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["王子思歸日，長安已亂兵。","霑衣問行在，走馬向承明。","暮景巴蜀僻，春風江漢清。","晉山雖自棄，魏闕尚含情。"]', '["王子思归日，长安已亂兵。","霑衣问行在，走马向承明。","暮景巴蜀僻，春风江漢清。","晉山雖自棄，魏闕尚含情。"]', '诗', 'shi', '', NULL, '送李卿嘩 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc5bb894-c908-405b-8280-571cdb08da82', '絕句', '絕句', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["江邊踏青罷，迴首見旌旗。","風起春城暮，高樓鼓角悲。"]', '["江邊踏青罷，迴首见旌旗。","风起春城暮，高楼鼓角悲。"]', '诗', 'shi', '', NULL, '絕句 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7cb7e51b-c366-4df8-ad63-514d23284330', '城上', '城上', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["草滿巴西綠，空城白日長。","風吹花片片，春動水茫茫。","八駿隨天子，羣臣從武皇。","遙聞出巡守，早晚徧遐荒。"]', '["草满巴西綠，空城白日长。","风吹花片片，春动水茫茫。","八駿隨天子，羣臣從武皇。","遙闻出巡守，早晚徧遐荒。"]', '诗', 'shi', '', NULL, '城上 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd0063b6-941f-409a-b14e-e149d44df3a3', '舍弟占歸草堂檢校聊示此詩', '舍弟占归草堂檢校聊示此诗', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["久客應吾道，相隨獨爾來。","孰知江路近，頻爲草堂迴。","鵝鴨宜長數，柴荆莫浪開。","東林竹影薄，臘月更須栽。"]', '["久客應吾道，相隨独爾来。","孰知江路近，頻爲草堂迴。","鵝鴨宜长數，柴荆莫浪开。","东林竹影薄，臘月更須栽。"]', '诗', 'shi', '', NULL, '舍弟占歸草堂檢校聊示此詩 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf81140d-3582-401f-a17d-87607f23ac91', '傷春五首 一', '傷春五首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["天下兵雖滿，春光日自濃。","西京疲百戰，北闕任羣兇。","關塞三千里，煙花一萬重。","蒙塵清路急，御宿且誰供。","殷復前王道，周遷舊國容。","蓬萊足雲氣，應合總從龍。"]', '["天下兵雖满，春光日自濃。","西京疲百戰，北闕任羣兇。","关塞三千里，煙花一万重。","蒙塵清路急，御宿且誰供。","殷复前王道，周遷旧国容。","蓬萊足云氣，應合總從龙。"]', '诗', 'shi', '', NULL, '傷春五首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49d2767d-7281-4df2-ba8f-36276d5928e4', '傷春五首 二', '傷春五首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["鸎入新年語，花開滿故枝。","天青風捲幔，草碧水通池。","牢落官軍速，蕭條萬事危。","鬢毛元自白，淚點向來垂。","不是無兄弟，其如有別離。","巴山春色靜，北望轉逶迤。"]', '["鸎入新年語，花开满故枝。","天青风捲幔，草碧水通池。","牢落官軍速，蕭條万事危。","鬢毛元自白，泪点向来垂。","不是無兄弟，其如有別離。","巴山春色静，北望轉逶迤。"]', '诗', 'shi', '', NULL, '傷春五首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bd8927c-c929-4a2d-98d9-d6c31a8a8378', '傷春五首 三', '傷春五首 三', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["日月還相鬬，星辰屢合圍。","不成誅執法，焉得變危機。","大角纏兵氣，鉤陳出帝畿。","煙塵昏御道，耆舊把天衣。","行在諸軍闕，來朝大將稀。","賢多隱屠釣，王肯載同歸。"]', '["日月還相鬬，星辰屢合圍。","不成誅執法，焉得变危機。","大角纏兵氣，鉤陳出帝畿。","煙塵昏御道，耆旧把天衣。","行在諸軍闕，来朝大將稀。","賢多隐屠釣，王肯載同归。"]', '诗', 'shi', '', NULL, '傷春五首 三 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97239505-e2b5-49d0-aa4a-d3a91d939622', '傷春五首 四', '傷春五首 四', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["再有朝廷亂，難知消息真。","近傳王在洛，復道使歸秦。","奪馬悲公主，登車泣貴嬪。","蕭關迷北上，滄海欲東巡。","敢料安危體，猶多老大臣。","豈無嵇紹血，霑灑屬車塵。"]', '["再有朝廷亂，难知消息真。","近傳王在洛，复道使归秦。","奪马悲公主，登车泣貴嬪。","蕭关迷北上，滄海欲东巡。","敢料安危體，猶多老大臣。","豈無嵇紹血，霑灑屬车塵。"]', '诗', 'shi', '', NULL, '傷春五首 四 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7bb9666-5122-4a9e-8fb6-404217f2db34', '傷春五首 五', '傷春五首 五', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["聞說初東幸，孤兒却走多。","難分太倉粟，競棄魯陽戈。","胡虜登前殿，王公出御河。","得無中夜舞，誰憶大風歌。","春色生烽燧，幽人泣薜蘿。","君臣重修德，猶足見時和。"]', '["闻说初东幸，孤兒却走多。","难分太倉粟，競棄魯陽戈。","胡虜登前殿，王公出御河。","得無中夜舞，誰憶大风歌。","春色生烽燧，幽人泣薜蘿。","君臣重修德，猶足见时和。"]', '诗', 'shi', '', NULL, '傷春五首 五 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d27b426-ebfa-44d6-9574-86c1dfe83093', '王閬州筵奉酬十一舅惜別之作', '王閬州筵奉酬十一舅惜別之作', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["萬壑樹聲滿，千崖秋氣高。","浮舟出郡郭，別酒寄江濤。","良會不復久，此生何太勞。","窮愁但有骨，羣盜尚如毛。","吾舅惜分手，使君寒贈袍。","沙頭暮黃鴣，失侶自哀號。"]', '["万壑樹声满，千崖秋氣高。","浮舟出郡郭，別酒寄江濤。","良會不复久，此生何太勞。","窮愁但有骨，羣盜尚如毛。","吾舅惜分手，使君寒贈袍。","沙头暮黄鴣，失侶自哀號。"]', '诗', 'shi', '', NULL, '王閬州筵奉酬十一舅惜別之作 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23834280-4f62-49ac-ba7b-1c27752825fc', '放船', '放船', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["送客蒼溪縣，山寒雨不開。","直愁騎馬滑，故作泛舟迴。","青惜峰巒過，黃知橘柚來。","江流大自在，坐穩興悠哉。"]', '["送客蒼溪縣，山寒雨不开。","直愁騎马滑，故作泛舟迴。","青惜峰巒過，黄知橘柚来。","江流大自在，坐穩兴悠哉。"]', '诗', 'shi', '', NULL, '放船 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d883f11d-db2f-4729-b587-b378f3a6a133', '奉待嚴大夫', '奉待嚴大夫', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["殊方又喜故人來，重鎮還須濟世才。","常怪偏裨終日待，不知旌節隔年迴。","欲辭巴徼啼鶯合，遠下旌門去鷁催。","身老時危思會面，一生襟抱向誰開。"]', '["殊方又喜故人来，重鎮還須濟世才。","常怪偏裨終日待，不知旌節隔年迴。","欲辞巴徼啼鶯合，远下旌门去鷁催。","身老时危思會面，一生襟抱向誰开。"]', '诗', 'shi', '', NULL, '奉待嚴大夫 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ffb52c7-3cf0-4d4b-939c-9497851ab6bd', '奉寄高常侍', '奉寄高常侍', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["汶上相逢年頗多，飛騰無那故人何。","總戎楚蜀應全未，方駕曹劉不啻過。","今日朝廷須汲黯，中原將帥憶廉頗。","天涯春色催遲暮，別淚遙添錦水波。"]', '["汶上相逢年頗多，飞腾無那故人何。","總戎楚蜀應全未，方駕曹劉不啻過。","今日朝廷須汲黯，中原將帥憶廉頗。","天涯春色催遲暮，別泪遙添錦水波。"]', '诗', 'shi', '', NULL, '奉寄高常侍 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1df24506-ebde-45a0-9d0d-d449f1020b3b', '奉寄章十侍御', '奉寄章十侍御', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["淮海維揚一俊人，金章紫綬照青春。","指麾能事迴天地，訓練強兵動鬼神。","湘西不得歸關羽，河內猶宜借寇恂。","朝覲從容問幽仄，勿云江漢有垂綸。"]', '["淮海維揚一俊人，金章紫綬照青春。","指麾能事迴天地，訓練強兵动鬼神。","湘西不得归关羽，河內猶宜借寇恂。","朝覲從容问幽仄，勿云江漢有垂綸。"]', '诗', 'shi', '', NULL, '奉寄章十侍御 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34be343f-1efd-450f-a5c8-e99c08600aed', '將赴荆南寄別李劒州', '將赴荆南寄別李劒州', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["使君高義驅今古，寥落三年坐劒州。","但見文翁能化俗，焉知李廣未封侯。","路經灧澦雙蓬鬢，天入滄浪一釣舟。","戎馬相逢更何日，春風迴首仲宣樓。"]', '["使君高義驱今古，寥落三年坐劒州。","但见文翁能化俗，焉知李廣未封侯。","路經灧澦雙蓬鬢，天入滄浪一釣舟。","戎马相逢更何日，春风迴首仲宣楼。"]', '诗', 'shi', '', NULL, '將赴荆南寄別李劒州 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ab03240-492d-44fa-b967-00441fb20900', '奉寄別馬巴州', '奉寄別马巴州', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["勳業終歸馬伏波，功曹非復漢蕭何。","扁舟繫纜沙邊久，南國浮雲水上多。","獨把魚竿終遠去，難隨鳥翼一相過。","知君未愛春湖色，興在驪駒白玉珂。"]', '["勳業終归马伏波，功曹非复漢蕭何。","扁舟繫纜沙邊久，南国浮云水上多。","独把鱼竿終远去，难隨鸟翼一相過。","知君未愛春湖色，兴在驪駒白玉珂。"]', '诗', 'shi', '', NULL, '奉寄別馬巴州 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d2d7846-56ad-418c-a6e2-6f8e5f490c4b', '泛江', '泛江', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["方舟不用楫，極目總無波。","長日容盃酒，深江淨綺羅。","亂離還奏樂，飄泊且聽歌。","故國流清渭，如今花正多。"]', '["方舟不用楫，極目總無波。","长日容盃酒，深江淨綺羅。","亂離還奏乐，飄泊且听歌。","故国流清渭，如今花正多。"]', '诗', 'shi', '', NULL, '泛江 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4856804-965c-40d0-a54d-5379ace1d95c', '陪王使君晦日泛江就黃家亭子二首 一', '陪王使君晦日泛江就黄家亭子二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["山豁何時斷，江平不肯流。","稍知花改岸，始驗鳥隨舟。","結束多紅粉，歡娛恨白頭。","非君愛人客，晦日更添愁。"]', '["山豁何时斷，江平不肯流。","稍知花改岸，始驗鸟隨舟。","結束多紅粉，歡娛恨白头。","非君愛人客，晦日更添愁。"]', '诗', 'shi', '', NULL, '陪王使君晦日泛江就黃家亭子二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfefd449-c8d9-4b64-b391-480f64682615', '陪王使君晦日泛江就黃家亭子二首 二', '陪王使君晦日泛江就黄家亭子二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["有徑金沙軟，無人碧草芳。","野畦連蛺蝶，江檻俯鴛鴦。","日晚煙花亂，風生錦繡香。","不須吹急管，衰老易悲傷。"]', '["有徑金沙軟，無人碧草芳。","野畦連蛺蝶，江檻俯鴛鴦。","日晚煙花亂，风生錦繡香。","不須吹急管，衰老易悲傷。"]', '诗', 'shi', '', NULL, '陪王使君晦日泛江就黃家亭子二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('251a7dea-9d42-445d-84de-39a9b71b8bcf', '南征', '南征', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["春岸桃花水，雲帆楓樹林。","偷生長避地，適遠更霑襟。","老病南征日，君恩北望心。","百年歌自苦，未見有知音。"]', '["春岸桃花水，云帆楓樹林。","偷生长避地，適远更霑襟。","老病南征日，君恩北望心。","百年歌自苦，未见有知音。"]', '诗', 'shi', '', NULL, '南征 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87334352-82e2-40c3-84b4-ab78ae38e411', '久客', '久客', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["羈旅知交態，淹留見俗情。","衰顏聊自哂，小吏最相輕。","去國哀王粲，傷時哭賈生。","狐狸何足道，豺虎正縱橫。"]', '["羈旅知交態，淹留见俗情。","衰顏聊自哂，小吏最相轻。","去国哀王粲，傷时哭賈生。","狐狸何足道，豺虎正縱橫。"]', '诗', 'shi', '', NULL, '久客 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3735888b-0625-49aa-bd0b-22b38bb81c92', '春遠', '春远', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["肅肅花絮晚，菲菲紅素輕。","日長唯鳥雀，春遠獨柴荆。","數有關中亂，何曾劒外清。","故鄉歸不得，地入亞夫營。"]', '["肅肅花絮晚，菲菲紅素轻。","日长唯鸟雀，春远独柴荆。","數有关中亂，何曾劒外清。","故乡归不得，地入亞夫營。"]', '诗', 'shi', '', NULL, '春遠 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8bd9e71-19f2-405b-b654-c5501a8d9acb', '暮寒', '暮寒', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["霧隱平郊樹，風含廣岸波。","沈沈春色靜，慘慘暮寒多。","戍鼓猶長擊，林鸎遂不歌。","忽思高宴會，朱袖拂雲和。"]', '["霧隐平郊樹，风含廣岸波。","沈沈春色静，慘慘暮寒多。","戍鼓猶长擊，林鸎遂不歌。","忽思高宴會，朱袖拂云和。"]', '诗', 'shi', '', NULL, '暮寒 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2cf02e5-3f41-4a70-a202-6e16c3b8d59c', '雙鷰', '雙鷰', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["旅食驚雙鷰，銜泥入此堂。","應同避燥濕，且復過炎涼。","養子風塵際，來時道路長。","今秋天地在，吾亦離殊方。"]', '["旅食驚雙鷰，銜泥入此堂。","應同避燥濕，且复過炎涼。","養子风塵際，来时道路长。","今秋天地在，吾亦離殊方。"]', '诗', 'shi', '', NULL, '雙鷰 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1232ea58-6d47-4e23-a8b3-0c1181aa1afc', '百舌', '百舌', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["百舌來何處，重重祗報春。","知音兼衆語，整翮豈多身。","花密藏難見，枝高聽轉新。","過時如發口，君側有讒人。"]', '["百舌来何处，重重祗報春。","知音兼衆語，整翮豈多身。","花密藏难见，枝高听轉新。","過时如發口，君側有讒人。"]', '诗', 'shi', '', NULL, '百舌 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2357d9c-7e63-41e4-a3c6-cd71d0117881', '地隅', '地隅', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["江漢山重阻，風雲地一隅。","年年非故物，處處是窮途。","喪亂秦公子，悲涼楚大夫。","平生心已折，行路日荒蕪。"]', '["江漢山重阻，风云地一隅。","年年非故物，处处是窮途。","喪亂秦公子，悲涼楚大夫。","平生心已折，行路日荒蕪。"]', '诗', 'shi', '', NULL, '地隅 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3aed731e-5ee5-45d4-a3d0-26c8d2ff8dc5', '游子', '游子', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["巴蜀愁誰語，吳門興杳然。","九江春草外，三峽暮帆前。","厭就成都卜，休爲吏部眠。","蓬萊如可到，衰白問羣仙。"]', '["巴蜀愁誰語，吳门兴杳然。","九江春草外，三峽暮帆前。","厭就成都卜，休爲吏部眠。","蓬萊如可到，衰白问羣仙。"]', '诗', 'shi', '', NULL, '游子 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c89b78bc-576e-40b0-923d-916d181cf73d', '歸夢', '归梦', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["道路時通塞，江山日寂寥。","偷生唯一老，伐叛已三朝。","雨急青楓暮，雲深黑水遙。","夢歸歸未得，不用楚辭招。"]', '["道路时通塞，江山日寂寥。","偷生唯一老，伐叛已三朝。","雨急青楓暮，云深黑水遙。","梦归归未得，不用楚辞招。"]', '诗', 'shi', '', NULL, '歸夢 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29556155-b2af-48ef-b0d4-3d38b02d7a48', '江亭王閬州筵餞蕭遂州', '江亭王閬州筵餞蕭遂州', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["離亭非舊國，春色是他鄉。","老畏歌聲斷，愁隨舞曲長。","二天開寵餞，五馬爛生光。","川路風煙接，俱宜下鳳皇。"]', '["離亭非旧国，春色是他乡。","老畏歌声斷，愁隨舞曲长。","二天开寵餞，五马爛生光。","川路风煙接，俱宜下鳳皇。"]', '诗', 'shi', '', NULL, '江亭王閬州筵餞蕭遂州 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c55ccfa6-8820-40b0-90ff-79412f03c7a8', '絕句二首 一', '絕句二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["遲日江山麗，春風花草香。","泥融飛燕子，沙暖睡鴛鴦。"]', '["遲日江山丽，春风花草香。","泥融飞燕子，沙暖睡鴛鴦。"]', '诗', 'shi', '', NULL, '絕句二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d38fe4da-790a-4eaa-b357-360d49d02bd7', '絕句二首 二', '絕句二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["江碧鳥逾白，山青花欲燃。"]', '["江碧鸟逾白，山青花欲燃。"]', '诗', 'shi', '', NULL, '絕句二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1546bb1b-8d81-403c-b807-9b5a798fc65e', '滕王亭子', '滕王亭子', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["君王臺榭枕巴山，萬丈丹梯尚可攀。","春日鸎啼脩竹裏，仙家犬吠白雲間。","清江錦石傷心麗，嫩蘂濃花滿目班。","人到於今歌出牧，來遊此地不知還。"]', '["君王台榭枕巴山，万丈丹梯尚可攀。","春日鸎啼脩竹裏，仙家犬吠白云间。","清江錦石傷心丽，嫩蘂濃花满目班。","人到於今歌出牧，来游此地不知還。"]', '诗', 'shi', '', NULL, '滕王亭子 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8500c5b-349d-41e5-b495-7b8ef514f191', '玉臺觀', '玉台观', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["中天積翠玉臺遙，上帝高居絳節朝。","遂有馮夷來擊鼓，始知嬴女善吹簫。","江光隱見黿鼉窟，石勢參差烏鵲橋。","更肯紅顏生羽翼，便應黃髮老漁樵。"]', '["中天積翠玉台遙，上帝高居絳節朝。","遂有馮夷来擊鼓，始知嬴女善吹簫。","江光隐见黿鼉窟，石勢參差烏鵲橋。","更肯紅顏生羽翼，便應黄髮老漁樵。"]', '诗', 'shi', '', NULL, '玉臺觀 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d66f1624-d12b-41ca-b51d-b90d430bf734', '滕王亭子', '滕王亭子', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["寂寞春山路，君王不復行。","古牆猶竹色，虛閣自松聲。","鳥雀荒村暮，雲霞過客情。","尚思歌吹入，千騎把霓旌。"]', '["寂寞春山路，君王不复行。","古牆猶竹色，虛閣自松声。","鸟雀荒村暮，云霞過客情。","尚思歌吹入，千騎把霓旌。"]', '诗', 'shi', '', NULL, '滕王亭子 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('009701aa-5f62-4c7c-b0d7-c7a195709dd9', '玉臺觀', '玉台观', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["浩劫因王造，平臺訪古遊。","綵雲蕭史駐，文字魯恭留。","宮闕通羣帝，乾坤到十洲。","人傳有笙鶴，時過此山頭。"]', '["浩劫因王造，平台訪古游。","綵云蕭史駐，文字魯恭留。","宮闕通羣帝，乾坤到十洲。","人傳有笙鹤，时過此山头。"]', '诗', 'shi', '', NULL, '玉臺觀 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d10fbfdb-8ed3-4bbc-8e9b-d42b59a97ad9', '渡江', '渡江', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["春江不可渡，二月已風濤。","舟楫欹斜疾，魚龍偃臥高。","渚花兼素錦，汀草亂青袍。","戲問垂綸客，悠悠見汝曹。"]', '["春江不可渡，二月已风濤。","舟楫欹斜疾，鱼龙偃臥高。","渚花兼素錦，汀草亂青袍。","戲问垂綸客，悠悠见汝曹。"]', '诗', 'shi', '', NULL, '渡江 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('642a76f7-5cef-4296-a804-1e9c47694e42', '喜雨', '喜雨', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["南國旱無雨，今朝江出雲。","入空纔漠漠，灑迥已紛紛。","巢燕高飛盡，林花潤色分。","晚來聲不絕，應得夜深聞。"]', '["南国旱無雨，今朝江出云。","入空纔漠漠，灑迥已紛紛。","巢燕高飞尽，林花潤色分。","晚来声不絕，應得夜深闻。"]', '诗', 'shi', '', NULL, '喜雨 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d99511b-3c00-46f9-9f6a-142a52914f9e', '送韋郎司直歸成都', '送韋郎司直归成都', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["竄身來蜀地，同病得韋郎。","天下干戈滿，江邊歲月長。","別筵花欲暮，春日鬢俱蒼。","爲問南溪竹，抽梢合過墻。"]', '["竄身来蜀地，同病得韋郎。","天下干戈满，江邊歲月长。","別筵花欲暮，春日鬢俱蒼。","爲问南溪竹，抽梢合過墻。"]', '诗', 'shi', '', NULL, '送韋郎司直歸成都 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d61e94df-d121-4e6e-93c4-a00ae7135c3e', '將赴成都草堂途中有作先寄嚴鄭公五首 一', '將赴成都草堂途中有作先寄嚴鄭公五首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["得歸茅屋赴成都，直爲文翁再剖符。","但使閭閻還揖讓，敢論松竹久荒蕪。","魚知丙穴由來美酒憶郫筒不用酤。","五馬舊曾諳小徑，幾回書札待潛夫。"]', '["得归茅屋赴成都，直爲文翁再剖符。","但使閭閻還揖讓，敢論松竹久荒蕪。","鱼知丙穴由来美酒憶郫筒不用酤。","五马旧曾諳小徑，幾回书札待潛夫。"]', '诗', 'shi', '', NULL, '將赴成都草堂途中有作先寄嚴鄭公五首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8138a2d0-cd03-4430-95cf-487daa5d6902', '將赴成都草堂途中有作先寄嚴鄭公五首 二', '將赴成都草堂途中有作先寄嚴鄭公五首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["處處青江帶白蘋，故園猶得見殘春。","雪山斥候無兵馬，錦里逢迎有主人。","休怪兒童延俗客，不教鵝鴨惱比鄰。","習池未覺風流盡，況復旌州賞更新。"]', '["处处青江带白蘋，故园猶得见殘春。","雪山斥候無兵马，錦里逢迎有主人。","休怪兒童延俗客，不教鵝鴨惱比鄰。","習池未覺风流尽，況复旌州賞更新。"]', '诗', 'shi', '', NULL, '將赴成都草堂途中有作先寄嚴鄭公五首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49fc2b80-a407-453f-8ba7-1d03786dcf70', '將赴成都草堂途中有作先寄嚴鄭公五首 三', '將赴成都草堂途中有作先寄嚴鄭公五首 三', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["竹寒沙碧浣花溪，菱刺藤梢咫尺迷。","過客徑須愁出入，居人不自解東西。","書籤藥裏封蛛網，野店山橋送馬蹄。","豈藉荒庭春草色，先判一飲醉如泥。"]', '["竹寒沙碧浣花溪，菱刺藤梢咫尺迷。","過客徑須愁出入，居人不自解东西。","书籤藥裏封蛛網，野店山橋送马蹄。","豈藉荒庭春草色，先判一饮醉如泥。"]', '诗', 'shi', '', NULL, '將赴成都草堂途中有作先寄嚴鄭公五首 三 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0acd2d0-4a13-4846-a376-ef98cd6adc8a', '將赴成都草堂途中有作先寄嚴鄭公五首 四', '將赴成都草堂途中有作先寄嚴鄭公五首 四', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["常苦沙崩損藥欄，也從江檻落風湍。","新松恨不高千尺，惡竹應須斬萬竿。","生理祗憑黃閣老，衰顏欲付紫金丹。","三年奔走空皮骨，信有人間行路難。"]', '["常苦沙崩損藥欄，也從江檻落风湍。","新松恨不高千尺，惡竹應須斬万竿。","生理祗憑黄閣老，衰顏欲付紫金丹。","三年奔走空皮骨，信有人间行路难。"]', '诗', 'shi', '', NULL, '將赴成都草堂途中有作先寄嚴鄭公五首 四 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5165a927-d370-4d22-859a-b990ed586169', '將赴成都草堂途中有作先寄嚴鄭公五首 五', '將赴成都草堂途中有作先寄嚴鄭公五首 五', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["錦官城西生事微，烏皮几在還思歸。","昔去爲憂亂兵入，今來已恐鄰人非。","側身天地更懷古，迴首風塵甘息機。","共說總戎雲鳥陣，不妨遊子芰荷衣。"]', '["錦官城西生事微，烏皮几在還思归。","昔去爲憂亂兵入，今来已恐鄰人非。","側身天地更懷古，迴首风塵甘息機。","共说總戎云鸟陣，不妨游子芰荷衣。"]', '诗', 'shi', '', NULL, '將赴成都草堂途中有作先寄嚴鄭公五首 五 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c19e64b1-604b-40b7-9e41-6ef57b9c6f7b', '別房太尉墓', '別房太尉墓', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["他鄉復行役，駐馬別孤墳。","近淚無乾土，低空有斷雲。","對碁陪謝傅，把劒覓徐君。","唯見林花落，鸎啼送客聞。"]', '["他乡复行役，駐马別孤墳。","近泪無乾土，低空有斷云。","对碁陪謝傅，把劒覓徐君。","唯见林花落，鸎啼送客闻。"]', '诗', 'shi', '', NULL, '別房太尉墓 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03888191-1fe8-46a6-b8d4-49d65adde905', '自閬州領妻子却赴蜀州山行三首 一', '自閬州領妻子却赴蜀州山行三首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["汨汨避羣盜，悠悠經十年。","不成向南國，復作遊西川。","物役水虛照，魂傷山寂然。","我生無倚著，盡室畏途邊。"]', '["汨汨避羣盜，悠悠經十年。","不成向南国，复作游西川。","物役水虛照，魂傷山寂然。","我生無倚著，尽室畏途邊。"]', '诗', 'shi', '', NULL, '自閬州領妻子却赴蜀州山行三首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('598342f1-e4d1-45d1-b813-6aa0cac1ce52', '自閬州領妻子却赴蜀州山行三首 二', '自閬州領妻子却赴蜀州山行三首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["長林偃風色，迴復意猶迷。","衫裛翠微潤，馬銜青草嘶。","棧縣斜避石，橋斷却尋溪。","何日干戈盡，飄飄媿老妻。"]', '["长林偃风色，迴复意猶迷。","衫裛翠微潤，马銜青草嘶。","棧縣斜避石，橋斷却尋溪。","何日干戈尽，飄飄媿老妻。"]', '诗', 'shi', '', NULL, '自閬州領妻子却赴蜀州山行三首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3678278c-bddf-4639-837c-45fa64d6b28b', '自閬州領妻子却赴蜀州山行三首 三', '自閬州領妻子却赴蜀州山行三首 三', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["行色遞隱見，人煙時有無。","僕夫穿竹語，稚子入雲呼。","轉石驚魑魅，抨弓落狖鼯。","真供一笑樂，似欲慰窮途。"]', '["行色遞隐见，人煙时有無。","僕夫穿竹語，稚子入云呼。","轉石驚魑魅，抨弓落狖鼯。","真供一笑乐，似欲慰窮途。"]', '诗', 'shi', '', NULL, '自閬州領妻子却赴蜀州山行三首 三 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41d75b9e-6d29-4ba1-8d86-334eded1d58e', '山館', '山館', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["南國晝多霧，北風天正寒。","路危行木杪，身遠宿雲端。","山鬼吹燈滅，廚人語夜闌。","雞鳴問前館，世亂敢求安。"]', '["南国晝多霧，北风天正寒。","路危行木杪，身远宿云端。","山鬼吹灯滅，廚人語夜闌。","雞鳴问前館，世亂敢求安。"]', '诗', 'shi', '', NULL, '山館 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7db9a125-9ac8-48a3-a81c-5e61329eaaee', '行次鹽亭縣卿題四韻奉簡嚴遂州蓬州兩使君諮議諸昆季', '行次鹽亭縣卿題四韻奉簡嚴遂州蓬州兩使君諮議諸昆季', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["馬首見鹽亭，高山擁縣青。","雲溪花淡淡，春郭水泠泠。","全蜀多名士，嚴家聚德星。","長歌意無極，好爲老夫聽。"]', '["马首见鹽亭，高山擁縣青。","云溪花淡淡，春郭水泠泠。","全蜀多名士，嚴家聚德星。","长歌意無極，好爲老夫听。"]', '诗', 'shi', '', NULL, '行次鹽亭縣卿題四韻奉簡嚴遂州蓬州兩使君諮議諸昆季 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7cdb4a32-f710-4533-87d3-089684f18062', '倚杖', '倚杖', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["看花雖郭內，倚杖即溪邊。","山縣早休市，江橋春聚船。","狎鷗輕白浪，歸鴈喜青天。","物色兼生意，淒涼憶去年。"]', '["看花雖郭內，倚杖即溪邊。","山縣早休市，江橋春聚船。","狎鷗轻白浪，归鴈喜青天。","物色兼生意，淒涼憶去年。"]', '诗', 'shi', '', NULL, '倚杖 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3b9d6ef-b19c-4429-b799-db527e8907a4', '陪王漢州留杜綿州泛房公西湖', '陪王漢州留杜綿州泛房公西湖', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["舊相恩追後，春池賞不稀。","闕庭分未到，舟楫有光輝。","豉化蓴絲熟，刀鳴[鱠]縷飛。","使君雙皁蓋，灘淺正相依。"]', '["旧相恩追後，春池賞不稀。","闕庭分未到，舟楫有光輝。","豉化蓴絲熟，刀鳴[鱠]縷飞。","使君雙皁蓋，灘淺正相依。"]', '诗', 'shi', '', NULL, '陪王漢州留杜綿州泛房公西湖 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d58ca74-af48-4268-93bb-783f2a2d111f', '舟前小鵝兒', '舟前小鵝兒', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["鵝兒黃似酒，對酒愛新鵝。","引頸嗔船逼，無行亂眼多。","翅開遭宿雨，力小困滄波。","客散層城暮，狐狸奈若何。"]', '["鵝兒黄似酒，对酒愛新鵝。","引頸嗔船逼，無行亂眼多。","翅开遭宿雨，力小困滄波。","客散層城暮，狐狸奈若何。"]', '诗', 'shi', '', NULL, '舟前小鵝兒 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b243693-2a80-43cd-8c64-8c0e520a22ae', '得房公池鵝', '得房公池鵝', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["房相西亭鵝一羣，眠沙泛浦白於雲。","鳳皇池上應迴首，爲報籠隨王右軍。"]', '["房相西亭鵝一羣，眠沙泛浦白於云。","鳳皇池上應迴首，爲報籠隨王右軍。"]', '诗', 'shi', '', NULL, '得房公池鵝 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6203888d-a574-47fa-8171-628b4d9d5155', '荅楊梓州', '荅楊梓州', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["悶到房公池水頭，坐逢楊子鎮東州。","却向青溪不相見，迴船應載阿戎遊。"]', '["悶到房公池水头，坐逢楊子鎮东州。","却向青溪不相见，迴船應載阿戎游。"]', '诗', 'shi', '', NULL, '荅楊梓州 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12919986-2d09-4d2e-b5ad-f2485e40ada5', '登樓', '登楼', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["花近高樓傷客心，萬方多難此登臨。","錦江春色來天地，玉壘浮雲變古今。","北極朝廷終不改，西山寇盜莫相侵。","可憐後主還祠廟，日暮聊爲梁甫吟。"]', '["花近高楼傷客心，万方多难此登臨。","錦江春色来天地，玉壘浮云变古今。","北極朝廷終不改，西山寇盜莫相侵。","可怜後主還祠廟，日暮聊爲梁甫吟。"]', '诗', 'shi', '', NULL, '登樓 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f4ed534-1654-4701-8969-2cdc4c02b58b', '春歸', '春归', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["苔徑臨江竹，茅簷覆地花。","別來頻甲子，倏忽又春華。","倚杖看孤石，傾壺就淺沙。","遠鷗浮水靜，輕鷰受風斜。","世路雖多梗，吾生亦有涯。","此身醒復醉，乘興即爲家。"]', '["苔徑臨江竹，茅簷覆地花。","別来頻甲子，倏忽又春华。","倚杖看孤石，傾壺就淺沙。","远鷗浮水静，轻鷰受风斜。","世路雖多梗，吾生亦有涯。","此身醒复醉，乘兴即爲家。"]', '诗', 'shi', '', NULL, '春歸 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b325248c-fe36-4299-97fc-78e31bac554d', '歸鴈', '归鴈', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["東來萬里客，亂定幾年歸。","腸斷江城鴈，高高正北飛。"]', '["东来万里客，亂定幾年归。","腸斷江城鴈，高高正北飞。"]', '诗', 'shi', '', NULL, '歸鴈 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59f7c852-316a-4a45-838a-923df108a993', '贈王二十四侍御契四十韻', '贈王二十四侍御契四十韻', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["往往雖相見，飄飄媿此身。","不關輕紱冕，俱是避風塵。","一別星橋夜，三移斗柄春。","敗亡非赤壁，奔走爲黃巾。","子去何瀟灑，余藏異隱淪。","書成無過雁，衣故有縣鶉。","恐懼行裝數，伶俜臥疾頻。","曉鸎工迸淚，秋月解傷神。","會面嗟黧黑，含悽話苦辛。","接輿還入楚，王粲不歸秦。","錦里殘丹竈，花溪得釣綸。","消中祗自惜，晚起索誰親。","伏柱聞周史，乘槎有漢臣。","鴛鴻不易狎，龍虎未宜馴。","客則挂冠至，交非傾蓋新。","由來意氣合，直取性情真。","浪跡同生死，無心恥賤貧。","偶然存蔗芋，幸各對松筠。","麤飯依他日，窮愁怪此辰。","女長裁褐穩，男大卷書勻。","漰口江如練，蠶崖雪似銀。","名園當翠巘，野棹沒青蘋。","屢喜王侯宅，時邀江海人。","追隨不覺晚，欵曲動彌旬。","但使芝蘭秀，何煩棟宇鄰。","山陽無俗物，鄭驛正留賓。","出入並鞍馬，光輝參席珍。","重遊先主廟，更歷少城闉。","石鏡通幽魄，琴臺隱絳唇。","送終惟糞土，結愛獨荆榛。","置酒高林下，觀碁積水濱。","區區甘累趼，稍稍息勞筋。","網聚粘圓鯽，絲繁煮細蓴。","長歌敲柳癭，小睡憑藤輪。","農月須知課，田家敢忘勤。","浮生難去食，良會惜清晨。","列國兵戈暗，今王德教淳。","要聞除䝟貐，休作畫麒麟。","洗眼看輕薄，虛懷任屈伸。","莫令膠漆地，萬古重雷陳。"]', '["往往雖相见，飄飄媿此身。","不关轻紱冕，俱是避风塵。","一別星橋夜，三移斗柄春。","敗亡非赤壁，奔走爲黄巾。","子去何瀟灑，余藏異隐淪。","书成無過雁，衣故有縣鶉。","恐懼行裝數，伶俜臥疾頻。","晓鸎工迸泪，秋月解傷神。","會面嗟黧黑，含悽話苦辛。","接輿還入楚，王粲不归秦。","錦里殘丹竈，花溪得釣綸。","消中祗自惜，晚起索誰親。","伏柱闻周史，乘槎有漢臣。","鴛鴻不易狎，龙虎未宜馴。","客則挂冠至，交非傾蓋新。","由来意氣合，直取性情真。","浪跡同生死，無心恥賤貧。","偶然存蔗芋，幸各对松筠。","麤飯依他日，窮愁怪此辰。","女长裁褐穩，男大卷书勻。","漰口江如練，蠶崖雪似銀。","名园當翠巘，野棹沒青蘋。","屢喜王侯宅，时邀江海人。","追隨不覺晚，欵曲动彌旬。","但使芝蘭秀，何煩棟宇鄰。","山陽無俗物，鄭驛正留賓。","出入並鞍马，光輝參席珍。","重游先主廟，更歷少城闉。","石镜通幽魄，琴台隐絳唇。","送終惟糞土，結愛独荆榛。","置酒高林下，观碁積水濱。","區區甘累趼，稍稍息勞筋。","網聚粘圓鯽，絲繁煮細蓴。","长歌敲柳癭，小睡憑藤輪。","農月須知課，田家敢忘勤。","浮生难去食，良會惜清晨。","列国兵戈暗，今王德教淳。","要闻除䝟貐，休作畫麒麟。","洗眼看轻薄，虛懷任屈伸。","莫令膠漆地，万古重雷陳。"]', '诗', 'shi', '', NULL, '贈王二十四侍御契四十韻 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34493244-b343-4762-b07b-f9c0110926ea', '寄董卿嘉榮十韻', '寄董卿嘉榮十韻', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["聞道君牙帳，防秋近赤霄。","下臨千雪嶺，却背五繩橋。","海內久戎服，京師今晏朝。","犬羊曾爛熳，宮闕尚蕭條。","猛將宜嘗膽，龍泉必在腰。","黃圖遭污辱，月窟可焚燒。","會取干戈利，無令斥候驕。","居然雙捕虜，自是一嫖姚。","落日思輕騎，高天憶射雕。","雲臺畫形像，皆爲掃氛妖。"]', '["闻道君牙帳，防秋近赤霄。","下臨千雪嶺，却背五繩橋。","海內久戎服，京師今晏朝。","犬羊曾爛熳，宮闕尚蕭條。","猛將宜嘗膽，龙泉必在腰。","黄圖遭污辱，月窟可焚燒。","會取干戈利，無令斥候驕。","居然雙捕虜，自是一嫖姚。","落日思轻騎，高天憶射雕。","云台畫形像，皆爲掃氛妖。"]', '诗', 'shi', '', NULL, '寄董卿嘉榮十韻 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9340f8a2-3051-48fd-b8a5-09a2669f722b', '寄司馬山人十二韻', '寄司马山人十二韻', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["關內昔分袂，天邊今轉蓬。","驅馳不可說，談笑偶然同。","道術曾留意，先生早擊蒙。","家家迎薊子，處處識壺公。","長嘯峨嵋北，潛行玉壘東。","有時騎猛虎，虛室使仙童。","髮少何勞白，顏衰肯更紅。","望雲悲轗軻，畢景羨沖融。","喪亂形仍役，淒涼信不通。","懸旌要路口，倚劒短亭中。","永作殊方客，殘生一老翁。","相哀骨可換，亦遣馭清風。"]', '["关內昔分袂，天邊今轉蓬。","驱驰不可说，談笑偶然同。","道術曾留意，先生早擊蒙。","家家迎薊子，处处識壺公。","长嘯峨嵋北，潛行玉壘东。","有时騎猛虎，虛室使仙童。","髮少何勞白，顏衰肯更紅。","望云悲轗軻，畢景羨沖融。","喪亂形仍役，淒涼信不通。","懸旌要路口，倚劒短亭中。","永作殊方客，殘生一老翁。","相哀骨可換，亦遣馭清风。"]', '诗', 'shi', '', NULL, '寄司馬山人十二韻 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6aad28c5-dded-4c0c-884f-1c21d25854ef', '黃河二首 一', '黄河二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["黃河北岸海西軍，椎鼓鳴鐘天下聞。","鐵馬長鳴不知數，胡人高鼻動成羣。"]', '["黄河北岸海西軍，椎鼓鳴鐘天下闻。","鐵马长鳴不知數，胡人高鼻动成羣。"]', '诗', 'shi', '', NULL, '黃河二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1913f5e2-b937-40ac-ba4b-ea09007d13e1', '黃河二首 二', '黄河二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["黃河西岸是吾蜀，欲須供給家無粟。","願驅衆蔗戴君王，混一車書棄金玉。"]', '["黄河西岸是吾蜀，欲須供給家無粟。","願驱衆蔗戴君王，混一车书棄金玉。"]', '诗', 'shi', '', NULL, '黃河二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a671ac61-41e6-479a-80fe-f132f6d433dc', '寄李十四員外布十二韻', '寄李十四員外布十二韻', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["名參漢望苑，職述景題輿。","巫峽將之郡，荆門好附書。","遠行無自苦，內熱比何如。","正是炎天闊，那堪野館疎。","黃牛平駕浪，畫鷁上凌虛。","試待盤渦歇，方期解纜初。","悶能過小徑，自爲摘嘉蔬。","渚柳元幽僻，村花不掃除。","宿陰繁素柰，過雨亂紅蕖。","寂寂夏先晚，泠泠風有餘。","江清心可瑩，竹冷髮堪梳。","直作移巾几，秋帆發弊廬。"]', '["名參漢望苑，職述景題輿。","巫峽將之郡，荆门好附书。","远行無自苦，內熱比何如。","正是炎天闊，那堪野館疎。","黄牛平駕浪，畫鷁上凌虛。","試待盤渦歇，方期解纜初。","悶能過小徑，自爲摘嘉蔬。","渚柳元幽僻，村花不掃除。","宿陰繁素柰，過雨亂紅蕖。","寂寂夏先晚，泠泠风有餘。","江清心可瑩，竹冷髮堪梳。","直作移巾几，秋帆發弊廬。"]', '诗', 'shi', '', NULL, '寄李十四員外布十二韻 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8aa9b90a-e380-494c-a312-e82ce2fd95c1', '歸來', '归来', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["客裏有所過，歸來知路難。","開門野鼠走，散帙壁魚乾。","洗杓開新醞，低頭拭小盤。","憑誰給麴蘖，細酌老江干。"]', '["客裏有所過，归来知路难。","开门野鼠走，散帙壁鱼乾。","洗杓开新醞，低头拭小盤。","憑誰給麴蘖，細酌老江干。"]', '诗', 'shi', '', NULL, '歸來 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3881b29-fd35-4459-93c9-80fc02411b53', '王錄事許脩草堂貲不到聊小詰', '王錄事許脩草堂貲不到聊小詰', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["爲嗔王錄事，不寄草堂貲。","昨屬愁春雨，能忘欲漏時。"]', '["爲嗔王錄事，不寄草堂貲。","昨屬愁春雨，能忘欲漏时。"]', '诗', 'shi', '', NULL, '王錄事許脩草堂貲不到聊小詰 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88d481a0-19f1-46f9-8959-6ba465381437', '寄邛州崔錄事', '寄邛州崔錄事', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["邛州崔錄事，聞在果園坊。","久待無消息，終朝有底忙。","應愁江樹遠，怯見野亭荒。","浩蕩風塵外，誰知酒熟香。"]', '["邛州崔錄事，闻在果园坊。","久待無消息，終朝有底忙。","應愁江樹远，怯见野亭荒。","浩蕩风塵外，誰知酒熟香。"]', '诗', 'shi', '', NULL, '寄邛州崔錄事 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a97b732-79e2-426f-81ac-c16bec77daf2', '過故斛斯校書莊二首 一', '過故斛斯校书莊二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["此老已云歿，鄰人嗟亦休。","竟無宣室召，徒有茂陵求。","妻子寄他食，園林非昔遊。","空餘繐帷在，淅淅野風秋。"]', '["此老已云歿，鄰人嗟亦休。","竟無宣室召，徒有茂陵求。","妻子寄他食，园林非昔游。","空餘繐帷在，淅淅野风秋。"]', '诗', 'shi', '', NULL, '過故斛斯校書莊二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0145ae39-2773-42f7-9287-ea653ce947a7', '過故斛斯校書莊二首 二', '過故斛斯校书莊二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["燕入非旁舍，鷗歸祗故池。","斷橋無復板，臥柳自生枝。","遂有山陽作，多慚鮑叔知。","素交零落盡，白首淚雙垂。"]', '["燕入非旁舍，鷗归祗故池。","斷橋無复板，臥柳自生枝。","遂有山陽作，多慚鲍叔知。","素交零落尽，白首泪雙垂。"]', '诗', 'shi', '', NULL, '過故斛斯校書莊二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('322046c5-fbdd-4d0d-b085-51250f255e61', '立秋雨院中有作', '立秋雨院中有作', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["山雲行絕塞，大火復西流。","飛雨動華屋，蕭蕭梁棟秋。","窮途媿知己，暮齒借前籌。","已費清晨謁，那成長者謀。","解衣開北戶，高枕對南樓。","樹濕風涼進，江喧水氣浮。","禮寬心有適，節爽病微瘳。","主將歸調鼎，吾還訪舊丘。"]', '["山云行絕塞，大火复西流。","飞雨动华屋，蕭蕭梁棟秋。","窮途媿知己，暮齒借前籌。","已費清晨謁，那成长者謀。","解衣开北戶，高枕对南楼。","樹濕风涼進，江喧水氣浮。","禮寬心有適，節爽病微瘳。","主將归調鼎，吾還訪旧丘。"]', '诗', 'shi', '', NULL, '立秋雨院中有作 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc9806ac-4ec6-43fa-b84d-f9502d5c8aa9', '奉和嚴大夫軍城早秋', '奉和嚴大夫軍城早秋', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["秋風褭褭動高旌，玉帳分弓射虜營。","已收滴博雲間戍，更奪蓬婆雪外城。"]', '["秋风褭褭动高旌，玉帳分弓射虜營。","已收滴博云间戍，更奪蓬婆雪外城。"]', '诗', 'shi', '', NULL, '奉和嚴大夫軍城早秋 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7cdb6ea4-8134-4ac9-a201-952fec088296', '院中晚晴懷西郭茅舍', '院中晚晴懷西郭茅舍', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["幕府秋風日夜清，澹雲疎雨過高城。","葉心朱實看時落，階面青苔先自生。","復有樓臺銜暮景，不勞鐘鼓報新晴。","浣花溪裏花饒笑，肯信吾兼吏隱名。"]', '["幕府秋风日夜清，澹云疎雨過高城。","葉心朱實看时落，階面青苔先自生。","复有楼台銜暮景，不勞鐘鼓報新晴。","浣花溪裏花饒笑，肯信吾兼吏隐名。"]', '诗', 'shi', '', NULL, '院中晚晴懷西郭茅舍 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b67cee37-9190-4581-89ec-473df5ef0c6f', '到村', '到村', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["碧澗雖多雨，秋沙先少泥。","蛟龍引子過，荷芰逐花低。","老去參戎幕，歸來散馬蹄。","稻粱須就列，榛草即相迷。","蓄積思江漢，疎頑惑町畦。","稍酬知己分，還入故林棲。"]', '["碧澗雖多雨，秋沙先少泥。","蛟龙引子過，荷芰逐花低。","老去參戎幕，归来散马蹄。","稻粱須就列，榛草即相迷。","蓄積思江漢，疎頑惑町畦。","稍酬知己分，還入故林棲。"]', '诗', 'shi', '', NULL, '到村 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f540f519-e3c4-41c2-b299-f1d255977705', '宿府', '宿府', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["清秋幕府井梧寒，獨宿江城蠟炬殘。","永夜角聲悲自語，中天月色好誰看。","風塵荏苒音書絕，關塞蕭條行路難。","已忍伶俜十年事，強移栖息一枝安。"]', '["清秋幕府井梧寒，独宿江城蠟炬殘。","永夜角声悲自語，中天月色好誰看。","风塵荏苒音书絕，关塞蕭條行路难。","已忍伶俜十年事，強移栖息一枝安。"]', '诗', 'shi', '', NULL, '宿府 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9d85d1f-936c-489c-a074-9e2be10e5af6', '遣悶奉呈嚴公二十韻', '遣悶奉呈嚴公二十韻', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["白水魚竿客，清秋鶴髮翁。","胡爲來幕下，秪合在舟中。","黃卷真如律，青袍也自公。","老妻憂坐[痹]，幼女問頭風。","平地專欹倒，分曹失異同。","禮甘衰力就，義忝上官通。","疇昔論詩蚤，光輝仗鉞雄。","寬容存性拙，剪拂念途窮。","露裛思藤架，煙霏想桂叢。","信然龜觸網，直作鳥窺籠。","西嶺紆村北，南江遶舍東。","竹皮寒舊翠，椒實雨新紅。","浪簸船應坼，杯乾甕即空。","藩籬生野徑，斤斧任樵童。","束縛酬知己，蹉跎効小忠。","周防期稍稍，太簡遂悤悤。","曉入朱扉啓，昏歸畫角終。","不成尋別業，未敢息微躬。","烏鵲愁銀漢，駑駘怕錦幪。","會希全物色，時放倚梧桐。"]', '["白水鱼竿客，清秋鹤髮翁。","胡爲来幕下，秪合在舟中。","黄卷真如律，青袍也自公。","老妻憂坐[痹]，幼女问头风。","平地專欹倒，分曹失異同。","禮甘衰力就，義忝上官通。","疇昔論诗蚤，光輝仗鉞雄。","寬容存性拙，剪拂念途窮。","露裛思藤架，煙霏想桂叢。","信然龟觸網，直作鸟窺籠。","西嶺紆村北，南江遶舍东。","竹皮寒旧翠，椒實雨新紅。","浪簸船應坼，杯乾甕即空。","藩籬生野徑，斤斧任樵童。","束縛酬知己，蹉跎効小忠。","周防期稍稍，太簡遂悤悤。","晓入朱扉啓，昏归畫角終。","不成尋別業，未敢息微躬。","烏鵲愁銀漢，駑駘怕錦幪。","會希全物色，时放倚梧桐。"]', '诗', 'shi', '', NULL, '遣悶奉呈嚴公二十韻 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0352351-cbb8-4181-a13c-560a59351f65', '送舍弟頻赴齊州三首 一', '送舍弟頻赴齊州三首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["岷嶺南蠻北，徐關東海西。","此行何日到，送汝萬行啼。","絕域惟高枕，清風獨杖藜。","危時暫相見，衰白意都迷。"]', '["岷嶺南蠻北，徐关东海西。","此行何日到，送汝万行啼。","絕域惟高枕，清风独杖藜。","危时暫相见，衰白意都迷。"]', '诗', 'shi', '', NULL, '送舍弟頻赴齊州三首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63d7c6b3-e7ae-46f9-ba66-a92675741240', '送舍弟頻赴齊州三首 二', '送舍弟頻赴齊州三首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["風塵暗不開，汝去幾時來。","兄弟分離苦，形容老病催。","江通一柱觀，日落望鄉臺。"]', '["风塵暗不开，汝去幾时来。","兄弟分離苦，形容老病催。","江通一柱观，日落望乡台。"]', '诗', 'shi', '', NULL, '送舍弟頻赴齊州三首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d334d8a-642f-4f6d-9dae-a3e4cb7165b3', '送舍弟頻赴齊州三首 三', '送舍弟頻赴齊州三首 三', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["諸姑今海畔，兩弟亦山東。","去傍干戈覓，來看道路通。","短衣防戰地，匹馬逐秋風。","莫作俱流落，長瞻碣石鴻。"]', '["諸姑今海畔，兩弟亦山东。","去傍干戈覓，来看道路通。","短衣防戰地，匹马逐秋风。","莫作俱流落，长瞻碣石鴻。"]', '诗', 'shi', '', NULL, '送舍弟頻赴齊州三首 三 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3b34546-d2b2-45f5-bb3b-177fcb29e35e', '嚴鄭公階下新松', '嚴鄭公階下新松', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["弱質豈自負，移根方爾瞻。","細聲聞玉帳，疎翠近珠簾。","未見紫烟集，虛蒙清露霑。","何當一百丈，欹蓋擁高簷。"]', '["弱質豈自負，移根方爾瞻。","細声闻玉帳，疎翠近珠簾。","未见紫烟集，虛蒙清露霑。","何當一百丈，欹蓋擁高簷。"]', '诗', 'shi', '', NULL, '嚴鄭公階下新松 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2c64cce-66c4-481f-bcce-0b54ff36d87f', '嚴鄭公宅同詠竹', '嚴鄭公宅同詠竹', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["綠竹半含籜，新梢纔出牆。","色侵書帙晚，陰過酒樽涼。","雨洗娟娟淨，風吹細細香。","但令無剪伐，會見拂雲長。"]', '["綠竹半含籜，新梢纔出牆。","色侵书帙晚，陰過酒樽涼。","雨洗娟娟淨，风吹細細香。","但令無剪伐，會见拂云长。"]', '诗', 'shi', '', NULL, '嚴鄭公宅同詠竹 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ac25dea-5343-40b0-92ff-f61969a78556', '奉觀嚴鄭公廳事岷山沱江畫圖十韻', '奉观嚴鄭公廳事岷山沱江畫圖十韻', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["沱水流中座，岷山到此堂。","白波吹粉壁，青嶂插雕梁。","直訝杉松冷，兼疑菱荇香。","雪雲虛點綴，沙草得微茫。","嶺鴈隨毫末，川蜺飲練光。","霏紅洲蘂亂，拂黛石蘿長。","暗谷非關雨，丹楓不爲霜。","秋成玄圃外，景物洞庭旁。","繪事功殊絕，幽襟興激昂。","從來謝太傅，丘壑道難忘。"]', '["沱水流中座，岷山到此堂。","白波吹粉壁，青嶂插雕梁。","直訝杉松冷，兼疑菱荇香。","雪云虛点綴，沙草得微茫。","嶺鴈隨毫末，川蜺饮練光。","霏紅洲蘂亂，拂黛石蘿长。","暗谷非关雨，丹楓不爲霜。","秋成玄圃外，景物洞庭旁。","繪事功殊絕，幽襟兴激昂。","從来謝太傅，丘壑道难忘。"]', '诗', 'shi', '', NULL, '奉觀嚴鄭公廳事岷山沱江畫圖十韻 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dceaa342-8374-4c18-9c45-85943d152c38', '晚秋陪嚴鄭公摩訶池泛舟', '晚秋陪嚴鄭公摩訶池泛舟', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["湍駛風醒酒，船迴霧起隄。","高城秋自落，雜樹晚相迷。","坐觸鴛鴦起，巢傾翡翠低。","莫須驚白鷺，爲伴宿清溪。"]', '["湍駛风醒酒，船迴霧起隄。","高城秋自落，杂樹晚相迷。","坐觸鴛鴦起，巢傾翡翠低。","莫須驚白鷺，爲伴宿清溪。"]', '诗', 'shi', '', NULL, '晚秋陪嚴鄭公摩訶池泛舟 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb25edb2-93ff-438b-9d11-5823c96c0dd4', '初冬', '初冬', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["垂老戎衣窄，歸休寒色深。","漁舟上急水，獵火著高林。","日有習池醉，愁來梁甫吟。","干戈未偃息，出處遂何心。"]', '["垂老戎衣窄，归休寒色深。","漁舟上急水，獵火著高林。","日有習池醉，愁来梁甫吟。","干戈未偃息，出处遂何心。"]', '诗', 'shi', '', NULL, '初冬 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fd3e5b2-168d-4899-b0c9-8e74dc2237ab', '至後', '至後', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["冬至至後日初長，遠在劒南思洛陽。","青袍白馬有何意，金谷銅駝非故鄉。","梅花欲開不自覺，棣蕚一別永相望。","愁極本憑詩遣興，詩成吟詠轉淒涼。"]', '["冬至至後日初长，远在劒南思洛陽。","青袍白马有何意，金谷銅駝非故乡。","梅花欲开不自覺，棣蕚一別永相望。","愁極本憑诗遣兴，诗成吟詠轉淒涼。"]', '诗', 'shi', '', NULL, '至後 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b722208-9e02-4dac-9ec5-979859eea818', '正月三日歸溪上有作簡院內諸公', '正月三日归溪上有作簡院內諸公', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["野外堂依竹，籬邊水向城。","蟻浮仍臘味，鷗泛已春聲。","藥許隣人劚，書從稚子擎。","白頭趨幕府，深覺負平生。"]', '["野外堂依竹，籬邊水向城。","蟻浮仍臘味，鷗泛已春声。","藥許隣人劚，书從稚子擎。","白头趨幕府，深覺負平生。"]', '诗', 'shi', '', NULL, '正月三日歸溪上有作簡院內諸公 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('467b678a-283e-40bd-831c-a90532233f85', '弊廬遣興奉寄嚴公', '弊廬遣兴奉寄嚴公', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["野水平橋路，春沙映竹村。","風輕粉蝶喜，花暖蜜蜂喧。","把酒宜深酌，題詩好細論。","府中瞻暇日，江上憶詞源。","跡忝朝廷舊，情依節制尊。","還思長者轍，恐避席爲門。"]', '["野水平橋路，春沙映竹村。","风轻粉蝶喜，花暖蜜蜂喧。","把酒宜深酌，題诗好細論。","府中瞻暇日，江上憶词源。","跡忝朝廷旧，情依節制尊。","還思长者轍，恐避席爲门。"]', '诗', 'shi', '', NULL, '弊廬遣興奉寄嚴公 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d2b033b-eceb-4425-a345-7116bcdb2f5a', '春日江村五首 一', '春日江村五首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["農務村村急，春流岸岸深。","乾坤萬里眼，時序百年心。","茅屋還堪賦，桃源自可尋。","艱難賤生理，飄泊到如今。"]', '["農務村村急，春流岸岸深。","乾坤万里眼，时序百年心。","茅屋還堪賦，桃源自可尋。","艱难賤生理，飄泊到如今。"]', '诗', 'shi', '', NULL, '春日江村五首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9dd1e11-5396-498a-a228-9afeb720dc41', '春日江村五首 二', '春日江村五首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["迢遞來三蜀，蹉跎有六年。","客身逢故舊，發興自林泉。","過懶從衣結，頻遊任履穿。","藩籬無限景，恣意買江天。"]', '["迢遞来三蜀，蹉跎有六年。","客身逢故旧，發兴自林泉。","過懶從衣結，頻游任履穿。","藩籬無限景，恣意買江天。"]', '诗', 'shi', '', NULL, '春日江村五首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8928378-7719-4940-a9b9-848d78b21d5b', '春日江村五首 三', '春日江村五首 三', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["種竹交加翠，栽桃爛熳紅。","經心石鏡月，到面雪山風。","赤管隨王命，銀章付老翁。","豈知牙齒落，名玷薦賢中。"]', '["種竹交加翠，栽桃爛熳紅。","經心石镜月，到面雪山风。","赤管隨王命，銀章付老翁。","豈知牙齒落，名玷薦賢中。"]', '诗', 'shi', '', NULL, '春日江村五首 三 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22063a2e-01e8-4550-ade4-56e43fe96672', '春日江村五首 四', '春日江村五首 四', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["扶病垂朱紱，歸休步紫苔。","郊扉存晚計，幕府媿羣材。","燕外晴絲卷，鷗邊水葉開。","隣家送魚鼈，問我數能來。"]', '["扶病垂朱紱，归休步紫苔。","郊扉存晚計，幕府媿羣材。","燕外晴絲卷，鷗邊水葉开。","隣家送鱼鼈，问我數能来。"]', '诗', 'shi', '', NULL, '春日江村五首 四 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81144889-f17a-4590-bbeb-5a9fdb7fcf4d', '春日江村五首 五', '春日江村五首 五', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["羣盜哀王粲，中年召賈生。","登樓初有作，前席竟爲榮。","宅入先賢傳，才高處士名。","異時懷二子，春日復含情。"]', '["羣盜哀王粲，中年召賈生。","登楼初有作，前席竟爲榮。","宅入先賢傳，才高处士名。","異时懷二子，春日复含情。"]', '诗', 'shi', '', NULL, '春日江村五首 五 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8379509c-ec9d-4644-9da0-80007c6acfa5', '絕句六首 一', '絕句六首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["日出籬東水，雲生舍北泥。","竹高鳴翡翠，沙僻舞鵾雞。"]', '["日出籬东水，云生舍北泥。","竹高鳴翡翠，沙僻舞鵾雞。"]', '诗', 'shi', '', NULL, '絕句六首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c544b70-ded0-42f3-9bd0-2a5d8e9bb537', '絕句六首 二', '絕句六首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["藹藹花蘂亂，飛飛蜂蝶多。","幽棲身懶動，客至欲如何。"]', '["藹藹花蘂亂，飞飞蜂蝶多。","幽棲身懶动，客至欲如何。"]', '诗', 'shi', '', NULL, '絕句六首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9edc47c9-17a3-4552-adcf-ebe56de05289', '絕句六首 三', '絕句六首 三', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["鑿井交椶葉，開渠斷竹根。","扁舟輕褭纜，小徑曲通村。"]', '["鑿井交椶葉，开渠斷竹根。","扁舟轻褭纜，小徑曲通村。"]', '诗', 'shi', '', NULL, '絕句六首 三 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ed2c62d-92af-4ff1-b54e-f8eea706be9b', '絕句六首 四', '絕句六首 四', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["急雨捎溪足，斜暉轉樹腰。","隔巢黃鳥竝，翻藻白魚跳。"]', '["急雨捎溪足，斜暉轉樹腰。","隔巢黄鸟竝，翻藻白鱼跳。"]', '诗', 'shi', '', NULL, '絕句六首 四 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3905360b-f2f9-49ac-8bee-2b3081665a8a', '絕句六首 五', '絕句六首 五', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["舍下笋穿壁，庭中藤刺簷。","地晴絲冉冉，江白草纖纖。"]', '["舍下笋穿壁，庭中藤刺簷。","地晴絲冉冉，江白草纖纖。"]', '诗', 'shi', '', NULL, '絕句六首 五 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e50791c1-e9ee-4e3f-bc49-1bab0654b7f5', '絕句六首 六', '絕句六首 六', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["江動月移石，溪虛雲傍花。","鳥棲知故道，帆過宿誰家。"]', '["江动月移石，溪虛云傍花。","鸟棲知故道，帆過宿誰家。"]', '诗', 'shi', '', NULL, '絕句六首 六 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d59bd22-bdfc-4105-9379-3be27dab92da', '絕句四首 一', '絕句四首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["堂西長笋別開門，塹北行椒却背村。","梅熟許同朱老喫，松高擬對阮生論。"]', '["堂西长笋別开门，塹北行椒却背村。","梅熟許同朱老喫，松高擬对阮生論。"]', '诗', 'shi', '', NULL, '絕句四首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23a057b3-7f46-441b-855a-2182a3402d5f', '絕句四首 二', '絕句四首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["欲作魚梁雲復湍，因驚四月雨聲寒。","青溪先有蛟龍窟，竹石如山不敢安。"]', '["欲作鱼梁云复湍，因驚四月雨声寒。","青溪先有蛟龙窟，竹石如山不敢安。"]', '诗', 'shi', '', NULL, '絕句四首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abf4daf0-0c7b-4b0c-87a2-2c48097d6a65', '絕句四首 三', '絕句四首 三', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["兩箇黃鸝鳴翠柳，一行白鷺上青天。","窗含西嶺千秋雪，門泊東吳萬里船。"]', '["兩箇黄鸝鳴翠柳，一行白鷺上青天。","窗含西嶺千秋雪，门泊东吳万里船。"]', '诗', 'shi', '', NULL, '絕句四首 三 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e5de1b6-c28a-4201-b8cb-a1072c618eae', '絕句四首 四', '絕句四首 四', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["藥條藥甲潤青青，色過棕亭入草亭。","苗滿空山慙取譽，根居隙地怯成形。"]', '["藥條藥甲潤青青，色過棕亭入草亭。","苗满空山慙取譽，根居隙地怯成形。"]', '诗', 'shi', '', NULL, '絕句四首 四 杜甫 shi');
